/* ============================================================
   chars.js —— 角色美术层（外观专用，不碰任何数值/碰撞/物理）
   大肥鱼：蓝发鲸鱼娘女仆（DeepSeek 的化身，取代原「八哥」士兵）
   小克  ：象牙白瓷装甲 + 珊瑚橙星芒（Claude 的化身，终局 BOSS）
   绘制全部在「脚底为原点、朝 +x」的局部坐标里完成。
   大肥鱼现在是双轨制：物理碰撞盒 h=58 不动，视觉用 96px 的位图立绘
   （见下面 WHALE_VH）—— 横版游戏里角色轮廓本来就该比碰撞体饱满，
   裙摆、长发、呆毛都该溢出。小克仍是纯路径绘制。
   ============================================================ */

/* ============================================================
   姿态图：蹲到底 / 趴到底不再在站姿立绘上变形
   ------------------------------------------------------------
   整张图变形有一个过不去的坎：蹲姿的落差只能从腿里出，而立绘的
   腿只占身高 26%（髋到踝 49.4px / 193px，正常人 47%）。腿不够长，
   膝就得往前顶出去一大截才蹲得低 —— 调了 12 组参数，全读作
   「坐在看不见的椅子上」。分件骨骼也一样：它只能在已有像素里
   搬家具，搬不出本来就画不出来的东西。
   （参考过同类横版射击游戏的资源结构：人物同样是一整张
   texture + 可换的配色/武器层，不是分件骨骼 —— 靠的是每个
   姿态单独一张图。这条路才是这类游戏真正在走的。）

   所以蹲、趴各出一张专门的立绘，这里存的就是它们：
     · 出图：ImageGen 图生图（先把原图放大 6 倍再喂，否则模型会把它
       当成风格参考而不是待编辑的图 —— 会翻方向、变 3/4 视、换画风）
     · 去底：tools/skel/dechecker.js（抠掉被画进像素的棋盘格）
     · 定标：tools/skel/posefix.js（腐蚀去白边 → 按**头盔宽度**缩放。
       按身高缩会把蹲姿撑成和站姿一样高，头宽是唯一不变的参照物）
     · 内嵌：tools/gen-poseart.js

   三张图的物理尺度是一致的，所以下面每张只要 w/h（画幅）就够：
   视觉身高按「相对 192 高的站立立绘」等比换算，不用重标锚点。
   ============================================================ */

/* ==POSEART:BEGIN== */
/* 由 tools/gen-poseart.js 生成，不要手改。
   每张图四样东西：画幅（算宽高比）、视觉身高基准、脚底与掌心在画幅里的
   相对位置。三张图是同一物理尺度出的（按头盔宽度对齐），所以 vh 直接按
   「相对 192 高的站立立绘」等比换算 —— 换一张图不用重标锚点。 */
const POSE_ART = {
  hero: {
    crouch: { w: 91, h: 154, foot: 0.5275, hand: [0.8681, 0.5584],
      src: "data:image/png;base64," },
    prone: { w: 193, h: 111, foot: 0.5078, hand: [0.9223, 0.8649],
      src: "data:image/png;base64," },
  },
};
/* ==POSEART:END== */

/* 姿态图的 Image 对象。data URL 解码是异步的，所以每帧都要问 ready ——
   没解码好就退回老路径，绝不会画出空白。 */
const POSE_IMG = {};
if (typeof Image !== 'undefined') {
  for (const _pk in POSE_ART) {
    POSE_IMG[_pk] = {};
    for (const _qs in POSE_ART[_pk]) {
      const _im = new Image();
      _im.src = POSE_ART[_pk][_qs].src;
      POSE_IMG[_pk][_qs] = _im;
    }
  }
}

/* 换图的阈值。0.5 是两条曲线高度最接近的地方：蹲到一半的站姿被压到约
   86px，蹲图 77px，落差最小；再往后站姿已经压扁得不像腿了。
   趴下同理（半躺的站姿 ≈ 80px，趴图 55.5px，这一档落差本来就大，
   但扑倒只有 0.24 秒，眼睛追不上）。 */
const POSE_SWAP = 0.5;

/* 所有站立立绘的统一基准高。姿态图按这个换算视觉身高，
   所以换一张图不用重标任何锚点。 */
const POSE_BASE_H = 192;

/* 查当前该用哪张姿态图。没有这张图、或者还没解码好 → null，
   调用方退回「整图变形」，六干员和大肥鱼一行都不用改。 */
function poseArtOf(look, cq, pr) {
  const set = POSE_IMG[look];
  if (!set) return null;
  /* 趴下优先：趴着时 cqEff 已经被 (1-proneK) 压到 0，两者不会同时成立 */
  const key = (pr > POSE_SWAP) ? 'prone' : ((cq > POSE_SWAP) ? 'crouch' : null);
  if (!key) return null;
  const im = set[key];
  if (!im || !im.complete || im.naturalWidth <= 0) return null;
  return { key: key, im: im, art: POSE_ART[look][key] };
}

/* 姿态图在屏幕上的几何：视觉身高按「相对 192 的站立立绘」等比换算，
   宽按画幅比例推。dx 是画幅左边相对角色原点的偏移（负值 = 往左）。 */
function poseGeom(art, vhStand) {
  const vh = vhStand * art.h / POSE_BASE_H;
  const w = vh * (art.w / art.h);
  return { vh: vh, w: w, dx: -w * art.foot };
}

/* 掌心的本地坐标（脚底为原点、朝 +x）。枪的挂点用它 —— 画枪和算枪口
   读的是同一个函数，「枪口不在枪管末端」在这条路径上不可能发生。 */
function poseHand(art, vhStand) {
  const g = poseGeom(art, vhStand);
  return { x: g.dx + g.w * art.hand[0], y: -g.vh + g.vh * art.hand[1] };
}

/* ------------------------------------------------------------------
   姿态图的局部形变：让一张静态立绘的腿能动
   ------------------------------------------------------------------
   姿态图解决了「蹲/趴画得不像」，代价是它是一整张静态图 —— 一移动
   就整张平移。原话是「趴下腿应该在蠕动，结果它没有动，是在平移」，
   蹲着走也一样：「还是在平移」。

   位图没有骨骼，局部旋转做不到，只能把图切开重排。两条姿态的腿
   形状完全不同，所以用两套切法：

   **趴姿 → 竖条（沿 x 切，腿方向）**。腿是横着伸出去的独立块，沿 x
   切不碰躯干。每条按连续权重加位移，权重在髋处收到 0，接缝不会断。

   **蹲姿 → 把立绘里本来就有的两条腿分开、反向摆**。蹲姿的腿长在躯干
   正下方、和躯干紧密相接，横着切一定切在肉上 —— 腰（0.34）切开像
   身体断成两截，髋下（0.62）切出一道水平断层，脚掌（0.86）断层没了
   但位移小到看不出。三条路全试过，都不成立。
   真正的解法是**先看清图里已经有什么**：这张立绘本来就画着前后两条
   腿，中间有一道缝（x≈0.53）。所以不用造腿，把两半按缝分开、各自
   绕膝反向平移即可 —— 详见下面 poseWarpLegs 的注释和踩坑记录。

   两套共用一条相位：a.anim。它就是步频，匍匐和蹲行在 ACT_CLIPS 里
   各有自己的 cadence，所以爬得慢腿也摆得慢，不用另起一套时间轴。
   权重再乘上实际速度：停下腿就停，不会原地自己蠕。

   幅度必须小。超过 4px 就开始像果冻而不像用力 ——
   真正让人觉得「在动」的是相位对、两端收得干净，不是幅度大。
   ------------------------------------------------------------------ */
const POSE_WARP_COL = 44;      /* 竖条数：趴姿屏宽约 118px → 每条约 2.7px */

/* 蹲行的腿：切点、缝、膝枢轴，全部从立绘的 alpha 轮廓量出来
   （test/_legseq.js 会把每一行「有肉的列段」打出来，别估，去读）。
   91×154 那张的实际数据：

     行 100 (v 0.65)   0-59 | 62-79      髋，一整块，只有一道浅缝
     行 106~122 (0.69~0.79)  3-69 / 16-75   ← **并腿段：一整块，没有缝**
     行 124 (v 0.81)   20-45 | 52-71       ← 这里才真正分叉
     行 140 (v 0.91)   19-34 | 46-70

   第二条是上一次返工的根因：0.69~0.79 这一段两条腿是糊在一起的，
   在那儿按 0.53 切开再挪 —— 切在肉上，一挪就是一道裂口，
   读起来是「腿在抽」，不是「腿在走」。所以：
     · 只能切在 0.80 以下（分叉线）
     · 0.80 以上整块不动，既没有裂口也不用重采样膝盖
     · 缝在 u 0.51~0.57（列 46~51），取中点 0.53
     · 远腿（暗蓝）u 0.19~0.47，近腿（棕靴）u 0.52~0.80 */
const POSE_LEG_CUT     = 0.80;   /* 分叉线：以上整块，以下两条独立小腿 */
const POSE_LEG_SPLIT_U = 0.53;   /* 两腿之间的缝 */
/* 脚的前后行程（屏幕 px，单侧）。上一版 3.4 只有两腿间距（约 15px）的
   1/4，两条腿永远不会互相比对方更靠前，所以读成「张合」不是「交错」。
   5.5 到了间距的 1/3 以上，前后关系才一眼看出来。 */
const POSE_FOOT_TRAVEL = 6.0;
/* 摆动腿的靴子往上抬多少（屏幕 px）。抬高 + 往前挪，才是「迈步」；
   只挪不抬，读起来还是在地上滑。 */
const POSE_LEG_LIFT    = 2.6;
/* 靴子上沿在画幅里的位置。0.80 以上是小腿，0.90 以下是整只靴子：
   靴子必须**当刚体平移**，一旦被缩放 / 剪切就变形 —— 上一版整条腿
   统一剪切，靴子被压成斜的平行四边形，像脚扭了。 */
const POSE_BOOT_V      = 0.91;

/* 本帧要不要形变。返回 null = 整图直接画（静止 / 不是蹲行匍匐）。 */
function poseWarpOf(a) {
  const P = actPose(a);
  const sp = Math.abs(a.vx || 0);
  /* 门槛比 actRun 推进 anim 那个 (sp > 8) 高一些：速度刚到 10 时
     腿在抖、又看不清方向，不如让它先停住。60 是「真在挪」的下限。 */
  const k = clamp((sp - 10) / 60, 0, 1);
  const cr = (P.w.crawl || 0) * k;
  const cw = (P.w.crouchW || 0) * k;
  if (cr < 0.04 && cw < 0.04) return null;
  const phase = a.anim || 0;
  /* 两条都接近 0.5 时（蹲着走直接趴下）谁的权重大听谁的，
     多一档混合只会让腿在两种切法之间闪 */
  if (cr >= cw) return { kind: 'crawl', amp: 3.4 * cr, phase: phase };
  return { kind: 'legs', amp: POSE_FOOT_TRAVEL * cw, phase: phase };
}

/* 按 warp 把这张图拼出来。im 必须是 art 画幅（受击红闪的 tint 图同尺寸，
   所以红闪可以拿同一个 warp 再画一遍，绝不会和主体错位）。 */
function poseWarped(im, g, warp) {
  if (!warp) { ctx.drawImage(im, g.dx, -g.vh, g.w, g.vh); return; }
  /* tint 走的是离屏 canvas，没有 naturalWidth —— 两种尺寸读法都要给 */
  const nw = im.naturalWidth || im.width;
  const nh = im.naturalHeight || im.height;
  if (warp.kind === 'legs') { poseWarpLegs(im, g, warp, nw, nh); return; }

  /* ---- 趴姿：竖条，脚端摆得最大、往手端收到 0 ---- */
  /* 画幅 58% 以右是手和头：整段一次画完，不切片。既省 drawImage，
     也保证头部这块最怕糊的区域完全不动、不重采样。 */
  const n = POSE_WARP_COL, seg = g.w / n, u1 = 0.58;
  const i1 = Math.ceil(u1 * n);
  for (let i = 0; i < i1; i++) {
    const u = (i + 0.5) / n;
    const wt = clamp(1 - u / u1, 0, 1);
    /* 位移只有单向（0 → −amp，即「往上抬」）。
       第一版是 sin 的双向摆动，结果腿有一半时间在往地里压：
       趴姿立绘的腿本来就贴地，往下挪 3px 就是穿进地面 ——
       放大图上看得很清楚，右帧的腿压到了地面线以下。
       爬行真实的动作是「抬起来 → 落回地面」，落回去是回到原图
       那个位置（位移 0），所以下限必须锁死在 0。

       相位随 u 往后推：脚先抬、髋后抬，波动从下肢传回躯干。
       u 在腿段上跨了约 0.65 个周期 —— 不到一个整波，读起来是
       「膝弯了一下」，整波会变成蛇形，那就不是人了。
       权重用 1.3 次方而不是平方：平方只有脚尖那 1/4 在动，
       看着像腿在抽，不像整条腿在使劲。 */
    const off = -(0.5 + 0.5 * Math.sin(warp.phase + u * 7.0)) * warp.amp * Math.pow(wt, 1.3);
    /* 每条多给 0.7px 宽（源图多给 0.6px）：相邻片重叠一点点，
       否则亚像素位移会在拼缝处露出发丝一样的亮线 */
    ctx.drawImage(im, i * nw / n, 0, nw / n + 0.6, nh,
                      g.dx + i * seg, -g.vh + off, seg + 0.7, g.vh);
  }
  ctx.drawImage(im, nw * u1, 0, nw * (1 - u1), nh,
                    g.dx + g.w * u1, -g.vh, g.w * (1 - u1), g.vh);
}

/* ---- 蹲姿：小腿分两段，靴子刚性平移，上面那截跟着弯 ----
   踩坑记录（别再试第二遍）：
   · 第一版「整条腿当刚体摆」：两条腿是同一份像素同一个亮度，错开之后
     读成「腿在抖」的重影，不像后面还有一条腿。压暗一份副本也没救回来 ——
     根本问题不在这：这张图**本来就画着两条腿**，叠两份就成了四条腿。
   · 第二版「按 0.53 切成左右两半、从膝 0.72 起给横向位移」：能动了，
     但 0.69~0.79 那一段两腿是糊成一整块的，位移从那儿开始等于切在肉上；
     幅度也只有 3.4px，不到两腿间距的一半，两条腿永远换不了位置 ——
     眼睛看到的是「张开 → 合上」，不是「一前一后」。用户第二次否掉的就是它。
   · 第三版「绕膝旋转 26°」：交错是有了，但**刚体转动必然在膝下留一块空地**
     —— 腿转走了，原来的位置就空出来，背景从那儿透过去，放大看像腿被切断。
     两条腿又是相向摆，空出来的地方正好都在外沿，谁都盖不住。这条路不通。
   · 第四版「整条小腿统一剪切 + 缩腿」：没有洞了，但靴子被一起剪切 /
     压扁，变成斜的平行四边形 —— 靴子是全图对比度最高的一块，一变形
     立刻读成「脚扭了」。所以形变绝对不能碰靴子。
   · 这一版：**小腿分上下两段**。
       · 靴子（≥0.91）当刚体，只平移 (前后偏移, 抬高)，形状一点不变
       · 中间那截（0.80~0.91）做剪切 + 纵向拉伸，把靴子接到膝盖上
     拉伸量正好等于靴子的抬升量，所以接缝严丝合缝；剪切量在顶边收到 0，
     所以膝线永远接得上，也不会像旋转那样空出一块 —— 整条腿始终是连续的肉。
   两段各一次 drawImage + 一次矩阵变换，只有两次重采样，不会出横纹。 */
function poseWarpLegs(im, g, warp, nw, nh) {
  const vc = POSE_LEG_CUT, vb = POSE_BOOT_V;
  const sy0 = nh * vc, sy1 = nh * vb;
  const dy0 = -g.vh + g.vh * vc;
  const sh1 = sy1 - sy0, dh1 = g.vh * (vb - vc);
  const sh2 = nh - sy1, dh2 = g.vh * (1 - vb);
  const sw = Math.sin(warp.phase), cs = Math.cos(warp.phase);

  /* 先远腿、后近腿，最后压上躯干。远腿是画幅左半那条暗蓝的。
     amp 是「这条腿出多少力」：近腿是迈步的那条，给满；远腿只做 0.38
     的反向配重。为什么不给满 —— 两条腿等幅反相时，sin=±1 那一侧会
     完全并到同一个位置，两只靴子叠成一坨，眼睛瞬间找不到两条腿了。
     0.38 让两脚的间距在 6.7~23.3px 之间来回，永远分得开，而 15px 的
     原始间距正好落在中间：既不会叠，也不会被拉成一字马。 */
  const legs = [
    { u0: 0, u1: POSE_LEG_SPLIT_U, sgn: +1, amp: 0.38 },
    { u0: POSE_LEG_SPLIT_U, u1: 1, sgn: -1, amp: 1.0 }
  ];
  for (const L of legs) {
    /* 脚往前 = 这条腿正在摆，它就抬；脚往后 = 踩地支撑，落回原高。
       用 max(0, sgn·cosθ) 而不是 |sin|：sin 在两端都是 0，那样两条腿
       会同时抬、同时落，读成「一起颠一下」，不是交替。 */
    const swing = Math.max(0, L.sgn * cs);
    const off = L.sgn * L.amp * POSE_FOOT_TRAVEL * sw;
    const lift = -L.amp * POSE_LEG_LIFT * swing;   /* 画布 y 向下，抬高是负 */
    const dx = g.dx + g.w * L.u0, dw = g.w * (L.u1 - L.u0);
    const sx = nw * L.u0, swid = nw * (L.u1 - L.u0);

    /* 上半截：顶边不动，底边横移 off、纵向拉到 dh1+lift —— 于是它下沿
       正好落在靴子平移后的上沿，不会有缝，也不会有重叠。 */
    ctx.save();
    ctx.translate(0, dy0);
    ctx.transform(1, 0, off / dh1, 1 + lift / dh1, 0, 0);
    ctx.drawImage(im, sx, sy0, swid, sh1, dx, 0, dw, dh1);
    ctx.restore();

    /* 靴子：纯平移，形状一像素不改 */
    ctx.save();
    ctx.translate(0, dy0 + dh1 + lift);
    ctx.drawImage(im, sx, sy1, swid, sh2, dx + off, 0, dw, dh2);
    ctx.restore();
  }
  /* 躯干 + 大腿整块，一像素不重采样，顺带盖住膝线上任何亚像素缝 */
  ctx.drawImage(im, 0, 0, nw, sy0, g.dx, -g.vh, g.w, g.vh * vc);
}


/* ============================================================
   大肥鱼改用位图美术资源（2026-10-28 换路子）
   ------------------------------------------------------------
   原本她整隻是 Canvas 路径一笔一笔画的，迭代了 6 轮
   （side1 → side_z6，见 test/）撞在硬天花板上：
   56px 的角色上，眼睛只有 1.8px、荷叶边一道褶只有 0.6px ——
   物理上画不出来，参数调到头也追不上设定稿的质感。

   现在改成「美术资源 + 程序化补间」：
     · 立绘 ImageGen 出图（朝右纯侧身），PIL 抠掉假透明棋盘格、
       去白边、缩到 192px 高（2x 超采样），base64 内联进这里，
       保证单文件版 build-single.js 打出来还能显示
     · 代码只负责搬运和变形：镜像、蹲下压缩、空翻旋转、落地挤压、受击闪烁
     · 路径绘制版本保留为 drawWhaleGirlPath()，图片没解码完时兜底
   ============================================================ */

/* 立绘：116×192（含呆毛与甩尾，脚底中心在宽度 61.8% 处）
   v2 重构：原来那版是「按大尺寸画、再缩小」，缩到 96px 后蕾丝碎花全糊成噪点，
   裙摆又比头宽，缩略图读起来是一团蓝。这一版按目标尺寸倒推：头（含发）占到
   全高一半、裙摆窄于头、围裙收成一整块白、轮廓线加粗，删掉所有缩到 96px 会消失的细节。 */
const WHALE_SPRITE_B64 = 'data:image/png;base64,';
/* Image 只在浏览器里存在。Node 探针（test/probe-*.js）用 vm 跑这份代码做
   数值回归，那里没有 DOM —— 顶层无脑 new Image() 会让整个文件加载失败，
   连带 7 个探针全报错。缺 Image 时就让它安静地退回路径绘制版本。 */
/* 握枪底图：双手前伸的空手取枪姿势，手上没有武器 ——
   枪由代码挂在她的前拳上，于是枪能跟着准星转，手不动，读起来是「手在稳枪」。 */
const WHALE_SPRITE_HOLD_B64 =
  'data:image/png;base64,';
const WHALE_SPRITE_HOLD = (typeof Image !== 'undefined') ? new Image() : null;
if (WHALE_SPRITE_HOLD) WHALE_SPRITE_HOLD.src = WHALE_SPRITE_HOLD_B64;

const WHALE_SPRITE = (typeof Image !== 'undefined') ? new Image() : null;
if (WHALE_SPRITE) WHALE_SPRITE.src = WHALE_SPRITE_B64;

/* 视觉高度。物理碰撞盒仍是 h=58 不动 —— 横版游戏里角色轮廓本来就
   比碰撞体饱满（裙摆、长发、呆毛都该溢出）。96px 是「能放下表情的最小尺寸」：
   再小眼睛就掉到 2px 以下，再大就会在 720p 里压过关卡平台。 */
const WHALE_VH = 96;
const WHALE_AR = 116 / 192;   /* 宽高比 */

/* 趴下抬升系数。1 是「身体半厚」，她整个人比人厚（裙摆 + 长发 + 尾巴
   铺开一大片），所以要多抬。这个数必须和 gunAnchor 里那个 liftK 是同一个，
   否则趴下时枪的挂点按一套算、身体按另一套画，枪会从手里飘出去。
   v1 立绘（细节版）实测贴地：2.2 时胸腹陷地 6px → 2.66。 */
const WHALE_LIFT_K = 1.74;

/* 两张底图各有各的脚底位置：待机图是垂手侧身，握枪图是开腿持枪。
   脚底中心不按图上量，按「两张图各自的脚」量，否则换图时人会横向跳一下。 */
const WHALE_FOOT = 0.654;       /* 待机图（idle） */
const WHALE_FOOT_HOLD = 0.592;  /* 握枪图（hold）：开腿站姿，两脚质心 */

function whaleSpriteReady() {
  return !!WHALE_SPRITE && WHALE_SPRITE.complete && WHALE_SPRITE.naturalWidth > 0;
}
function whaleHoldReady() {
  return !!WHALE_SPRITE_HOLD && WHALE_SPRITE_HOLD.complete && WHALE_SPRITE_HOLD.naturalWidth > 0;
}

/* 受击红闪用的纯红剪影：懒生成一次，之后复用。
   做法是把立绘画到离屏 canvas，再用 source-atop 只填它的不透明区 ——
   这样染色不会溢出到关卡背景上（直接在主 canvas 上 fillRect 会）。

   两张底图各存一份：剪影是按「哪张图的不透明区」抠的，用一个缓存的话，
   换了姿势红闪会烧出一张「另一个姿势的红色影子」。 */
let _whaleTint = null, _whaleTintHold = null;
function whaleTintFor(img) {
  if (!img || !img.complete || img.naturalWidth <= 0) return null;
  const c = document.createElement('canvas');
  c.width = img.naturalWidth;
  c.height = img.naturalHeight;
  const g = c.getContext('2d');
  g.drawImage(img, 0, 0);
  g.globalCompositeOperation = 'source-atop';
  g.fillStyle = '#ff5a3c';
  g.fillRect(0, 0, c.width, c.height);
  return c;
}
function whaleTintCanvas(img) {
  img = img || WHALE_SPRITE;
  if (img === WHALE_SPRITE_HOLD) {
    if (!_whaleTintHold) _whaleTintHold = whaleTintFor(img);
    return _whaleTintHold;
  }
  if (!_whaleTint) _whaleTint = whaleTintFor(img);
  return _whaleTint;
}

/* ============================================================
   蹲下：头不压、只压身子，再补「折」和「撑」
   ------------------------------------------------------------
   试过三种：
     · 整张图 scale(1.14, 0.80) —— 脸一起被压扁，像同一张图缩小了
       一点，没有「蹲」的动作感。
     · 切在裙摆下缘压死下半身 —— 裙子压成薄片，像陷进地里。
     · 脖子切两段、头段也压到 0.92 —— 比前两种好，但**脸还是会扁**：
       头段是 50px 高的一整块，压 8% 就是 4px，眼睛正好在这 4px 里。

   所以现在的分工是：**压缩全给身段，头一点不动**，另外补两个动作 ——
     · 上身绕脚底往前折（shear）—— 蹲是「折」，不是「缩」。
       重心压在脚掌上，肩比髋靠前，这是重量感的来源。
     · 髋 / 裙摆横向撑开 —— 蹲到底时膝盖朝外开，裙子撑成伞形。
   三件事叠起来读作「蹲下」；只有第一条的话，怎么调参数都读作「变矮」。

   切点仍压在她下巴下面那条脖子上（真实的结构线），看不出接缝。
   总高降到 85%，比物理箱的 71% 略高 —— 宁可让她看着「比实际高」，
   也别让她看着像已经躲好了结果吃子弹。
   ============================================================ */
const WHALE_NECK = 0.52;      /* 头/身分界：脖子在 sprite 高度 52% 处 */
const WHALE_HEAD_K = 1.00;    /* 头段的纵向残留：**1 = 完全不压**，别往下调 */
const WHALE_BODY_K = 0.64;    /* 身段的纵向残留（蹲到底时） */
const WHALE_PRONE_THIN = 0.34;  /* 趴下时压薄的比例（正面像收腿张开） */
const WHALE_CROUCH_LEAN = 0.20;  /* 蹲下时上身向前折的剪切系数（绕脚底） */
const WHALE_CROUCH_WIDE = 0.16;  /* 蹲下时髋 / 裙摆横向撑开 */

/* 蹲下后头段/身段各自的本地高度 */
function whaleBands(cq) {
  const headH = WHALE_VH * WHALE_NECK * (1 - cq * (1 - WHALE_HEAD_K));
  const bodyH = WHALE_VH * (1 - WHALE_NECK) * (1 - cq * (1 - WHALE_BODY_K));
  return { headH, bodyH, total: headH + bodyH };
}

/* 蹲下时任意 sprite 行号映射到的本地 y（本地坐标：脚底 = 0，向上为负） */
function whaleRowY(rowFrac, cq) {
  if (cq <= 0.01) return -WHALE_VH + rowFrac * WHALE_VH;
  const { headH, bodyH, total } = whaleBands(cq);
  if (rowFrac < WHALE_NECK) {
    return -total + (rowFrac / WHALE_NECK) * headH;
  }
  return -bodyH + ((rowFrac - WHALE_NECK) / (1 - WHALE_NECK)) * bodyH;
}

/* 立绘里那只手的掌心：sprite 像素 (66, 139)，换算成以脚底为原点的本地坐标。
   这个数字决定了枪会不会飘 —— 是量出来的，不是猜的。 */
const WHALE_HAND_ROW = 143 / 192;
const WHALE_HAND_X = -2.5;   /* 枪的挂点比掌心前移 3px：枪托别从背后戳出去 */
/* 路径版的枪按 58px 身高设计，位图是 96px，所以要让枪跟着变大一点。
   但**不能**按身高 96/58≈1.65 等比 —— 这张立绘的头占了将近一半身高，
   等比放大会让她端着一门炮。1.12 试过，整枪 52px，机匣块头跟她小臂一样粗，
   读起来像「抱着一块砖」。落到 0.95（整枪约 44px、1.3 个头宽），
   才是「顺手的一把步枪」。 */
const WHALE_GUN_K = 0.95;

/* 握枪图里，双拳抱在胸前（sprite 像素 (860, 885) 处是前手）。
   手臂已经画进图里并且固定在持握姿势，所以枪只要咬住这个点，
   手就不会跟着准星甩出去 —— 看起来是「手在稳枪」，而不是「枪在手外飘」。 */
const WHALE_HAND_ROW_HOLD = 108 / 192;
const WHALE_HAND_XFRAC_HOLD = 102 / 116;

/* 枪的挂点：本地坐标，脚底中心为原点、朝 +x。
   hold 图与 idle 图的前后位置差很多（垂手 vs 伸臂），必须分别算。 */
function whaleHandX(foot) {
  return (WHALE_HAND_XFRAC_HOLD - foot) * (WHALE_VH * WHALE_AR);
}

/* ============================================================
   腿：把立绘拆成「躯干 + 前腿 + 后腿」三片
   ------------------------------------------------------------
   立绘是一张死图，腿要动就必须单独摆。运行时拆件：
     · 两块小腿片 —— 从裙摆下缘往下，一直截到脚底
     · 一块躯干 —— 同一张图，只把下缘以下的腿像素清掉

   关键在那个「上缘」：腿片的上缘故意伸进裙摆内部二十多像素。
   画的时候先画腿、后画躯干，伸进裙子的那截被裙摆盖住 —— 于是
   腿不管抬多高、摆多大，切口永远藏在裙子里面，不会露出断层。
   这也是为什么只能「抬」不能「压」：往下走才会把切口拽出来。

   矩形全部写在 116×192 的立绘坐标里，按 naturalWidth/116 自动缩放，
   以后换 232×384 的素材不用改这里。
   ============================================================ */
const WHALE_LEG = {
  /* cutX0..cutX1 / cutY 以下是「腿」，从躯干上清掉；sx/sy/sw/sh 是腿片本身
     pivot 是髋关节（在裙子里面，旋转中心在这儿，脚才摆得自然）

     数字全部是量出来的（art/whale_hold.png 逐行 alpha 扫描，见 test/_legscan.js）：
       前腿：裙摆下缘 y≈173，腿在 y 174~191、x 48~60，鞋更宽一档
       后腿：裙摆右角在 y≈167，腿在 y 168~191、x 77~91
     cutY 正好压在裙摆下缘那条线上 —— 躯干保留整条完整的裙摆，
     腿片再从裙内往上伸 24px（sy=150/146）当作被裙子盖住的余量。 */
  front: { sx: 45, sy: 152, sw: 21, sh: 40, cutX0: 46, cutX1: 64, cutY: 174, pivotX: 54, pivotY: 156 },
  back:  { sx: 72, sy: 146, sw: 24, sh: 46, cutX0: 74, cutX1: 94, cutY: 168, pivotX: 84, pivotY: 154 }
};
/* 摆幅是「按可见量」定的，不是按角度手感定的。
   腿在立绘里只有 174~192 这 18px 露在裙摆外，换算到屏幕上（96px 身高、
   u=0.5）只剩 9px —— 髋到脚 36 立绘像素 = 18 屏幕像素。
   所以 0.10rad 只能让脚前后挪 1.8 屏幕像素，等于没动；0.22rad（≈12.6°）
   下脚前后 7.9 立绘像素 = 4 屏幕像素、抬脚 9 立绘像素 = 4.5 屏幕像素，
   两只鞋来回差了快三个鞋宽，才在「一眼看得出在迈步」和「不像踢正步」之间。
   再往上抬腿片会从裙摆侧边露头，所以到此为止。 */
const WHALE_STEP_ROT = 0.22;
const WHALE_STEP_LIFT = 9;
const WHALE_IDLE_ROT = 0.050;   /* 站着：重心轻轻换脚 */
const WHALE_IDLE_LIFT = 3.0;

/* 任意 canvas → 同尺寸纯红剪影（受击红闪用） */
function whaleSilhouette(src) {
  if (!src || typeof document === 'undefined') return null;
  const c = document.createElement('canvas');
  c.width = src.width; c.height = src.height;
  const g = c.getContext('2d');
  g.drawImage(src, 0, 0);
  g.globalCompositeOperation = 'source-atop';
  g.fillStyle = '#ff5a3c';
  g.fillRect(0, 0, c.width, c.height);
  return c;
}

/* img → { body, legs:{front,back}, s, sil(canvas) }，懒拆一次，之后复用。
   sil 是剪影缓存入口：受击红闪要对躯干和每条腿分别取剪影，
   否则红影子会顶着一双不动的腿，和身体的摆腿对不上。 */
const _whaleSplit = new Map();
function legPartsOf(img, cfg, artW, cache) {
  if (!img || typeof document === 'undefined') return null;
  if (!img.naturalWidth || !img.naturalHeight) return null;
  let hit = cache.get(img);
  if (hit !== undefined) return hit;
  const W = img.naturalWidth, H = img.naturalHeight;
  const s = W / artW;
  const mk = () => {
    const c = document.createElement('canvas');
    c.width = W; c.height = H;
    return c;
  };
  try {
    const body = mk();
    const bg = body.getContext('2d');
    bg.drawImage(img, 0, 0);
    const legs = {};
    for (const key in cfg) {
      const R = cfg[key];
      /* 腿片：只留腿本身那一块矩形，画布就跟腿一样大，省得每次搬整图 */
      const c = document.createElement('canvas');
      c.width = Math.ceil(R.sw * s); c.height = Math.ceil(R.sh * s);
      const cg = c.getContext('2d');
      cg.drawImage(img, R.sx * s, R.sy * s, R.sw * s, R.sh * s,
                        0, 0, R.sw * s, R.sh * s);
      /* 后腿压暗一档：和躯干的明暗拉开，两条腿叠在一起时才读得出前后 */
      if (key === 'back') {
        cg.globalCompositeOperation = 'source-atop';
        cg.fillStyle = 'rgba(0,0,0,' + (R.dim === undefined ? 0.13 : R.dim) + ')';
        cg.fillRect(0, 0, c.width, c.height);
      }
      legs[key] = c;
      /* 躯干从 cutY 往下把这块腿挖掉 —— 挖掉的矩形全在腿片范围内 */
      bg.clearRect(R.cutX0 * s, R.cutY * s, (R.cutX1 - R.cutX0) * s, H - R.cutY * s);
    }
    hit = { body, legs, s, sil: {} };
  } catch (e) {
    hit = null;
  }
  cache.set(img, hit);
  return hit;
}
function whaleLegParts(img) { return legPartsOf(img, WHALE_LEG, 116, _whaleSplit); }

/* parts 里某一块（'body' 或腿名）的剪影，取过就缓存 */
function whalePartSil(parts, key) {
  if (!parts) return null;
  if (parts.sil[key] !== undefined) return parts.sil[key];
  const src = key === 'body' ? parts.body : parts.legs[key];
  const sv = whaleSilhouette(src);
  parts.sil[key] = sv;
  return sv;
}

/* 这一步两条腿该摆多少（rot：绕髋转角；lift：抬脚，立绘像素）
   三种状态：空中收腿 / 走跑交替迈步 / 站着换重心。
   蹲下时脚踩死 —— 蹲着还抖腿会显得人没重量。 */
/* 参数化版本：摆幅由调用方给（大肥鱼 / 主角各有各的腿长，同一个角度
   在 96px 的立绘上走出的步幅是不一样的），姿态逻辑完全共用。 */
function gaitFor(a, t, cq, K) {
  const out = { front: { rot: 0, lift: 0 }, back: { rot: 0, lift: 0 } };
  const sp = Math.abs(a.vx || 0);
  if (!a.onGround) {
    /* 空中收腿：前腿往前收、后腿往后蹬，两脚都离地 —— 读起来是「腾空」而不是「站在空气上」 */
    out.front.rot = K.airFront; out.front.lift = K.airLiftF;
    out.back.rot = K.airBack; out.back.lift = K.airLiftB;
  } else {
    /* 走 / 站之间原来是硬切：速度跨过 28px/s 的那一帧，相位从 a.anim
       直接换成 t*1.9，摆幅从 stepRot(0.52) 掉到 idleRot(0.13) ——
       四条腿在 16 毫秒里缩回去 3/4，读起来是「被谁按了一下膝盖」。
       这段是原地停步，玩家天天要做，却一直没人报，因为它太快、
       只在一瞬间，眼睛看到的是「有点怪」而说不出哪儿怪。

       改成两条曲线按速度加权：8px/s 以下全是待机，60 以上全是迈步，
       中间线性混。两端和原来自行完全一致（m=0 / m=1），
       所以手感没变，只是中间那 52px/s 的过渡带被填上了。 */
    const m = clamp((sp - 8) / 52, 0, 1);
    const phW = a.anim || 0;
    const phI = t * 1.9;
    const fW = Math.sin(phW), bW = Math.sin(phW + Math.PI);
    const fI = Math.sin(phI), bI = Math.sin(phI + Math.PI);
    out.front.rot = lerp(fI * K.idleRot, fW * K.stepRot, m);
    out.back.rot = lerp(bI * K.idleRot, bW * K.stepRot, m);
    out.front.lift = lerp(Math.max(0, fI) * K.idleLift, Math.max(0, fW) * K.stepLift, m);
    out.back.lift = lerp(Math.max(0, bI) * K.idleLift, Math.max(0, bW) * K.stepLift, m);
  }
  if (cq > 0.02) {
    const k = 1 - cq;
    out.front.rot *= k; out.front.lift *= k;
    out.back.rot *= k; out.back.lift *= k;
  }
  return out;
}

const WHALE_GAIT_K = {
  stepRot: WHALE_STEP_ROT, stepLift: WHALE_STEP_LIFT,
  idleRot: WHALE_IDLE_ROT, idleLift: WHALE_IDLE_LIFT,
  airFront: 0.13, airBack: -0.10, airLiftF: 7.0, airLiftB: 8.0
};
function whaleGait(a, t, cq) { return gaitFor(a, t, cq, WHALE_GAIT_K); }

/* ============================================================
   贴着准星倾身
   ------------------------------------------------------------
   想让「抬头角度」跟着准星走，最直觉的做法是把头单独转一点。
   但这张立绘的头发和肩是连成一片的：横着切一刀再转头，
   切口处（左边那一大团后发，离脖子 300+ 像素）会错开十几像素，
   放大看就是一条断裂的头发。任何「只转头部」的写法都躲不掉这条缝。

   所以在这里改成整身倾身：绕脚底那个点转一点点，头、肩、枪一起走。
   没有任何切线，不会裂；准星抬得越高，人往后仰得越多，
   读起来就是「她跟着准星把身子让过去了」。

   上限 4.9° —— 再大就不像在瞄准，像被人从背后推了一把。
   绕脚底转 4.9° 时，头（离地约 70px）横移 6px，是「看得出来但不会怪」的量。
   ============================================================ */
const WHALE_LEAN_K = 0.080;     /* 每 1rad 俯仰 → 0.080rad 倾身 */
const WHALE_LEAN_MAX = 0.085;   /* ≈4.9° 封顶 */

function whalePitch(a) {
  /* aim 是整圆角度（朝左时 ≈π）；折成俯仰角，抬头 = 负、低头 = 正 */
  return Math.atan2(Math.sin(a.aim), Math.abs(Math.cos(a.aim)));
}
function whaleLean(a) {
  return clamp(whalePitch(a) * WHALE_LEAN_K, -WHALE_LEAN_MAX, WHALE_LEAN_MAX);
}

/* 位图通道的枪：只画枪身和枪口焰。
   握枪图里她已经有两只手在托着，再画袖子就是三只手。
   part='back' / 'front' 用来分两趟画（枪托在立绘下面、机匣在上面）。 */
function whaleGunProp(a, cq, lean, part) {
  ctx.save();
  /* 外层已经 scale(facing,1) 翻过镜像，所以这里的 +x 就是「面朝方向」。
     aim 是整圆角度（朝左时 ≈π），直接拿去 rotate 会转反，
     要先折成俯仰角 atan2(sin, |cos|)。
     外层还整体倾了 lean，这里要扣掉 —— 否则枪会比准星多转那 3°，
     近距离看得出来「枪口没指着十字」。 */
  const pitch = whalePitch(a);
  const hold = whaleHoldReady();
  const hx = hold ? whaleHandX(WHALE_FOOT_HOLD) : WHALE_HAND_X;
  const hy = hold ? whaleRowY(WHALE_HAND_ROW_HOLD, cq || 0)
                  : whaleRowY(WHALE_HAND_ROW, cq || 0);
  ctx.translate(hx, hy);
  ctx.rotate(pitch - (lean || 0));
  ctx.scale(WHALE_GUN_K, WHALE_GUN_K);
  ctx.translate(-9, -5);            /* 枪的握把在 (9,5)，挪过来咬住掌心 */
  ctx.translate(-kickOf(a), 0);     /* 后坐：沿枪管往后，在缩放里面 → 已乘过 K */
  /* 换弹：绕握把下沉 + 枪口垂下（枪的重心在手里，所以像把枪放低了一点） */
  const dip = gunDip(a);
  if (dip.rot) ctx.rotate(dip.rot);
  if (dip.dy) ctx.translate(0, dip.dy);
  whaleGunBody(a, part);

  ctx.restore();
}

const WH = {
  ink: '#0b1420',
  skin: '#f8ddc6', skinS: '#e0b191',
  hairD: '#102c52', hairM: '#1d5ca6', hairL: '#84d5f4',
  dress: '#192a45', dressD: '#0f1a2c', dressL: '#294164',
  apron: '#f0f7fd', apronS: '#c4d7e9',
  ribbon: '#38a8e2', ribbonD: '#1b74ab',
  eye: '#2f86d8', eyeD: '#10365c',
  tail: '#1d5ca6', tailL: '#a9e3f8',
  boot: '#1a2540'
};

/* 填色 + 描边一体：这套画风靠厚描边撑剪影 */
function wPath(col, lw) {
  ctx.fillStyle = col;
  ctx.fill();
  if (lw !== 0) {
    ctx.strokeStyle = WH.ink;
    ctx.lineWidth = lw || 1.5;
    ctx.stroke();
  }
}

/* ---------------- 队友名牌 / 血条 / 气泡（与人类士兵共用） ---------------- */
function drawBuddyPlate(a, sx, topY) {
  ctx.textAlign = 'center';
  ctx.font = 'bold 12px "Microsoft YaHei",sans-serif';
  ctx.fillStyle = '#7fd8ff';
  ctx.fillText(a.plateName || '大肥鱼', sx, topY - 4);

  const bw = 46, ratio = clamp(a.hp / a.maxHp, 0, 1);
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  roundRect(sx - bw / 2 - 1, topY - 1, bw + 2, 7, 3);
  ctx.fill();
  ctx.fillStyle = ratio > 0.5 ? '#5fd98a' : (ratio > 0.25 ? '#ffc857' : '#ff6b5a');
  roundRect(sx - bw / 2, topY, bw * ratio, 5, 2.5);
  ctx.fill();

  /* 只在真正打的时候说话：结算 / 失败 / 暂停时 bubbleTimer 不再走，
     不挡的话会冻在屏幕上 —— 已经通关了，大肥鱼还在下面喊
     「我跟着你，你打哪我打哪」，跟结算卡对不上。 */
  if (a.bubbleTimer > 0 && a.bubble && game.state === 'playing') {
    ctx.font = '13px "Microsoft YaHei",sans-serif';
    const tw = ctx.measureText(a.bubble).width;
    const bw2 = tw + 20;
    /* 大肥鱼靠着屏幕左（右）边缘说话时，气泡会有一半被画布裁掉，
       只剩「管你，你打哪我打哪。」这种半句。整块夹回画布内，尖端仍指向角色。 */
    const bx = clamp(sx - tw / 2 - 10, 6, W - bw2 - 6);
    /* 气泡要挂在名牌**上方**。老公式按 58px 的路径小人写的（顶到 a.y-124），
       大肥鱼的位图有 96px 高，名牌已经顶到 a.y-112 —— 不重算的话气泡会把名字和血条整个盖住。
       取两者更靠上的那个：路径小人维持原样，位图自动跟着名牌走。 */
    const by = Math.min(a.y - a.h - 66, topY - 46);
    ctx.globalAlpha = Math.min(1, a.bubbleTimer * 2);
    ctx.fillStyle = 'rgba(12,20,30,0.94)';
    ctx.strokeStyle = 'rgba(127,216,255,0.75)';
    ctx.lineWidth = 1.5;
    roundRect(bx, by, bw2, 26, 8);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(sx - 6, by + 26);
    ctx.lineTo(sx, by + 34);
    ctx.lineTo(sx + 6, by + 26);
    ctx.fillStyle = 'rgba(12,20,30,0.94)';
    ctx.fill();
    ctx.fillStyle = '#bfe9ff';
    ctx.textAlign = 'center';
    /* 文字必须跟着盒子走：盒子夹回画布了、字还按 sx 居中，
       靠边说话时第一个字就露在盒子外面（还被画布裁掉） */
    ctx.fillText(a.bubble, bx + bw2 / 2, by + 18);
    ctx.globalAlpha = 1;
  }
}

/* ---------------- 一条腿：过膝袜 + 小皮鞋 ---------------- */
function whaleLeg(hx, hy, swing, knee, thick) {
  const TH = 11, SH = 12;
  const kx = hx + Math.sin(swing) * TH, ky = hy + Math.cos(swing) * TH;
  const ang = swing - knee;
  const fx = kx + Math.sin(ang) * SH, fy = ky + Math.cos(ang) * SH;

  seg(hx, hy, kx, ky, thick, WH.apron);          /* 袜口以下整体白 */
  seg(kx, ky, fx, fy, thick * 0.9, WH.apron);
  /* 袜口皱边 */
  ctx.strokeStyle = WH.apronS;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(hx - thick * 0.55, hy + 1);
  ctx.lineTo(hx + thick * 0.55, hy + 1);
  ctx.stroke();
  /* 鞋 */
  ctx.save();
  ctx.translate(fx, fy);
  ctx.beginPath();
  roundRect(-3.6, -2.8, 8.8, 4.6, 1.9);
  wPath(WH.boot, 1.3);
  ctx.restore();
  return { fx, fy };
}

/* ---------------- 鲸鱼尾：从尾椎往身后甩，随情绪摆动 ---------------- */
function whaleTail(facing, hipY, mood, t, vx) {
  const wag = Math.sin(t * 3.2) * (mood === 2 ? 0.35 : 1) + clamp(-vx * 0.006, -0.5, 0.5);
  ctx.save();
  ctx.translate(-facing * 5, hipY + 2);
  ctx.scale(facing, 1);
  ctx.rotate(-0.55 + wag * 0.22);

  /* 尾柄 */
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.quadraticCurveTo(-8, -3, -15, -8);
  ctx.lineTo(-13.5, -2.5);
  ctx.quadraticCurveTo(-7, 3.5, 0, 4.5);
  ctx.closePath();
  wPath(WH.tail, 1.5);

  /* 尾鳍：两瓣，上大下小 */
  ctx.beginPath();
  ctx.moveTo(-14, -8);
  ctx.quadraticCurveTo(-24, -14, -23, -20.5);
  ctx.quadraticCurveTo(-17, -18, -12.5, -12.5);
  ctx.closePath();
  wPath(WH.tailL, 1.4);

  ctx.beginPath();
  ctx.moveTo(-13, -3);
  ctx.quadraticCurveTo(-21, -1, -22.5, 5.5);
  ctx.quadraticCurveTo(-16, 3.5, -11.5, -0.5);
  ctx.closePath();
  wPath(WH.tail, 1.4);
  ctx.restore();
}

/* ---------------- 长发：从脑后垂到腰，带一缕冰蓝渐变 ---------------- */
function whaleHairBack(facing, headY, hipY, t, vx, mood) {
  const sway = clamp(-vx * 0.012, -0.55, 0.55) + Math.sin(t * 1.7) * 0.09;

  ctx.save();
  ctx.translate(-facing * 1.5, 0);

  /* 主发团 */
  ctx.beginPath();
  ctx.moveTo(-8.5, headY + 2);
  ctx.quadraticCurveTo(-15 - sway * 4, headY + 16, -12.5 - sway * 7, hipY + 5);
  ctx.quadraticCurveTo(-9 - sway * 6, hipY + 12, -3 - sway * 3, hipY + 9);
  ctx.quadraticCurveTo(2, hipY + 4, 1, hipY - 2);
  ctx.quadraticCurveTo(2, headY + 12, 3, headY + 2);
  ctx.closePath();
  wPath(WH.hairM, 1.6);

  /* 深处的暗面 */
  ctx.beginPath();
  ctx.moveTo(-8, headY + 4);
  ctx.quadraticCurveTo(-13 - sway * 3, headY + 18, -10.5 - sway * 5, hipY + 4);
  ctx.quadraticCurveTo(-7, hipY + 8, -5, hipY + 3);
  ctx.closePath();
  wPath(WH.hairD, 0);

  /* 发梢冰蓝 */
  ctx.beginPath();
  ctx.moveTo(-12.5 - sway * 7, hipY + 5);
  ctx.quadraticCurveTo(-9 - sway * 6, hipY + 13, -3 - sway * 3, hipY + 9);
  ctx.quadraticCurveTo(-6.5, hipY + 6, -8 - sway * 4, hipY - 1);
  ctx.closePath();
  wPath(WH.hairL, 0);
  ctx.globalAlpha = 0.5;
  ctx.fillStyle = WH.hairL;
  ctx.beginPath();
  ctx.ellipse(-9 - sway * 4, hipY + 1.5, 3.4, 5.5, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.restore();
}

/* ---------------- 手臂 + 枪（复用玩家那套枪械造型，压窄一点） ---------------- */
function whaleGun(a, facing, shY, aim) {
  ctx.save();
  ctx.translate(facing * 1.5, shY + 3);
  ctx.rotate(aim);
  if (facing < 0) ctx.scale(1, -1);

  const kick = Math.min(1, (a.muzzle || 0) * 12);
  ctx.translate(-kick * 1.5, 0);

  /* 后手 + 袖子 */
  seg(-1, 2, 7, 5.5, 6.5, WH.dressD);
  ctx.beginPath();
  ctx.ellipse(-3.5, 2.5, 4.6, 4.2, 0, 0, Math.PI * 2);
  wPath(WH.apron, 1.3);

  whaleGunBody(a);

  /* 前手 + 袖子 */
  seg(1.5, -2, 24, 3.4, 6.5, WH.dress);
  ctx.beginPath();
  ctx.ellipse(2, -2.5, 5.2, 4.6, 0, 0, Math.PI * 2);
  wPath(WH.apron, 1.3);
  ctx.fillStyle = WH.skin;
  ctx.beginPath(); ctx.arc(24, 3.8, 3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(9, 5.4, 2.8, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}

/* ---------------- 枪身本体 ----------------
   把枪从「手臂 + 枪」里单独拎出来，是为了位图通道。
   立绘里她自己的手臂和手已经画在图上了，再画代码的袖子就成了三只手；
   但枪不能丢 —— 射击游戏里枪口位置是玩家读朝向、读「我正在开火」的主要线索。
   所以位图通道只借这一坨：机匣/弹匣/枪管/枪口焰，不画袖子不画手。
   坐标单位仍是「58px 身高的角色」，缩放由调用方负责。
   枪的握把在 (9, 5)，调用方据此对齐掌心。

   part='back' 只画该被她的身体挡住的那部分（枪托、弹匣），
   part='front' 画该露在她手外面的（机匣、准星、枪管、枪口焰）。
   分两趟是因为：她的双拳是抱在胸前的，枪身如果整块压在上面，
   拳头就全被盖住了 —— 看起来像「枪粘在胸口」，而不是「手握着枪」。
   枪托塞在肩窝里本来就该被身体挡住，弹匣挂在她肚子前面也该被挡住，
   这两块放到立绘下面，露出来的只有机匣和枪管，正好从她手背上方穿出去。 */
function whaleGunBody(a, part) {
  /* 填 + 描一体。第一版没描边、又用了 #2c343b 这种和裙子（#192a45）、
     背景（#20262e）几乎同亮度的深灰，结果整把枪糊成一团，
     看着像「她胸口破了个洞」而不是「她端着一把枪」。
     素材本身是厚描边画风，枪也得吃同一套 ink 线才立得住。 */
  const ink = '#0b1420';
  const paint = (fill, lw) => {
    ctx.fillStyle = fill;
    ctx.fill();
    if (lw !== 0) {
      ctx.strokeStyle = ink;
      ctx.lineWidth = lw || 1.0;
      ctx.lineJoin = 'round';
      ctx.stroke();
    }
  };

  /* part 省略 = 整把枪一次画完（路径通道走这条，顺序和原来一致） */
  if (part !== 'front') {
    /* 枪托（塞在肩前，被她的双手和胸口挡住）—— 压暗，别抢机匣的视线 */
    roundRect(-9, 0.5, 11, 6.5, 2);
    paint('#39434d');
    /* 弹匣（挂在小腹前，被裙摆和胳膊挡住大半）。换弹时它会先消失、
       再从下方推回去 —— 这是「上膛」在这张立绘上唯一能加的动作 */
    gunMag(a, '#313b45', ink, 1.0);
    if (part === 'back') return;
  }
  /* 机匣：全枪最亮的一块，视线先落这儿。
     高度收到 6.2 —— 7.2 的时候它跟小臂一样粗，整把枪读成一块砖。 */
  roundRect(-1, -2.6, 20, 6.2, 2);
  paint('#5c6771', 1.15);
  /* 机匣上沿高光：一道 1px 的冷光，小尺寸下它就是「金属」的信号 */
  ctx.fillStyle = 'rgba(186,214,236,0.55)';
  ctx.fillRect(0.6, -2.2, 17.8, 1.0);
  /* 瞄准镜：直接坐在机匣顶上。
     上一版中间还垫了一条 #39434d 的「导轨」，三层同色叠在一起，
     描边把它们焊成一个实心方块 —— 这才是「像砖」的真凶，导轨删掉。 */
  roundRect(5.0, -6.9, 6.6, 3.5, 1.2);
  paint('#1b2229', 1.1);
  /* 镜筒迎光面 + 镜片：这两笔是「这不是一块铁，是带镜的枪」的唯一线索 */
  ctx.fillStyle = 'rgba(150,196,232,0.32)';
  ctx.fillRect(5.8, -6.5, 5.0, 1.1);
  ctx.fillStyle = 'rgba(168,226,255,0.9)';
  ctx.fillRect(10.5, -6.2, 1.0, 2.4);
  /* 枪管：上亮下暗的金属圆柱 */
  const bgr = ctx.createLinearGradient(17, -1.5, 17, 1.9);
  bgr.addColorStop(0, '#8d99a5');
  bgr.addColorStop(0.45, '#5d6873');
  bgr.addColorStop(1, '#2b333b');
  ctx.fillStyle = bgr;
  ctx.fillRect(17, -1.5, 14, 3.2);
  ctx.strokeStyle = ink;
  ctx.lineWidth = 1.0;
  ctx.strokeRect(17, -1.5, 14, 3.2);
  /* 枪口消焰器：比枪管粗一圈，剪影上有个台阶才认得出是枪口 */
  roundRect(31, -2.1, 5.2, 4.4, 1);
  paint('#232b32', 1.05);

  /* 枪口焰（消焰器口在 x≈36.2，焰心咬在那儿才不会「从枪管中间喷火」） */
  if ((a.muzzle || 0) > 0) {
    const mg = ctx.createRadialGradient(36, 0, 1, 36, 0, 23);
    mg.addColorStop(0, 'rgba(255,248,214,0.95)');
    mg.addColorStop(0.35, 'rgba(255,186,72,0.55)');
    mg.addColorStop(1, 'rgba(255,120,0,0)');
    ctx.fillStyle = mg;
    ctx.beginPath(); ctx.arc(36, 0, 23, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(255,240,190,0.9)';
    ctx.beginPath();
    ctx.moveTo(35, 0); ctx.lineTo(44, -3.2); ctx.lineTo(41, 0); ctx.lineTo(44, 3.2);
    ctx.closePath(); ctx.fill();
  }
}

/* ==================================================================
   枪口：唯一权威
   ------------------------------------------------------------------
   以前「子弹从哪出来」是三个地方各算各的：
     · ai.js  fireWeapon    → a.x + cos(aim)*30, a.y - a.h*0.62 + sin()*30
     · render2 scMuzzleFor  → 横移 38, 肩高 -46.5 + 17*cqEff
     · 每个 xxxGunProp 的真实变换栈
   第一个用受击盒 a.h 当身高估肩高（趴下时 h 从 58 掉到 28，越趴越错），
   第二个是照着「站立」量的一条直线，蹲下/趴下都只是近似加一项。
   于是屏幕上枪口在脸旁，子弹却从胸口往外飞 —— 用户的原话是
   「打出去的枪械实际上是低于它显示的那个枪口」。

   现在只留这一份：把 GunProp 的变换栈按矩阵走一遍，解出枪口那个点。
   枪是三个人共用的一把（whaleGunBody），几何写在下面这两个常量里：
     握把 (9,5)  —— 变换栈先 translate(-9,-5) 把握把咬到掌心
     枪口 (36,0) —— 所以「枪口相对掌心」= (27,-5)，再乘缩放 K
   改 whaleGunBody 的枪管长度时，这两个数要一起改。
   ================================================================== */
const GUN_GRIP = { x: 9, y: 5 };
const GUN_MUZZLE = { x: 36, y: 0 };

/* ==================================================================
   动起来：三个自由度
   ------------------------------------------------------------------
   立绘是一整张静态图，现在只有腿在摆，读起来就是「人钉在空气里剪腿」。
   4399 那批横版角色之所以不木头，是因为同一张图跑起来的时候还有三件事：

     ① 上下一沉一起 —— 每迈一步重心沉一下再弹起来；
     ② 起步前倾、急停后仰 —— 重心先动，腿后跟；
     ③ 站定时轻微呼吸 —— 不动的时候也还在「活着」。

   三件事全做在「绕脚底」那一层：脚永远踩在原地，不会浮空，也不碰受击盒。
   关键是枪口必须跟着一起动 —— muzzlePoint 读的是同一个 motionOf，
   否则又回到「子弹从胸口飞出来」那个老毛病。

   逐帧缓存（_frameNo）是必需的：同一帧里 fireWeapon 和 render 各要问一次，
   没有闸门就会把加速度积分两遍，人往前倒 3.6° 而子弹只倒 1.8°。
   ================================================================== */
function motionOf(a) {
  /* 动觉三自由度（起伏 / 倾角 / 呼吸）现在全部由动作层推进，
     这里只做一次转发 —— 保留 motionOf 这个名字是因为枪口 muzzlePoint
     和四套画法都按它取的，改名字只会多一处漏改的风险。

     这一帧还没被 actRun 结算过（比如截图脚本直接问姿态、或者只调
     render 不调 update）就在这里补一次。actRun 自己带帧号闸门，
     所以补算不会把步频推进两遍。 */
  const fno = (typeof _frameNo === 'number') ? _frameNo : -1;
  /* 这一帧已经有人往里喂了一份姿态（_motion.js 的枪口测试就是这么做的，
     好把 bob/lean 精确控制住、只看枪口跟不跟）—— 直接用它，不要覆盖。 */
  if (fno >= 0 && a._moNo === fno && a._mo) return a._mo;
  if (a._poseNo !== fno) {
    actRun(a, (typeof _dt === 'number' && _dt > 0) ? _dt : 0);
  }
  const P = a._pose || ACT_EMPTY;
  return { bob: P.bob, lean: P.lean };
}

/* 换弹动作：枪在手里下沉 + 枪口垂下去，走「落下 → 扶正」一条正弦包络。
   不新增任何绘制，只是把枪的动态补上 —— HUD 上有进度环，
   可人身上一点反应都没有的时候，看着就像「对着空气做表情」。

   现在这个包络由动作层算（actRun 的 P.reload），这里只取结果：
   玩家用 reloading/reloadDur、敌兵用 reloadT/reload，两套字段名在
   actRun 里已经合并成同一条进度线 —— 所以敌兵换弹的枪口动作，
   和玩家是同一个节奏，不会再出现「敌人换弹是匀速、自己是缓入缓出」。 */
/* ------------------------------------------------------------------
   换弹的弹匣
   ------------------------------------------------------------------
   「上膛」原先只有枪在往下沉，人身上一点反应都没有 —— 玩家读不出
   自己在换弹，只能看 HUD 上那个环。加一只手是错的解法：位图立绘的
   手已经画在图里，再画一只就是三只手。

   所以只动那一个弹匣：先在弹匣井里「咔」一下抽走（前半段不画），
   再从下方推一只新的进去（后半段），最后压实。这个位移在 96px 上
   看得见，而且不需要第二只手。

   抽出来是因为三套画法（大肥鱼 / 主角 / 干员）的弹匣几何是同一组数
   （7,4.4 / 15.4,4.4 / 17.2,13.6 / 9.6,14.4），各画一份的话，
   改一处另外两处就对不齐了。敌兵那把枪用的是同一组数，也调这个。
   ------------------------------------------------------------------ */
function gunMagShape(fill, ink, lw) {
  ctx.beginPath();
  ctx.moveTo(7, 4.4);
  ctx.lineTo(15.4, 4.4);
  ctx.lineTo(17.2, 13.6);
  ctx.lineTo(9.6, 14.4);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
  if (lw) {
    ctx.strokeStyle = ink;
    ctx.lineWidth = lw;
    ctx.lineJoin = 'round';
    ctx.stroke();
  }
}

/* magPhase：0 → 0.45 旧匣已抽出（这一段干脆不画，读作「空仓」），
   0.45 → 1 新匣从下方推进到位，最后一段 S 形收力（压实那一下）。 */
function gunMag(a, fill, ink, lw) {
  const rl = actReloadEnvelope(a);
  if (rl.k > 0.02) {
    if (rl.phase < 0.45) return;
    const k = (rl.phase - 0.45) / 0.55;
    const e = k * k * (3 - 2 * k);
    ctx.save();
    ctx.translate(0, 15 * (1 - e));
    ctx.rotate(-0.22 * (1 - e));
    gunMagShape(fill, ink, lw);
    ctx.restore();
    return;
  }
  gunMagShape(fill, ink, lw);
}

const DIP_NONE = { dy: 0, rot: 0 };
/* 姿态图接管时用的「不做放倒」：和 pronePose 在 pr=0 时返回的那份同形，
   免得下面每一处都要判空。共享一份常量，不每帧生成对象。 */
const POSE_FLAT = { pr: 0, ang: 0, shift: 0, lift: 0 };
function gunDip(a) {
  const k = actReloadEnvelope(a).k;     /* 0 → 1 → 0 的正弦包络，两头归零 */
  if (k <= 0.001) return DIP_NONE;
  return { dy: k * 7.5, rot: k * 0.30 };
}

/* 每套外观的：掌心挂点 / 枪缩放 / 后坐距离 / 视觉身高 / 趴下抬升系数。
   这些数字原本硬编码在各自的 GunProp 里，这里抄一份当出口 ——
   prop 那边改了，这里必须一起改（两边注释互相指认）。 */
function gunAnchor(a) {
  const look = a.look;
  if (look === 'whale') {
    /* 握枪图和待机图的挂点差很多：一张是双拳抱胸、一张是手垂在身侧。
       图还没解码完时 whaleHoldReady() 是 false，画的也是待机图，
       所以这里必须问同一个函数，不能假定「一定是握枪图」。 */
    const hold = whaleHoldReady();
    const cq = cqEff(a);
    return {
      hx: hold ? whaleHandX(WHALE_FOOT_HOLD) : WHALE_HAND_X,
      hy: hold ? whaleRowY(WHALE_HAND_ROW_HOLD, cq) : whaleRowY(WHALE_HAND_ROW, cq),
      K: WHALE_GUN_K, rec: 1.5, vh: WHALE_VH, liftK: WHALE_LIFT_K,
      squash: true
    };
  }
  if (look === 'hero') {
    /* 蹲到底 / 趴到底交给了专门画的姿态图 —— 挂点必须跟着换，
       否则枪会留在站姿的旧位置（蹲下时浮在肚子上、趴下时悬在半空）。 */
    const pa = poseArtOf(look, cqEff(a), proneK(a));
    if (pa) {
      const hand = poseHand(pa.art, HERO_VH);
      return {
        hx: hand.x, hy: hand.y,
        K: HERO_GUN_K, rec: 1.5, vh: HERO_VH, liftK: HERO_LIFT_K,
        squash: true, poseArt: true
      };
    }
    return {
      hx: (HERO_HAND_XFRAC_HOLD - HERO_FOOT_HOLD) * (HERO_VH * HERO_AR_HOLD),
      hy: heroRowY(HERO_HAND_ROW_HOLD, cqEff(a)),
      /* liftK 必须和 drawHero 里 pronePose 用的是同一个（HERO_LIFT_K）。
         这里原来写的 1，比画面上少抬 8px —— 平时平瞄看不出来，一趴下
         枪口就掉到身体外面去了（「子弹不从枪口出」就是这么来的）。 */
      K: HERO_GUN_K, rec: 1.5, vh: HERO_VH, liftK: HERO_LIFT_K,
      squash: true
    };
  }
  if (look === 'kimi' || look === 'glm' || look === 'gpt') {
    /* 干员是程序化骨架，挂点是写死的 (2.5,-55)；
       骨架蹲下时整体非等比压扁（见 drawAgent 的 squash = 1 - cq*0.30 + sq*0.06），
       枪跟着一起压。注意这条挤压和位图那两套**不是**一个公式，
       所以 squash 置 false、只走 agentSquash 这一支，别叠两遍。 */
    if (castReady(look)) {
      /* 有立绘就走位图那套：挂点、缩放、抬升全部来自 castAnchor，
         和 drawCast 里画枪读的是同一个函数 —— 两边不可能对不上。 */
      return castAnchor(CAST_CFG[look], cqEff(a), proneK(a), look);
    }
    return {
      hx: 2.5, hy: -55, K: 0.82, rec: 1.4, vh: AGENT_VH, liftK: 1,
      squash: false, agentSquash: true
    };
  }
  if (castCfg(look) && castReady(look)) {
    return castAnchor(CAST_CFG[look], cqEff(a), proneK(a), look);
  }
  return null;      /* 敌兵是另一套矢量枪，由调用方自己算 */
}

/* 返回枪口的世界坐标 { x, y, ang }；不认识的外观返回 null。
   第二个参数只是给老调用点留的位（枪始终按 a.aim 画，不跟散布角走）。 */
function muzzlePoint(a) {
  if (!a) return null;
  const an = gunAnchor(a);
  if (!an) return null;

  const cq = cqEff(a);
  /* 姿态图接管时身体不再绕脚底放倒 —— 那张图本来就是躺平的，
     再转 84.6° 会把整个人转到地底下。 */
  const pp = an.poseArt ? POSE_FLAT : pronePose(a, an.vh, an.liftK);
  const pitch = whalePitch(a);
  const mo = motionOf(a);
  /* 外层倾角 = 准星倾身 + 起步倾角（三个 painter 都是「先转再画」） */
  const lean = whaleLean(a) + mo.lean;
  const dip = gunDip(a);

  /* 「掌心 → 枪口」这一段，在枪的局部系里。变换栈是
       scale(K) → translate(-9,-5) → scale 内的后坐 → 换弹的下沉/下垂，
     所以后坐、下沉、下垂都要跟进去 —— 少一样就少几像素。 */
  const tube = GUN_MUZZLE.x - kickOf(a, an);
  const cr = Math.cos(dip.rot), sr = Math.sin(dip.rot);
  const gx = (tube * cr - dip.dy * sr - GUN_GRIP.x) * an.K;
  const gy = (tube * sr + dip.dy * cr - GUN_GRIP.y) * an.K;

  /* 掌心在「脚底系」（原点在脚底、+x = 面朝方向）里的位置。
     趴下时整身先 T(shift,-lift)·R(ang) 放倒，掌心跟着走。 */
  const pc = Math.cos(pp.ang), ps = Math.sin(pp.ang);
  const hx0 = an.hx, hy0 = an.hy;
  let px = pp.shift + hx0 * pc - hy0 * ps;
  let py = -pp.lift + hx0 * ps + hy0 * pc;

  /* 枪的净角：外层 (lean + pp.ang) + 枪内 (pitch - gunLean + dip.rot)，
     gunLean = lean + pp.ang，一进一出抵平 → 相对「倾身系」只剩 pitch - lean + rot */
  const ra = pitch - lean + dip.rot;
  const ca = Math.cos(ra), sa = Math.sin(ra);
  px += gx * ca - gy * sa;
  py += gx * sa + gy * ca;

  /* 起伏：画的时候是 rotate(lean) 之后 translate(0,-bob)，
     所以 bob 加在「转之前」的本地系上，再被 lean 一起转过去 */
  py -= mo.bob;

  /* 整身绕脚底转 lean —— 这一步以前漏了，只在 aim 顶到 ±90° 时才显形：
     倾身 4.9° 下，半径 60px 的枪口会偏出去 5px。平瞄时 lean = 0，
     所以之前量站立/趴下都是准的，一抬头就歪。 */
  if (lean) {
    const cl = Math.cos(lean), sl = Math.sin(lean);
    const nx = px * cl - py * sl, ny = px * sl + py * cl;
    px = nx; py = ny;
  }

  /* 落地挤压：位图两个 painter 的外层都是 scale(1+sq*0.11, 1-sq*0.15) */
  if (an.squash) {
    const sq = clamp(a.landSquash || 0, 0, 1);
    px *= 1 + sq * 0.11;
    py *= 1 - sq * 0.15;
  }
  /* 干员骨架：scale(facing*(1+cq*0.08), 1-cq*0.30+sq*0.06) —— 和位图那两套不是一个公式 */
  if (an.agentSquash) {
    const sq = clamp(a.landSquash || 0, 0, 1);
    px *= 1 + cq * 0.08;
    py *= 1 - cq * 0.30 + sq * 0.06;
  }

  const facing = Math.cos(a.aim) >= 0 ? 1 : -1;
  return { x: a.x + facing * px, y: a.y + py, ang: pitch };
}

/* 后坐距离：枪一开火就往后弹一点，弹的量在缩放里面，所以要乘 K。
   muzzle 是「开火后还剩多少秒」，0.06 秒内线性收回。 */
function kickOf(a, an) {
  return Math.min(1, (a.muzzle || 0) * 12) * (an ? an.rec : 1.5);
}

/* ---------------- 大肥鱼本体 ---------------- */
function drawWhaleGirl(a, isBuddy) {
  if (a.dead) return;
  if (a.downed) { drawDowned(a); return; }

  const h = a.h, sx = a.x - camera.x;
  const facing = Math.cos(a.aim) >= 0 ? 1 : -1;
  const sq = clamp(a.landSquash || 0, 0, 1);
  const t = game.time;

  /* 情绪：0 平静 / 1 得意（开火时翘尾巴）/ 2 慌（你倒了或血太少） */
  let mood = 0;
  if (player && player.downed) mood = 2;
  else if (player && player.hp / Math.max(1, player.maxHp) < 0.34) mood = 2;
  else if ((a.muzzle || 0) > 0.01) mood = 1;

  /* 承托面阴影。a.flatShadow = 菜单立绘：没有世界层可问，
     阴影直接贴脚，否则它会落到上一关某块平台上（画面外） */
  const under = a.flatShadow ? a.y : surfaceBelow(a.x, a.y);
  const gap = a.flatShadow ? 0 : clamp((under - a.y) / 190, 0, 1);
  const sk = 1 - gap * 0.68;
  ctx.fillStyle = 'rgba(0,0,0,' + (0.42 * sk).toFixed(3) + ')';
  ctx.beginPath();
  ctx.ellipse(sx + facing * 2, under + 1, (17 + 26 * proneK(a)) * sk, 4.8 * sk, 0, 0, Math.PI * 2);
  ctx.fill();

  /* 冲刺残影 */
  if ((a.dashTime || 0) > 0) {
    const dir = Math.sign(a.vx) || facing;
    for (let i = 3; i >= 1; i--) {
      ctx.globalAlpha = 0.11 * i;
      ctx.fillStyle = WH.hairM;
      roundRect(sx - dir * i * 9 - 8, a.y - h * 0.86, 16, h * 0.78, 7);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* 二段跳空翻：与人类士兵共用 AIRJUMP_FLIP 时钟，只是旋转中心更高 */
  let flipK = 0, flipAng = 0;
  if ((a.airJumpT || 0) > 0) {
    flipK = clamp(1 - a.airJumpT / AIRJUMP_FLIP, 0, 1);
    const e = flipK * flipK * (3 - 2 * flipK);
    flipAng = (a.flipDir || facing) * Math.PI * 2 * e;
  }
  const pivot = h * 0.56;
  if (flipK > 0 && flipK < 0.82) {
    const al = 0.36 * (1 - flipK / 0.82);
    ctx.strokeStyle = 'rgba(160,226,255,' + al.toFixed(3) + ')';
    ctx.lineWidth = 2.2;
    ctx.lineCap = 'round';
    for (let i = 0; i < 2; i++) {
      const a0 = flipAng - 1.7 - i * 0.5;
      ctx.beginPath();
      ctx.arc(sx, a.y - pivot, h * 0.42 - i * 5, a0, a0 + 1.15);
      ctx.stroke();
    }
  }

  const blink = a.invuln > 0 && Math.floor(a.invuln * 18) % 2 === 0;

  ctx.save();
  ctx.translate(sx, a.y);
  ctx.scale(1 + sq * 0.11, 1 - sq * 0.15);
  if (flipAng) {
    ctx.translate(0, -pivot);
    ctx.rotate(flipAng);
    ctx.translate(0, pivot);
  }
  if (blink) ctx.globalAlpha = 0.5;

  /* 蹲下：整体下沉，裙子跟着塌。
     趴下：不走 drop —— 蹲姿在趴下时已经被 cqEff 压成 0，
     整身另走「绕脚底放倒」（角度见 pronePose），两套姿态不会叠出怪身高。 */
  const cq = cqEff(a);
  const pp = pronePose(a, WHALE_VH, WHALE_LIFT_K);
  const drop = 15 * cq;
  const hipY = -25 + drop;
  const shY = -40 + drop;
  const headY = -50 + drop;

  /* ============================================================
     位图通道：图片解码好就在这儿收工，下面 700 行路径绘制全跳过。
     ============================================================ */
  if (whaleSpriteReady()) {
    /* 握枪图优先：那张是双手已经抱在胸前的持握姿势，枪挂在她的前拳上。
       待机图留作兜底（解码失败、或者以后换素材时的退路）。 */
    const holdUse = whaleHoldReady();
    const img0 = holdUse ? WHALE_SPRITE_HOLD : WHALE_SPRITE;
    const natW = img0.naturalWidth, natH = img0.naturalHeight;
    const spH = WHALE_VH, spW = spH * WHALE_AR;
    /* 脚底锚点跟着图换 —— 两张图的重心不一样，混用会让人横向跳一下 */
    const dx = -spW * (holdUse ? WHALE_FOOT_HOLD : WHALE_FOOT);
    /* 镜像：素材只画了朝右一种，朝左全靠 scale(-1,1) 翻 */
    ctx.scale(facing, 1);

    /* 倾身 + 起步倾角：绕脚底面那个点转，头、肩、枪、腿一起跟着走。
       起步时人先往前倒一点、急停时往后坐一下 —— 重心动得比腿快，
       这就是「不像木头」那一半（见 motionOf）。bob 排在转之后：
       在倾斜的坐标系里上下，脚不会离开地面。 */
    const mo = motionOf(a);
    const lean = whaleLean(a) + mo.lean;
    if (lean) ctx.rotate(lean);
    if (mo.bob) ctx.translate(0, -mo.bob);

    /* 趴下：身段绕脚底放倒，头绕颈部切口抬回去（模型见 util.js 的 proneHead）。
       这一行在 scale(facing,1) 之后，所以 +x 仍然等于「面朝方向」。
       倒下去的时候枪不能跟着转 —— 躺着架枪，枪管是贴着地面的，
       所以下面传给 whaleGunProp 的 lean 要先把放倒的角度扣掉。 */
    const lying = pp.pr > 0.002;
    const gunLean = lean + (lying ? pp.ang : 0);

    /* 脖子切口：直立本地坐标里的一条横线，cutY 是它的 y（向上为负），
       cutH 是切口以上那一段（= 头）的高度。 */
    const cutY = -spH * (1 - WHALE_NECK);
    const cutH = spH * WHALE_NECK;

    /* 放倒变换：身段、腿、枪托全都套这一层。
       头**不套** —— 它要绕切口反着抬回来，套进来就等于没抬。 */
    const bodyXform = () => {
      if (!lying) return;
      ctx.translate(pp.shift, -pp.lift);
      ctx.rotate(pp.ang);
    };

    /* 身段 / 整图。趴下时只画脖子以下，头交给 blitHead 单独摆。 */
    const blit = (img) => {
      if (!img) return;
      if (lying) {
        /* 躺倒后压一点「厚度」（局部 y）。正因为它，两条腿在躺平后不会张成
           一个 V —— 正面像的两腿左右分开，转 85° 就变成上下分开，不压会像
           「躺着蹬腿」。压的是厚度不是长度，所以身高方向一点没变。 */
        ctx.save();
        ctx.scale(1, 1 - WHALE_PRONE_THIN * pp.pr);
        ctx.drawImage(img, 0, natH * WHALE_NECK, natW, natH * (1 - WHALE_NECK),
                      dx, cutY, spW, -cutY + 0.5);
        ctx.restore();
        return;
      }
      if (cq <= 0.01) { ctx.drawImage(img, dx, -spH, spW, spH); return; }
      const { headH, bodyH, total } = whaleBands(cq);
      /* 蹲下不是「上下压扁」，是「折 + 撑」：
         ① shear 绕脚底把上身往前折 —— c 项在 y=0（脚掌）处不产生位移，
            越往上偏得越多，正是一个人收重心往前坐的样子；+x 已等于面朝方向
         ② 髋与裙摆横向撑开，膝盖朝外开、裙子撑成伞形
         ③ 头段一点不缩放（HEAD_K = 1），蹲下去只是整块降下来，脸的比例不变 */
      ctx.save();
      ctx.transform(1, 0, -cq * WHALE_CROUCH_LEAN, 1, 0, 0);
      ctx.scale(1 + cq * WHALE_CROUCH_WIDE * 0.55, 1);
      /* 身段先画（贴地）：+0.5 是补缝，避免两条 drawImage 之间露 1px 背景 */
      ctx.save();
      ctx.scale(1 + cq * WHALE_CROUCH_WIDE * 0.45, 1);
      ctx.drawImage(img, 0, natH * WHALE_NECK, natW, natH * (1 - WHALE_NECK),
                    dx, -bodyH, spW, bodyH + 0.5);
      ctx.restore();
      /* 头段压在身段上（不缩放、不改形）：这里是「一扁就不像人」唯一会破功的地方 */
      ctx.drawImage(img, 0, 0, natW, natH * WHALE_NECK,
                    dx, -total, spW, headH + 0.5);
      ctx.restore();
    };

    /* 头段：只跟着放倒角转 PRONE_HEAD.k 倍（默认 0.3），剩下的角度绕切口反着抬回去。
       绕的是「切口中心」而不是脚底 —— 绕脚底转等于没抬，脸照样扎地里。
       绕中心转会留一道楔形缝：切口宽 spW，转 θ 后后脑那一侧要抬升
       (spW/2)·sinθ。所以沉降量不能写死，直接按这个量算出来，
       让后半边始终埋在身段里。额外再加一点 PRONE_HEAD.pull 把切口藏进衣领。 */
    const blitHead = (img) => {
      if (!img || !lying) return;
      const ncX = dx + spW * 0.5;
      const nh = proneHead(pp, ncX, cutY);
      if (!nh) return;
      const sink = PRONE_HEAD.pull + (spW * 0.5) * Math.abs(Math.sin(nh.ang));
      ctx.save();
      ctx.translate(nh.x, nh.y);
      ctx.rotate(nh.ang);
      ctx.translate(-spW * 0.05, sink);
      ctx.drawImage(img, 0, 0, natW, natH * WHALE_NECK,
                    dx - ncX, -cutH, spW, cutH + 0.5);
      ctx.restore();
    };

    /* ------------------------------------------------------------
       腿：拆件后单独摆
       ------------------------------------------------------------
       只有持枪图拆（idle 是兜底图，腿是并拢的一整片，拆不出两块）。
       **蹲下也拆** —— 这是「蹲」读得出来的关键：腿片顶端挂到裙摆下沿，
       脚底钉在地面，可见腿长自己缩短。不拆的话，腿要跟着身段一起压，
       读起来就是「把整张图纵向缩短」，正是「蹲下只是压扁」那个毛病。
       画序：后腿 → 前腿 → 躯干。躯干上面是被 clearRect 挖空的，
       所以腿片伸进裙摆的那一截一定会被裙子盖住，切口永远看不见。
       ------------------------------------------------------------ */
    const parts = holdUse ? whaleLegParts(img0) : null;
    /* 趴下时**不拆件**。这里踩过一个坑，值得写下来：
       原来条件是 `cq <= 0.02` 就算拆，而趴下时 cqEff = crouch·(1-proneK) 恰好是 0
       —— 于是趴下正好落进拆件分支，而那个分支只画 body，**不调 blitHead**，
       头就整个没了（只剩头发和躯干躺在地上）。蹲下时反而不触发，因为 cq 是 1。
       两条判据各管一种姿态，别再合成一个：
         · 蹲下：cq = 1 → 不拆（腿片塞不进两段压缩的坐标里）
         · 趴下：cq = 0 但 pr = 1 → 也不能拆，必须整图 + 头段单独摆 */
    const splitOn = !!parts && pp.pr < 0.002;
    const u = spW / 116;            /* 立绘像素 → 屏幕像素（等比，u == v） */

    const blitLeg = (key, useSil, gait) => {
      const R = WHALE_LEG[key];
      const g = gait[key];
      const cv = useSil ? whalePartSil(parts, key) : parts.legs[key];
      if (!cv) return;
      /* 腿片**不缩放、不变形**，永远按原尺寸画在原来的位置，脚底钉在地面。
         蹲下的降高靠躯干那边：身段压缩后，身体上被 clearRect 挖空的那块
         （裙摆下缘以下）跟着上移，于是腿被裙子盖住得多、露出来的少。
         结果就是「蹲着只看得见小腿和鞋」，而鞋一点没扁 —— 这是拆腿真正
         换来的东西。反过来做（把腿片压短）鞋会跟着压扁，那还不如不拆。 */
      const ox = dx + R.sx * u;
      const oy = -spH + R.sy * u - g.lift * u;      /* lift 是立绘像素，往上抬 */
      /* 旋转中心 = 髋点，换算成「相对腿片左上角」的偏移。
         注意：translate 已经把腿片左上角挪到了原点，所以下面 drawImage
         必须画在 (0,0) —— 再写一次 (ox,oy) 就等于平移两遍，
         腿会被推到裙子底下，看着像凭空消失了。
         绕 pivot 转的写法：先移到 pivot、转、再移回来。 */
      const px = (R.pivotX - R.sx) * u, py = (R.pivotY - R.sy) * u;
      ctx.save();
      ctx.translate(ox + px, oy + py);
      ctx.rotate(g.rot);
      ctx.translate(-px, -py);
      ctx.drawImage(cv, 0, 0, cv.width, cv.height, 0, 0, R.sw * u, R.sh * u);
      ctx.restore();
    };

    const blitLegs = (useSil) => {
      const gait = whaleGait(a, t, cq);
      blitLeg('back', useSil, gait);
      blitLeg('front', useSil, gait);
    };

    if (splitOn) {
      ctx.save(); bodyXform();
      whaleGunProp(a, cq, gunLean, 'back');   /* 枪托/弹匣塞在身体后面 */
      blitLegs(false);
      blit(parts.body);
      ctx.restore();
      /* 'front' 这趟（机匣 + 枪管）必须排在头之后、且留在 bodyXform 里：
         · 排头之后 —— 趴下时枪口正好在脸颊高度，画在头下面会被脸整个吞掉
           （主角的头盔是一整个球，尤其明显），只剩一小截枪管露在外面；
         · 留在 bodyXform 里 —— gunLean 含 +pp.ang、whaleGunProp 内部再减掉，
           一进一出抵平，净角度 = pitch；放外面画那 -pp.ang 没人抵，枪管会竖起来。 */
      ctx.save(); bodyXform();
      whaleGunProp(a, cq, gunLean, 'front');
      ctx.restore();
    } else {
      ctx.save(); bodyXform();
      whaleGunProp(a, cq, gunLean, 'back');
      blit(img0);
      ctx.restore();
      blitHead(img0);
      ctx.save(); bodyXform();
      whaleGunProp(a, cq, gunLean, 'front');
      ctx.restore();
    }

    /* 受击红闪：用 sprite 的 alpha 做遮罩的纯红剪影，叠上去。
       不能直接 fillRect —— 那会把背后的关卡一起染红。
       拆件时两块腿也要各自红一遍，否则红影子会顶着一双不动的腿。 */
    if (a.flash > 0) {
      ctx.globalAlpha = Math.min(0.5, a.flash * 2.2);
      ctx.save(); bodyXform();
      if (splitOn) {
        blitLegs(true);
        blit(whalePartSil(parts, 'body'));
      } else {
        blit(whaleTintCanvas(img0));
      }
      ctx.restore();
      blitHead(splitOn ? whalePartSil(parts, 'body') : whaleTintCanvas(img0));
      ctx.globalAlpha = 1;
    }
    ctx.restore();
    /* 名牌：位图比碰撞盒高出一截，锚点要按视觉高度重算，否则会被头发盖住。
       注意 whaleRowY 返回的是「脚底 = 0、向上为负」的本地 y，所以是 **加**
       不是减 —— 写成 a.y - whaleRowY(0,cq) 等于 a.y + 96，
       名牌会掉到她脚下 90px 的土里（这就是「血条位置不对」）。
       8px 是给顶上那撮呆毛留的净空。
       趴下时位图整体躺倒，视觉顶边只剩一个身厚，锚点改按受击盒顶走，
       否则名牌会飘在她上方 80px 的空中。 */
    if (isBuddy) {
      const topY = pp.pr > 0.02 ? a.y - PRONE_PLATE : a.y + whaleRowY(0, cq) - 8;
      drawBuddyPlate(a, sx, topY);
    }
    return;
  }

  /* 腿：走跑摆腿 + 空翻团身收膝 */
  let swA, knA, swB, knB;
  if (!a.onGround) { swA = 0.46; knA = 0.95; swB = -0.42; knB = 0.3; }
  else if (Math.abs(a.vx) > 28) {
    const ph = a.anim;
    swA = Math.sin(ph) * 0.5; swB = Math.sin(ph + Math.PI) * 0.5;
    knA = Math.max(0, Math.sin(ph + 2.1)) * 0.55;
    knB = Math.max(0, Math.sin(ph + Math.PI + 2.1)) * 0.55;
  } else { swA = -0.05; knA = 0.1; swB = 0.06; knB = 0.1; }

  if (cq > 0.02) {
    const fF = legIK(3 * facing, hipY, 3 * facing + 10 * facing, 0.5);
    const fB = legIK(-3 * facing, hipY, -3 * facing - 8 * facing, 0.5);
    swA = lerp(swA, fF.swing, cq); knA = lerp(knA, fF.knee, cq);
    swB = lerp(swB, fB.swing, cq); knB = lerp(knB, fB.knee, cq);
  }
  if (flipK > 0 && flipK < 1) {
    const tk = Math.sin(Math.PI * clamp(flipK, 0, 1));
    swA = lerp(swA, 1.15, tk * 0.9); knA = lerp(knA, 1.9, tk * 0.9);
    swB = lerp(swB, 0.95, tk * 0.9); knB = lerp(knB, 1.8, tk * 0.9);
  }

  /* 趴下：路径小人整身绕脚底放倒（位图通道在上面已经放过了）。
     这套兜底只在立绘解码失败时出现，所以不追求细节，只求「别站着趴」。 */
  const lyingPath = pp.pr > 0.002;
  if (lyingPath) {
    ctx.translate(facing * pp.shift, -pp.lift);
    ctx.rotate(facing * pp.ang);
  }

  whaleTail(facing, hipY, mood, t, a.vx || 0);
  whaleHairBack(facing, headY, hipY, t, a.vx || 0, mood);

  /* 后腿（暗一档，拉开前后层次） */
  const bl = whaleLeg(-2.6 * facing, hipY, swB, knB, 6.6);
  ctx.globalAlpha *= 1;
  /* 前腿 */
  const fl = whaleLeg(2.8 * facing, hipY, swA, knA, 7);

  /* ---- 裙子：上窄下阔，下摆有褶 ---- */
  ctx.beginPath();
  ctx.moveTo(-6.2, hipY - 9);
  ctx.quadraticCurveTo(-9.5, hipY + 3, -10.5, hipY + 8.5);
  ctx.quadraticCurveTo(0, hipY + 11.5, 10.5, hipY + 8.5);
  ctx.quadraticCurveTo(9.5, hipY + 3, 6.2, hipY - 9);
  ctx.closePath();
  wPath(WH.dress, 1.6);
  /* 褶 */
  ctx.strokeStyle = WH.dressD;
  ctx.lineWidth = 1.1;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 3.4, hipY - 7);
    ctx.lineTo(i * 5.6, hipY + 9.4);
    ctx.stroke();
  }
  /* 裙摆白边 */
  ctx.strokeStyle = WH.apron;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-10.4, hipY + 7.6);
  ctx.quadraticCurveTo(0, hipY + 10.6, 10.4, hipY + 7.6);
  ctx.stroke();

  /* ---- 上身 ---- */
  ctx.beginPath();
  ctx.moveTo(-5.6, shY + 1);
  ctx.quadraticCurveTo(-6.6, hipY - 8, -5.4, hipY - 3);
  ctx.lineTo(5.4, hipY - 3);
  ctx.quadraticCurveTo(6.6, hipY - 8, 5.6, shY + 1);
  ctx.quadraticCurveTo(0, shY - 2.4, -5.6, shY + 1);
  ctx.closePath();
  wPath(WH.dress, 1.6);

  /* 围裙：胸前一片 + 腰下裙摆 */
  ctx.beginPath();
  ctx.moveTo(-4.2, shY + 2.5);
  ctx.lineTo(4.2, shY + 2.5);
  ctx.lineTo(3.6, hipY - 8);
  ctx.lineTo(-3.6, hipY - 8);
  ctx.closePath();
  wPath(WH.apron, 1.2);
  /* 围裙肩带 */
  ctx.strokeStyle = WH.apron;
  ctx.lineWidth = 1.8;
  ctx.beginPath(); ctx.moveTo(-4, shY + 2.6); ctx.lineTo(-5.2, shY - 1); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(4, shY + 2.6); ctx.lineTo(5.2, shY - 1); ctx.stroke();
  /* 小鲸鱼徽章 */
  ctx.fillStyle = WH.ribbon;
  ctx.beginPath();
  ctx.ellipse(0.4, shY + 8, 2.2, 1.5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(2.4, shY + 7.6);
  ctx.lineTo(4, shY + 6); ctx.lineTo(4, shY + 9);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.85)';
  ctx.beginPath(); ctx.arc(-0.4, shY + 7.6, 0.6, 0, Math.PI * 2); ctx.fill();

  /* 腰后蝴蝶结 */
  ctx.beginPath();
  ctx.moveTo(-facing * 5, hipY - 9);
  ctx.lineTo(-facing * 10.5, hipY - 12);
  ctx.lineTo(-facing * 10, hipY - 5.5);
  ctx.closePath();
  wPath(WH.ribbon, 1.1);

  /* ---- 枪与手臂 ----
     身体已经放倒，枪要扣掉同样的角度，躺在那里也是平着架的 */
  whaleGun(a, facing, shY, lyingPath ? a.aim - facing * pp.ang : a.aim);

  /* ---- 定义脸/头（先算好给头发和头饰用） ---- */
  const hx = facing * 1.4;

  /* ---- 侧发：耳前一绺，从鬓角垂到胸口 ----
     侧身视角只能看到「靠镜头这一侧」的一绺。原来画在 facing*6.6~9.2（脸的正前方），
     和现在收窄的侧脸打架；挪到 6.4~8.2，正好压在耳根前面，垂到 headY+19（胸口）。 */
  ctx.beginPath();
  ctx.moveTo(hx + facing * 6.4, headY - 4.2);
  ctx.quadraticCurveTo(hx + facing * 8.6, headY + 7, hx + facing * 7.2, headY + 19);
  ctx.quadraticCurveTo(hx + facing * 5.0, headY + 17.5, hx + facing * 4.8, headY + 6);
  ctx.closePath();
  wPath(WH.hairM, 1.4);
  /* 发梢冰蓝：这一绺的尾端必须换色，否则长发在深色裙子上糊成一根柱子 */
  ctx.beginPath();
  ctx.moveTo(hx + facing * 7.2, headY + 19);
  ctx.quadraticCurveTo(hx + facing * 6.0, headY + 20, hx + facing * 5.0, headY + 17.5);
  ctx.quadraticCurveTo(hx + facing * 6.4, headY + 14.5, hx + facing * 6.8, headY + 11);
  ctx.closePath();
  wPath(WH.hairL, 0);

  /* ---- 头：#侧脸剪影# ----
     原来是正圆 ellipse，配两只对称的眼睛 —— 整体镜像翻转，读成「正面小玩偶」。
     横版游戏里角色永远朝左或朝右，正圆头在侧面是错的。改成真正的侧脸剪影：
       额 → 眉骨下压 → 鼻梁内收 → 小翘鼻 → 人中 → 上唇 → 下巴 → 下颌线 → 后脑。
     关键：鼻尖只凸出 1.3px（faceX 8.2 → 9.5）。56px 的角色上再大就没有「Q」味，
     变成猴脸；1.0~1.4 刚好够在 1x 下读出一个尖。
     后脑比原来鼓出去 1.4（-8.8 → -10.0），给后面的长发一个落点。 */
  const FX = hx + facing * 8.2;   /* 面部基准竖直切线：额头/鼻梁都贴在这条线附近 */
  ctx.beginPath();
  ctx.moveTo(hx - facing * 8.8, headY + 1.6);                                            /* 后脑下 */
  ctx.quadraticCurveTo(hx - facing * 10.0, headY - 3.0, hx - facing * 7.4, headY - 7.8);  /* 后脑枕骨 */
  ctx.quadraticCurveTo(hx - facing * 4.6, headY - 10.9, hx - facing * 0.2, headY - 10.5); /* 头顶 */
  ctx.quadraticCurveTo(hx + facing * 5.6, headY - 10.1, hx + facing * 7.9, headY - 5.6);  /* 额头斜坡 */
  ctx.quadraticCurveTo(hx + facing * 8.6, headY - 2.8, FX, headY + 0.2);                  /* 眉骨 → 鼻梁内收 */
  ctx.quadraticCurveTo(FX - facing * 0.3, headY + 0.3, hx + facing * 10.1, headY + 1.9);  /* 鼻尖（小翘鼻，凸 1.9） */
  ctx.quadraticCurveTo(hx + facing * 10.5, headY + 2.7, hx + facing * 8.7, headY + 2.95); /* 鼻底（急收，鼻头才翘） */
  ctx.quadraticCurveTo(hx + facing * 8.85, headY + 4.1, hx + facing * 8.3, headY + 4.8);  /* 上唇 */
  ctx.quadraticCurveTo(hx + facing * 7.95, headY + 5.5, hx + facing * 8.15, headY + 6.2); /* 下唇 */
  ctx.quadraticCurveTo(hx + facing * 7.1, headY + 8.5, hx + facing * 4.0, headY + 8.7);   /* 下巴 */
  ctx.quadraticCurveTo(hx + facing * 0.8, headY + 8.9, hx - facing * 1.8, headY + 7.0);   /* 下颌线 */
  ctx.quadraticCurveTo(hx - facing * 5.8, headY + 6.2, hx - facing * 7.8, headY + 4.4);   /* 腮后 */
  ctx.quadraticCurveTo(hx - facing * 8.9, headY + 3.4, hx - facing * 8.8, headY + 1.6);   /* 收口 */
  ctx.closePath();
  wPath(WH.skin, 1.6);

  /* 耳前阴影：侧脸必须有这一块，否则后脑和脸连成一片饼 */
  /* 耳前阴影：侧脸必须有这一块，否则后脑和脸连成一片饼。
     上一版 0.16 太淡，在 1x 下完全读不出 —— 加大到 0.30 并往上延伸到鬓角，
     让「脸」和「后方头发」之间出现一条硬的分界。 */
  ctx.beginPath();
  ctx.ellipse(hx - facing * 5.4, headY + 1.8, 3.4, 5.6, facing * 0.15, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(186,132,104,0.30)';
  ctx.fill();

  /* 下巴阴影 */
  ctx.beginPath();
  ctx.ellipse(hx + facing * 2.2, headY + 7.6, 4.4, 1.9, 0, 0, Math.PI);
  ctx.fillStyle = 'rgba(200,150,120,0.28)';
  ctx.fill();

  /* ---- 侧身发型 ----
     照设定稿：脸只占头的前下方一小块椭圆，其余全是头发。
     上一版把刘海边停在 -4.8（眉毛上方），露出 5px 的额头 → 又变回「发际线高」。
     设定稿的刘海是**斜扫**下来的：前额那一束一直压到眼睛外角。
     外轮廓 5 折：后颈发根 → 枕骨（比头鼓 2.2）→ 头顶（-12.8）→ 前额外缘（+9.6）→ 前鬓角
     刘海边 3 尖 2 凹：尖到 -1.2 / -3.2 / -4.4，凹到 -5.6 / -8.0。
     尖间距 4.4 —— 56px 上小于 3.5 的间距会糊成锯齿噪点，不是发丝。 */
  function hairOuter() {
    ctx.moveTo(hx - facing * 8.6, headY + 4.6);
    ctx.quadraticCurveTo(hx - facing * 11.2, headY - 1.0, hx - facing * 9.0, headY - 7.0);
    ctx.quadraticCurveTo(hx - facing * 7.0, headY - 12.4, hx - facing * 0.6, headY - 12.8);
    ctx.quadraticCurveTo(hx + facing * 5.8, headY - 12.4, hx + facing * 8.8, headY - 7.4);
    ctx.quadraticCurveTo(hx + facing * 10.0, headY - 5.6, hx + facing * 9.6, headY - 4.2);
  }
  ctx.beginPath();
  hairOuter();
  /* 刘海底缘 #v5#：上一版凹到 -5.6 / -8.0，那是「三束独立发绺」的画法，
     在 56px 上读成「额头上开了两个洞」—— 露出的肤色面积比头发还大，
     一眼又是「发际线高」。设定稿的刘海是**一片**盖上来的，只在边缘起小浪。
     所以凹陷抬到 -4.2 / -5.2，起伏只有 3.8，全程贴着上眼线（-3.1）上方不到 3px。 */
  ctx.quadraticCurveTo(hx + facing * 8.9, headY - 2.4, hx + facing * 8.2, headY - 1.4);   /* 尖 1：压到外眼角 */
  ctx.quadraticCurveTo(hx + facing * 7.2, headY - 3.2, hx + facing * 6.2, headY - 4.2);   /* 凹 */
  ctx.quadraticCurveTo(hx + facing * 5.0, headY - 3.4, hx + facing * 3.8, headY - 3.4);   /* 尖 2 */
  ctx.quadraticCurveTo(hx + facing * 2.2, headY - 4.6, hx + facing * 0.6, headY - 5.2);   /* 凹 */
  ctx.quadraticCurveTo(hx - facing * 1.2, headY - 4.8, hx - facing * 2.6, headY - 4.6);   /* 尖 3 */
  /* 后鬓角落到颈侧：不落下来，后脑就露出一个光秃的缺口 */
  ctx.quadraticCurveTo(hx - facing * 6.0, headY - 6.4, hx - facing * 8.6, headY + 4.6);
  ctx.closePath();
  ctx.fillStyle = WH.hairM;
  ctx.fill();

  /* 刘海内侧压暗：侧身只看得到一束刘海，没有这道暗面，整块蓝就是平涂 */
  ctx.beginPath();
  ctx.moveTo(hx + facing * 9.2, headY - 4.4);
  ctx.quadraticCurveTo(hx + facing * 8.8, headY - 1.6, hx + facing * 8.1, headY - 1.4);
  ctx.quadraticCurveTo(hx + facing * 8.6, headY - 3.4, hx + facing * 8.8, headY - 5.4);
  ctx.closePath();
  ctx.fillStyle = WH.hairD;
  ctx.globalAlpha = 0.4;
  ctx.fill();
  ctx.globalAlpha = 1;

  /* 发流线：两笔 hairD 把发团拆成「前刘海 / 中顶 / 后枕」三束 */
  ctx.strokeStyle = WH.hairD;
  ctx.lineWidth = 0.7;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(hx + facing * 5.6, headY - 11.6);
  ctx.quadraticCurveTo(hx + facing * 6.4, headY - 9.0, hx + facing * 6.2, headY - 5.8);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(hx - facing * 0.4, headY - 12.4);
  ctx.quadraticCurveTo(hx - facing * 1.8, headY - 9.4, hx - facing * 2.2, headY - 6.6);
  ctx.stroke();

  /* 外轮廓：厚描边（只描外圈，刘海边不描 —— 上一轮踩过的坑，别再改回去） */
  ctx.beginPath();
  hairOuter();
  ctx.strokeStyle = WH.ink;
  ctx.lineWidth = 1.5;
  ctx.lineCap = 'round';
  ctx.stroke();
  /* 刘海边中段按 0.8 描 ink 会糊：眉毛上沿 -3.62、刘海尖 -4.8，中间只剩 1.18px 皮肤，
     抗锯齿把「发下沿 + 眉 + 上眼线」压成一道灰蓝黑杠。蓝对肤明度差 60 以上，
     fill 的硬边界本身就是发际线。只保留「后鬓角 → 颈侧」这一折：那段贴着腮和脖子，
     不描的话头发会糊进下巴阴影。 */
  ctx.beginPath();
  ctx.moveTo(hx - facing * 2.6, headY - 4.4);
  ctx.quadraticCurveTo(hx - facing * 6.0, headY - 6.4, hx - facing * 8.6, headY + 4.6);
  ctx.strokeStyle = WH.ink;
  ctx.lineWidth = 0.7;
  ctx.stroke();

  /* 头顶高光：#拆成两段#。
     单条连续高光沿着头顶弧走，等于给发团描了一道反光边 —— 那是头盔/塑料壳的特征，
     不是头发。头发的高光是「几缕受光」，中间必须有断。断口就落在发流线上。 */
  ctx.strokeStyle = WH.hairL;
  ctx.lineCap = 'round';
  ctx.globalAlpha = 0.5;
  ctx.lineWidth = 1.7;
  ctx.beginPath();
  ctx.moveTo(hx - facing * 7.0, headY - 8.6);
  ctx.quadraticCurveTo(hx - facing * 3.6, headY - 12.0, hx - facing * 0.2, headY - 11.4);
  ctx.stroke();
  ctx.globalAlpha = 0.38;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(hx + facing * 1.8, headY - 10.6);
  ctx.quadraticCurveTo(hx + facing * 4.2, headY - 9.6, hx + facing * 6.0, headY - 7.6);
  ctx.stroke();
  ctx.globalAlpha = 1;

  /* ---- 鱼鳍耳：耳后一扇，三根鳍刺朝后发散 ----
     正面版是对称的两瓣（左右各一），侧身只能有靠镜头这一只，位置要在「耳后」。
     v1 两刺太窄 → 读成「一根白色斜刺」；v2 加到三刺，但 y 跨 -1.2~+5.6（6.8px）——
     在 19px 宽的头上等于竖着嵌了一块板，11× 下是「碎冰 / 玻璃碴」。
     扇必须**横向张**：y 跨收到 3.7，尖端从 -14.4 收到 -12.2（凸出 4.2 就够），
     鳍刺之间的凹口加深到 1.6，让三根刺真的分开。 */
  ctx.beginPath();
  ctx.moveTo(hx - facing * 8.0, headY - 0.6);
  ctx.quadraticCurveTo(hx - facing * 10.4, headY - 1.6, hx - facing * 12.2, headY - 1.9);  /* 上刺 */
  ctx.quadraticCurveTo(hx - facing * 10.8, headY - 0.2, hx - facing * 10.4, headY + 0.4);
  ctx.quadraticCurveTo(hx - facing * 12.0, headY + 0.9, hx - facing * 12.3, headY + 1.9);  /* 中刺 */
  ctx.quadraticCurveTo(hx - facing * 10.7, headY + 1.9, hx - facing * 10.2, headY + 2.4);
  ctx.quadraticCurveTo(hx - facing * 11.0, headY + 3.0, hx - facing * 10.2, headY + 3.7);  /* 下刺 */
  ctx.quadraticCurveTo(hx - facing * 8.8, headY + 3.2, hx - facing * 7.8, headY + 2.2);    /* 回耳根 */
  ctx.closePath();
  wPath(WH.tailL, 1.0);
  /* 三根鳍条：一根一根从耳根发出去，鳍的「放射」感全靠这个 */
  ctx.strokeStyle = WH.ribbonD;
  ctx.globalAlpha = 0.75;
  ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.moveTo(hx - facing * 8.4, headY + 0.9);
  ctx.lineTo(hx - facing * 11.7, headY - 1.5);
  ctx.moveTo(hx - facing * 8.4, headY + 1.2);
  ctx.lineTo(hx - facing * 11.8, headY + 1.9);
  ctx.moveTo(hx - facing * 8.4, headY + 1.5);
  ctx.lineTo(hx - facing * 9.9, headY + 3.4);
  ctx.stroke();
  ctx.globalAlpha = 1;

  /* ---- 眼睛：只画一只 ----
     这是「从正面小玩偶变成侧面站立的人」最关键的一处。
     两眼对称 = 正面；侧脸就只能露出一只。位置必须在面部前缘之内：
     脸缘在 +8.2，眼占 +1.7~+7.1，留 1.1 的边，不然眼白会压到侧脸线上。 */
  const blinkNow = Math.sin(t * 1.9 + (a.seed || 0) * 7) > 0.986;
  const eyeY = headY + 0.8;
  const ex = hx + facing * 4.4;
  const eOpen = blinkNow ? 0.16 : 1;
  ctx.beginPath();
  ctx.ellipse(ex, eyeY, 2.75, 3.4 * eOpen + 0.4, 0, 0, Math.PI * 2);
  ctx.fillStyle = '#fdfdff';
  ctx.fill();
  if (eOpen > 0.5) {
    ctx.beginPath();
    ctx.ellipse(ex + facing * 0.35, eyeY + 0.3, 2.25, 2.9, 0, 0, Math.PI * 2);
    ctx.fillStyle = mood === 2 ? '#3a6fa8' : WH.eye;
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(ex + facing * 0.35, eyeY + 0.5, 1.15, 1.7, 0, 0, Math.PI * 2);
    ctx.fillStyle = WH.eyeD;
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(ex + facing * 0.6 - 0.8, eyeY - 1.1, 0.95, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(ex - facing * 0.9, eyeY + 1.9, 0.5, 0, Math.PI * 2);
    ctx.fill();
    /* 得意时上眼皮压下来（半眯） */
    if (mood === 1) {
      ctx.fillStyle = WH.skin;
      ctx.beginPath();
      ctx.ellipse(ex, eyeY - 1.7, 2.9, 1.9, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = WH.ink;
      ctx.lineWidth = 0.9;
      ctx.beginPath();
      ctx.moveTo(ex - 2.6, eyeY - 1.6);
      ctx.lineTo(ex + 2.6, eyeY - 2.1);
      ctx.stroke();
    }
  }
  /* 上眼线：外眼角带一个小勾 —— 侧脸的眼线不勾，眼睛会像贴在脸上的贴纸 */
  ctx.strokeStyle = WH.ink;
  ctx.lineWidth = 1.25;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(ex - facing * 2.9, eyeY - 2.4 * eOpen);
  ctx.quadraticCurveTo(ex, eyeY - 3.9 * eOpen, ex + facing * 2.9, eyeY - 2.2 * eOpen);
  ctx.stroke();
  ctx.lineWidth = 0.9;
  ctx.beginPath();
  ctx.moveTo(ex + facing * 2.7, eyeY - 2.2);
  ctx.lineTo(ex + facing * 3.9, eyeY - 3.1);
  ctx.stroke();
  /* 眉毛：只一根，短、平、略下垂（傲娇脸的下垂眉）。
     上一版放在 eyeY-5.1，可上眼线在 eyeY-3.9、自身 1.25 宽 ——
     两者中心只差 1.2px，加减描边后完全叠成一坨，「没有眉毛」。
     眉毛必须独立成一条：抬到 -6.0，与上眼线留 2.1 的空隙，线宽收到 0.75。 */
  ctx.strokeStyle = WH.hairD;
  ctx.lineWidth = 0.75;
  ctx.beginPath();
  if (mood === 2) {
    ctx.moveTo(ex - facing * 2.4, eyeY - 6.5);
    ctx.lineTo(ex + facing * 2.2, eyeY - 5.4);
  } else if (mood === 1) {
    ctx.moveTo(ex - facing * 2.4, eyeY - 5.6);
    ctx.lineTo(ex + facing * 2.3, eyeY - 6.4);
  } else {
    ctx.moveTo(ex - facing * 2.3, eyeY - 6.1);
    ctx.lineTo(ex + facing * 2.3, eyeY - 6.3);
  }
  ctx.stroke();

  /* 腮红：侧脸只有一块，压在眼下方偏后 */
  ctx.fillStyle = 'rgba(240,140,150,0.32)';
  ctx.beginPath();
  ctx.ellipse(hx + facing * 4.2, headY + 4.6, 2.6, 1.5, facing * 0.1, 0, Math.PI * 2);
  ctx.fill();

  /* 嘴：贴在侧脸前缘，小、一点点嘟 —— 正面的「居中嘴」在侧脸上是错的 */
  ctx.strokeStyle = WH.ink;
  ctx.lineWidth = 0.95;
  ctx.lineCap = 'round';
  ctx.beginPath();
  if (mood === 2) {
    ctx.ellipse(hx + facing * 7.9, headY + 4.9, 1.0, 1.5, 0, 0, Math.PI * 2);
  } else if (mood === 1) {
    ctx.moveTo(hx + facing * 7.3, headY + 4.6);
    ctx.quadraticCurveTo(hx + facing * 8.5, headY + 5.6, hx + facing * 8.7, headY + 4.0);
  } else {
    ctx.moveTo(hx + facing * 7.5, headY + 4.8);
    ctx.quadraticCurveTo(hx + facing * 8.2, headY + 5.3, hx + facing * 8.7, headY + 4.6);
  }
  ctx.stroke();

  /* 慌的时候冒一滴汗：挪到太阳穴上方，不能压在刘海上 */
  if (mood === 2) {
    ctx.fillStyle = 'rgba(150,215,245,0.9)';
    ctx.beginPath();
    ctx.moveTo(hx + facing * 6.4, headY - 8.6);
    ctx.quadraticCurveTo(hx + facing * 8.0, headY - 5.8, hx + facing * 6.4, headY - 5.0);
    ctx.quadraticCurveTo(hx + facing * 4.9, headY - 6.2, hx + facing * 6.4, headY - 8.6);
    ctx.closePath();
    ctx.fill();
  }

  /* ---- 女仆头饰：窄发带 + 侧蝴蝶结 ----
     迭代记录（别再往回改）：
       ① 最早 r=9.2 / 带宽 3.4 / 跨 1.13π~1.87π，两端落到 headY-4.4（眉毛高度）
          —— 一条粗白弧盖住整个头顶，蓝发只剩额前一条边。这是「发际线高」的主因。
       ② 改成 5 颗连续扇贝，带宽收到 1.5。18 倍放大看到扇贝确实出来了，
          但在 1x 下完全读不出 —— 5 颗 r=1.4 的圆压在 1.5px 的带上，
          边缘全是半像素抖动，整体反而读成「头顶一块斜贴的白色窄条 / 刀片」。
          而且白区宽度 13~16px，头宽才 19px，白:蓝 ≈ 1:1，还是「戴了白帽子」。
       ③ 现在：去掉扇贝，改一条干净的窄带。判断依据是**面积比**——
          带宽 1.2、蓝发在带的上方留 2.9px（到外轮廓 -12.4）、下方留 4.1px（到发际线 -5.4），
          蓝:白 ≈ 7:1.2，一眼就是「头发上的带子」，不可能是帽子。
          细节只留两条：上沿一条 apronS 定边，内侧一条 hairD 阴影让带子「嵌」进头发。 */
  /* 白带本体：#实心月牙 + 墨线描边#。
     前两版都是「一条浅色 stroke」，9 倍放大看全是毛病：
       v1 贴发团外缘走 → 半条露在剪影外，读成悬空的白圈（耳机头梁）；
       v2 压进发团内部 → 上边缘只剩 2.1px 蓝发，和剪影描边糊在一起，还是光环。
     根因不是位置，是**没有轮廓线**：浅色细线放在深色块上，永远读成「光」不会读成「布」。
     改成两条椭圆弧围成的实心月牙、外描 1.0 ink，并且让上下各留 3 的蓝发。 */
  /* v4：带宽 1.7 是错的。1.0 的描边居中画，内外各吃掉 0.5，净白只剩 0.7px ——
     在 1x 下就是一根白线，11× 放大看是**两条平行白线**（描边把中间挤没了）。
     布必须有实宽：BW 3.2、描边收到 0.8，净白 2.4px，才撑得住「一条带子」。
     角度也改成非对称：后端 1.26π（y -7.6）比前端 1.80π（y -6.1）高 1.5，
     弦是斜的 —— 设定稿的荷叶边就是斜跨，正跨会读成「箍在头上的白圈」。 */
  const RC = headY - 0.4;
  const RBX = 7.0, RBY = 7.2, BW = 3.2;
  const A0 = Math.PI * 1.26, A1 = Math.PI * 1.80;
  /* 带子压在头发上的投影：先铺一道 hairD 淡淡的暗，带子才「嵌」进去而不是浮着 */
  ctx.beginPath();
  ctx.ellipse(hx, RC + 0.5, RBX + BW, RBY + BW, 0, A0 - 0.03, A1 + 0.03);
  ctx.strokeStyle = WH.hairD;
  ctx.globalAlpha = 0.55;
  ctx.lineWidth = 1.6;
  ctx.stroke();
  ctx.globalAlpha = 1;
  ctx.beginPath();
  ctx.ellipse(hx, RC, RBX + BW, RBY + BW, 0, A0, A1);
  ctx.ellipse(hx, RC, RBX, RBY, 0, A1, A0, true);
  ctx.closePath();
  wPath(WH.apron, 0.8);
  /* 内沿一条 apronS：布是有厚度的，只有轮廓线会读成「贴纸」 */
  ctx.beginPath();
  ctx.ellipse(hx, RC, RBX + 0.9, RBY + 0.9, 0, A0 + 0.06, A1 - 0.06);
  ctx.strokeStyle = WH.apronS;
  ctx.lineWidth = 0.55;
  ctx.stroke();
  /* 荷叶边不点小凸：v2 的「5 颗扇贝」在 18× 下像褶、在 1x 下全是半像素抖动，
     整体反而读成一块斜贴的白刀片。56px 上荷叶边只能靠「厚度 + 两色分级」暗示。 */

  /* 蝴蝶结：挂在发带的#后端#（后脑勺一侧），也就是弧的终点。
     正面版打在前额，侧脸看就是「结长在脸上」。第一版挪到 -8.4 时读成「一根蓝刺」——
     因为两瓣太窄（宽度只有长度的 0.8）。现在两瓣各自做成梯形，宽度撑到 3.2。 */
  const bx = hx - facing * 6.7, by = headY - 6.4;
  ctx.beginPath();
  ctx.moveTo(bx, by - 1.0);
  ctx.lineTo(bx - facing * 3.0, by - 2.4);
  ctx.lineTo(bx - facing * 3.2, by + 1.4);
  ctx.lineTo(bx, by + 1.0);
  ctx.closePath();
  wPath(WH.ribbon, 0.9);
  ctx.beginPath();
  ctx.moveTo(bx, by - 1.0);
  ctx.lineTo(bx + facing * 2.6, by - 2.0);
  ctx.lineTo(bx + facing * 2.8, by + 1.6);
  ctx.lineTo(bx, by + 1.0);
  ctx.closePath();
  wPath(WH.ribbonD, 0.9);
  /* 结：压在中间，两瓣才不会连成一块梭形 */
  ctx.beginPath();
  ctx.ellipse(bx, by, 1.0, 1.3, 0, 0, Math.PI * 2);
  wPath(WH.ribbon, 0.9);

  /* ---- 呆毛 ----
     1.7 读成「头顶的提手」，0.9 读成「耳机线」。1.3 + 长度只有 3.5 才像一撮翘毛。
     落点要从发旋（-0.6, -12.8）稍偏后起，往前翘 —— 侧脸的呆毛朝前才读得动。 */
  const ah = Math.sin(t * 2.6 + (a.seed || 0) * 5);
  ctx.strokeStyle = WH.hairM;
  ctx.lineWidth = 1.3;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(hx - facing * 1.8, headY - 11.8);
  ctx.quadraticCurveTo(hx + facing * (0.4 + ah * 0.8), headY - 15.6, hx + facing * (3.4 + ah * 1.0), headY - 14.0);
  ctx.stroke();

  /* 受击红闪：头顶被发冠抬到 -62.4，红块也要跟着长高，否则头发出血时会漏一圈 */
  if (a.flash > 0) {
    ctx.globalAlpha = Math.min(0.32, a.flash * 2.2);
    ctx.fillStyle = '#ff6a4a';
    roundRect(-10, -64, 20, 66, 8);
    ctx.fill();
    ctx.globalAlpha = blink ? 0.5 : 1;
  }

  ctx.restore();

  if (!isBuddy) return;
  drawBuddyPlate(a, sx, a.y - h - 16);
}

/* ---------------- 大肥鱼的尸体：头发铺开、尾巴耷拉、头饰歪掉 ---------------- */
function drawWhaleCorpse(c, ang, sink, fade) {
  ctx.save();
  ctx.globalAlpha = fade;
  ctx.translate(c.x - camera.x, c.y);
  ctx.translate(0, -sink * 0.1);
  ctx.rotate(c.dir * ang);

  /* 位图通道：把站姿立绘绕脚底转 87°，读成「躺平」。
     压扁到 0.88 是因为人躺下后从侧面看身体本来就更薄，
     不压会像一根竖着的木板横过来。 */
  if (whaleSpriteReady()) {
    const spH = WHALE_VH, spW = spH * WHALE_AR;
    ctx.scale(1, 0.88);
    ctx.drawImage(WHALE_SPRITE, -spW * WHALE_FOOT, -spH, spW, spH);
    ctx.restore();
    return;
  }

  const sc = (c.h || 56) / 56;
  ctx.scale(sc, sc);

  const hipY = -25, shY = -40, headY = -50;

  /* 尾巴 */
  ctx.beginPath();
  ctx.moveTo(-4, hipY + 2);
  ctx.quadraticCurveTo(-13, hipY + 5, -18, hipY + 1);
  ctx.lineTo(-17, hipY + 8);
  ctx.quadraticCurveTo(-10, hipY + 9, -4, hipY + 7);
  ctx.closePath();
  wPath(WH.tail, 1.4);
  ctx.beginPath();
  ctx.moveTo(-17, hipY + 1);
  ctx.quadraticCurveTo(-24, hipY - 4, -24, hipY - 10);
  ctx.quadraticCurveTo(-18, hipY - 7, -15, hipY + 1);
  ctx.closePath();
  wPath(WH.tailL, 1.3);

  /* 头发散在地上 */
  ctx.beginPath();
  ctx.moveTo(-6, headY + 4);
  ctx.quadraticCurveTo(-20, headY + 12, -24, headY + 24);
  ctx.quadraticCurveTo(-12, headY + 26, -2, headY + 18);
  ctx.closePath();
  wPath(WH.hairM, 1.5);
  ctx.beginPath();
  ctx.moveTo(-22, headY + 22);
  ctx.quadraticCurveTo(-14, headY + 26, -5, headY + 19);
  ctx.quadraticCurveTo(-12, headY + 20, -18, headY + 18);
  ctx.closePath();
  wPath(WH.hairL, 0);

  /* 腿：一条直一条弯 */
  ctx.strokeStyle = WH.apron;
  ctx.lineWidth = 6.6;
  ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-3, hipY); ctx.lineTo(-8, hipY + 12); ctx.lineTo(-2, -1); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(2, hipY); ctx.lineTo(10, hipY + 10); ctx.lineTo(17, -2); ctx.stroke();
  ctx.fillStyle = WH.boot;
  roundRect(-6, -3.6, 10, 4.6, 2); ctx.fill();
  roundRect(13, -5, 10, 4.6, 2); ctx.fill();

  /* 裙子塌下去 */
  ctx.beginPath();
  ctx.moveTo(-7, hipY - 3);
  ctx.quadraticCurveTo(-11, hipY + 6, -10, hipY + 11);
  ctx.quadraticCurveTo(0, hipY + 14, 10, hipY + 10);
  ctx.quadraticCurveTo(8, hipY + 3, 6, hipY - 3);
  ctx.closePath();
  wPath(WH.dress, 1.5);

  /* 上身 */
  ctx.beginPath();
  roundRect(-5.6, shY, 11.2, 12, 3.5);
  wPath(WH.dress, 1.4);
  ctx.beginPath();
  roundRect(-3.8, shY + 2, 7.6, 9, 2);
  wPath(WH.apron, 1);

  /* 头 + 歪掉的发呆毛 */
  ctx.beginPath();
  ctx.ellipse(0.5, headY, 8.6, 9, 0, 0, Math.PI * 2);
  wPath(WH.skin, 1.5);
  /* 闭眼 */
  ctx.strokeStyle = WH.ink;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-5.4, headY + 0.6); ctx.lineTo(-2.2, headY + 1.8); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(2.4, headY + 1.8); ctx.lineTo(5.6, headY + 0.6); ctx.stroke();
  /* 刘海 */
  ctx.beginPath();
  ctx.moveTo(-8.2, headY - 1.5);
  ctx.quadraticCurveTo(-6.4, headY - 9.4, 0.5, headY - 9.2);
  ctx.quadraticCurveTo(7.4, headY - 9.4, 8.2, headY - 1.5);
  ctx.quadraticCurveTo(3, headY - 6.4, -8.2, headY - 1.5);
  ctx.closePath();
  wPath(WH.hairM, 1.3);
  /* 头饰歪到一边 */
  ctx.strokeStyle = WH.apron;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(0.5, headY - 1, 9, Math.PI * 1.05, Math.PI * 1.62);
  ctx.stroke();

  ctx.restore();
}

/* ============================================================
   小克 —— 象牙白瓷装甲 / 珊瑚橙星芒 / 无脸面甲横条光 / 刀翼
   局部坐标：脚底 0，站立身高按 100 设计，外面用 (baseH/100) 缩放
   ============================================================ */
const XK = {
  ink: '#0e0f12',
  ivory: '#eae7dc', ivoryS: '#b7b4a8', ivoryD: '#7c7a71',
  joint: '#2b2c30', jointL: '#4a4c52',
  coral: '#ff7a52', coralL: '#ffb08c', coralD: '#c8441f',
  glow: 'rgba(255,138,96,'
};

function drawXiaoke(e) {
  if (e.dead) return;
  const sx = e.x - camera.x;
  if (sx < -220 || sx > W + 220) return;

  const s = (e.baseH || 100) / 100;
  const facing = Math.cos(e.aim) >= 0 ? 1 : -1;
  const t = game.time;
  const bob = Math.sin(t * 1.6) * 1.6;
  const charge = clamp((e.slamFx || 0) / 0.9, 0, 1);

  /* 落影（flatShadow：剧情立绘没有世界层可问，阴影直接贴脚） */
  const under = e.flatShadow ? e.y : surfaceBelow(e.x, e.y);
  const gap = e.flatShadow ? 0 : clamp((under - e.y) / 190, 0, 1);
  const sk = 1 - gap * 0.68;
  ctx.fillStyle = 'rgba(0,0,0,' + (0.44 * sk).toFixed(3) + ')';
  ctx.beginPath();
  ctx.ellipse(sx, under + 1, 26 * sk, 6 * sk, 0, 0, Math.PI * 2);
  ctx.fill();

  /* 地面珊瑚色余晖 —— 她站着的地方会微微发亮，压场感全靠这个 */
  const gl = ctx.createRadialGradient(sx, e.y - 4, 2, sx, e.y - 4, 60 * s);
  gl.addColorStop(0, 'rgba(255,120,80,0.16)');
  gl.addColorStop(1, 'rgba(255,120,80,0)');
  ctx.fillStyle = gl;
  ctx.beginPath();
  ctx.ellipse(sx, e.y, 60 * s, 16 * s, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.save();
  ctx.translate(sx, e.y + bob * 0.3);
  ctx.scale(s * facing, s);
  if (e.flash > 0) ctx.globalAlpha = 1;

  /* 趴下：和小兵/鲸鱼/黑甲共用同一套「绕脚底放平 + 整体抬起」。
     她的本地体格是 100（不是人的 56），而且是重装瓷壳 + 四片刀翼，
     横过来比人厚得多，所以抬升系数单独给到 1.6 —— 按人的 1.0 算，
     胸甲前沿和刀翼会切进地面。rotate 写在 scale 之后，镜像会自动带过去。 */
  const pp = pronePose(e, 100, 1.6);
  if (pp.pr > 0.002) {
    ctx.translate(pp.shift, -pp.lift);
    ctx.rotate(pp.ang);
  }

  const hipY = -44, shY = -74, headY = -88;

  /* ---- 刀翼：四片，从肩胛往身后上方扇形张开 ----
     关键约束：锚点必须在背后（局部 -x 侧）且高度在肩胛（不是头顶），
     角度必须全部落在「后方 90° 扇区」里；一旦转成 -90° 附近就会从头顶窜出来，
     读成兔耳 / 犄角，而不是翼。 */
  const wingX = -7, wingY = hipY - 16;
  for (let i = 3; i >= 0; i--) {
    const sp = Math.sin(t * 0.9 + i * 1.3) * 0.045;
    const ang = -Math.PI * 0.84 + i * 0.095 + sp;
    const L = 34 + i * 6;
    ctx.save();
    ctx.translate(wingX, wingY);
    ctx.rotate(ang);
    /* 刃身加厚到 ±3.4：±2.6 在实际游戏缩放下只剩一条几像素的白线，
       读不出「刀」的厚度，反而像几根天线 */
    ctx.beginPath();
    ctx.moveTo(0, -3.4);
    ctx.quadraticCurveTo(L * 0.62, -8.8, L, -1.4);
    ctx.quadraticCurveTo(L * 0.6, 3, 0, 3.4);
    ctx.closePath();
    ctx.fillStyle = i % 2 ? XK.ivoryS : XK.ivory;
    ctx.fill();
    ctx.strokeStyle = XK.ink;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    /* 刃口珊瑚光 */
    ctx.strokeStyle = XK.glow + (0.55 - i * 0.08) + ')';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(4, -1.2);
    ctx.quadraticCurveTo(L * 0.7, -3.4, L - 2, -1);
    ctx.stroke();
    ctx.restore();
  }
  /* 翼根机械关节：没有这个球，四片刀翼会读成「漂浮的叶形色块」 */
  ctx.beginPath();
  ctx.arc(wingX, wingY, 4.4, 0, Math.PI * 2);
  ctx.fillStyle = XK.joint;
  ctx.fill();
  ctx.strokeStyle = XK.ink;
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(wingX, wingY, 1.7, 0, Math.PI * 2);
  ctx.fillStyle = XK.coral;
  ctx.fill();

  /* ---- 星芒光环（头后） ----
     两个要点：
     1) 必须在「头」之前画，当逆光用 —— 画在脸之后会把象牙白瓷面刷成脏粉色；
     2) 尖角必须宽底（半角 ≥0.2）且 8 根起，6 根细针会读成「插了几根天线」。 */
  ctx.save();
  ctx.translate(0, headY - 2);
  /* 逆光底晕 */
  const bg = ctx.createRadialGradient(0, 0, 6, 0, 0, 34);
  bg.addColorStop(0, 'rgba(255,146,104,0.30)');
  bg.addColorStop(0.55, 'rgba(255,120,80,0.13)');
  bg.addColorStop(1, 'rgba(255,110,70,0)');
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.arc(0, 0, 34, 0, Math.PI * 2);
  ctx.fill();
  /* 尖角 */
  ctx.rotate(t * 0.22);
  for (let i = 0; i < 8; i++) {
    const a0 = i * Math.PI / 4;
    const R = i % 2 ? 27 : 35;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a0 - 0.21) * 11.5, Math.sin(a0 - 0.21) * 11.5);
    ctx.lineTo(Math.cos(a0) * R, Math.sin(a0) * R);
    ctx.lineTo(Math.cos(a0 + 0.21) * 11.5, Math.sin(a0 + 0.21) * 11.5);
    ctx.closePath();
    ctx.fillStyle = 'rgba(255,152,112,' + (0.30 + Math.sin(t * 2 + i) * 0.07).toFixed(2) + ')';
    ctx.fill();
  }
  ctx.restore();

  /* ---- 腿：细长机械腿，膝盖露出关节 ---- */
  const moving = Math.abs(e.vx) > 20;
  const ph = e.anim || 0;
  for (let i = 0; i < 2; i++) {
    const front = i === 1;
    const sw = moving ? Math.sin(ph + (front ? 0 : Math.PI)) * 0.46 : (front ? 0.05 : -0.06);
    const kn = moving ? Math.max(0, Math.sin(ph + (front ? 2 : 5))) * 0.5 : 0.1;
    const hx = (front ? 3.4 : -3.4);
    const thigh = 18, shin = 20;
    const kx = hx + Math.sin(sw) * thigh, ky = hipY + Math.cos(sw) * thigh;
    const fa = sw - kn;
    const fx = kx + Math.sin(fa) * shin, fy = ky + Math.cos(fa) * shin;

    ctx.strokeStyle = front ? XK.ivory : XK.ivoryS;
    ctx.lineWidth = 7.5;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(hx, hipY); ctx.lineTo(kx, ky); ctx.stroke();
    ctx.lineWidth = 6;
    ctx.beginPath(); ctx.moveTo(kx, ky); ctx.lineTo(fx, fy); ctx.stroke();

    /* 膝/踝关节 */
    ctx.fillStyle = XK.joint;
    ctx.beginPath(); ctx.arc(kx, ky, 3.4, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = XK.coral;
    ctx.beginPath(); ctx.arc(kx, ky, 1.5, 0, Math.PI * 2); ctx.fill();
    /* 足 */
    ctx.fillStyle = XK.ivoryD;
    ctx.beginPath();
    ctx.moveTo(fx - 3, fy - 3);
    ctx.lineTo(fx + 9, fy - 2.4);
    ctx.lineTo(fx + 8, fy + 2.6);
    ctx.lineTo(fx - 4, fy + 2.4);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = XK.ink;
    ctx.lineWidth = 1.2;
    ctx.stroke();
  }

  /* ---- 骨盆 / 腰 ---- */
  ctx.beginPath();
  ctx.moveTo(-8, hipY - 2);
  ctx.lineTo(8, hipY - 2);
  ctx.lineTo(6.5, hipY + 7);
  ctx.lineTo(-6.5, hipY + 7);
  ctx.closePath();
  ctx.fillStyle = XK.ivoryS;
  ctx.fill();
  ctx.strokeStyle = XK.ink;
  ctx.lineWidth = 1.4;
  ctx.stroke();

  /* ---- 躯干：光滑瓷壳，上宽下窄 ---- */
  ctx.beginPath();
  ctx.moveTo(-7, hipY - 4);
  ctx.quadraticCurveTo(-13, hipY - 20, -11.5, shY + 6);
  ctx.quadraticCurveTo(-9, shY - 4, 0, shY - 5);
  ctx.quadraticCurveTo(9, shY - 4, 11.5, shY + 6);
  ctx.quadraticCurveTo(13, hipY - 20, 7, hipY - 4);
  ctx.closePath();
  ctx.fillStyle = XK.ivory;
  ctx.fill();
  ctx.strokeStyle = XK.ink;
  ctx.lineWidth = 1.7;
  ctx.stroke();

  /* 胸口接缝 */
  ctx.strokeStyle = XK.ivoryD;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(0, shY + 2);
  ctx.lineTo(0, hipY - 6);
  ctx.stroke();

  /* 胸口星徽 */
  ctx.save();
  ctx.translate(0, shY + 14);
  for (let i = 0; i < 4; i++) {
    const a0 = i * Math.PI / 2;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(a0) * 5, Math.sin(a0) * 5);
    ctx.lineTo(Math.cos(a0 + Math.PI / 4) * 1.6, Math.sin(a0 + Math.PI / 4) * 1.6);
    ctx.closePath();
    ctx.fillStyle = XK.coral;
    ctx.fill();
  }
  ctx.restore();

  /* 胸腹散热缝：三道光 */
  for (let i = 0; i < 3; i++) {
    ctx.fillStyle = 'rgba(255,140,100,' + (0.42 - i * 0.09).toFixed(2) + ')';
    roundRect(-5.5 + i * 1.6, hipY - 8 + i * 6, 11 - i * 3.2, 1.4, 0.7);
    ctx.fill();
  }

  /* ---- 肩甲 ---- */
  for (let i = 0; i < 2; i++) {
    const sxx = i === 0 ? -9.5 : 9.5;
    ctx.beginPath();
    ctx.ellipse(sxx, shY + 4, 5.4, 6, sxx < 0 ? 0.3 : -0.3, 0, Math.PI * 2);
    ctx.fillStyle = i === 0 ? XK.ivoryS : XK.ivory;
    ctx.fill();
    ctx.strokeStyle = XK.ink;
    ctx.lineWidth = 1.4;
    ctx.stroke();
  }

  /* ---- 手臂 + 长枪 ----
     枪不跟着身体一起倒：把身体那一个 ang 扣掉，枪在趴下时仍然是架平朝 target 的 */
  ctx.save();
  ctx.translate(0, shY + 5);
  ctx.rotate(e.aim - pp.ang);
  const kick = Math.min(1, (e.muzzle || 0) * 10);
  ctx.translate(-kick * 1.8, 0);

  /* 后手 */
  ctx.strokeStyle = XK.ivoryS;
  ctx.lineWidth = 5;
  ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-2, 2); ctx.lineTo(13, 5.5); ctx.stroke();

  /* 枪体：细长瓷白长枪，珊瑚色能量槽 */
  ctx.fillStyle = XK.ivoryD;
  roundRect(-12, -0.5, 14, 6, 2.4);
  ctx.fill();
  ctx.strokeStyle = XK.ink; ctx.lineWidth = 1.1;
  ctx.stroke();
  ctx.fillStyle = XK.joint;
  roundRect(2, -4.5, 26, 7.5, 2.6);
  ctx.fill();
  ctx.fillStyle = XK.ivory;
  roundRect(4, -3, 22, 3.2, 1.4);
  ctx.fill();
  /* 能量槽 */
  ctx.fillStyle = XK.glow + (0.55 + charge * 0.4) + ')';
  roundRect(6, 0.2, 18, 2, 1);
  ctx.fill();
  /* 枪管 */
  ctx.fillStyle = XK.ivoryS;
  roundRect(27, -2.2, 26, 4.4, 1.8);
  ctx.fill();
  ctx.strokeStyle = XK.ink; ctx.lineWidth = 1.1;
  ctx.stroke();
  ctx.fillStyle = XK.coral;
  ctx.fillRect(50, -2.8, 4.5, 5.6);

  /* 前手 */
  ctx.strokeStyle = XK.ivory;
  ctx.lineWidth = 5.4;
  ctx.beginPath(); ctx.moveTo(1, -2); ctx.lineTo(30, 3.2); ctx.stroke();
  ctx.fillStyle = XK.ivoryS;
  ctx.beginPath(); ctx.arc(31, 3.6, 2.8, 0, Math.PI * 2); ctx.fill();

  /* 枪口闪光 */
  if ((e.muzzle || 0) > 0 || charge > 0.2) {
    const R = 20 + charge * 26;
    const mg = ctx.createRadialGradient(56, 0, 1, 56, 0, R);
    mg.addColorStop(0, 'rgba(255,240,226,0.95)');
    mg.addColorStop(0.4, 'rgba(255,140,96,0.5)');
    mg.addColorStop(1, 'rgba(255,90,50,0)');
    ctx.fillStyle = mg;
    ctx.beginPath(); ctx.arc(56, 0, R, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();

  /* ---- 颈 ---- */
  ctx.strokeStyle = XK.joint;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(0, shY - 2);
  ctx.lineTo(0, shY - 8);
  ctx.stroke();

  /* ---- 头：无脸面甲 + 横条光 ---- */
  ctx.beginPath();
  ctx.ellipse(0, headY, 11, 11.6, 0, 0, Math.PI * 2);
  ctx.fillStyle = XK.ivory;
  ctx.fill();
  ctx.strokeStyle = XK.ink;
  ctx.lineWidth = 1.8;
  ctx.stroke();

  /* 面甲暗槽 */
  ctx.beginPath();
  ctx.ellipse(-1, headY + 1, 9.4, 9, 0, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(30,28,26,0.16)';
  ctx.fill();

  /* 横条光：呼吸式明暗，蓄力时整条拉满。位置略高于头心，
     贴到正中会被读成「嘴」而不是「单眼观察窗」 */
  const eyeY = headY - 2.6;
  const barW = 12.5 + charge * 4;
  const barA = 0.72 + Math.sin(t * 2.4) * 0.16 + charge * 0.2;
  ctx.fillStyle = XK.glow + Math.min(1, barA).toFixed(2) + ')';
  roundRect(-barW / 2, eyeY - 1.5, barW, 3, 1.5);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,236,224,0.85)';
  roundRect(-barW / 2 + 1, eyeY - 0.8, barW - 2, 1.2, 0.6);
  ctx.fill();
  /* 近光晕：只罩住条形光本身，半径必须小于头半径，
     否则整张瓷脸会被染成粉褐色、失掉「白瓷」这个第一识别特征 */
  const hg = ctx.createRadialGradient(0, eyeY, 1.5, 0, eyeY, 8.5);
  hg.addColorStop(0, XK.glow + '0.30)');
  hg.addColorStop(1, 'rgba(255,120,70,0)');
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.arc(0, eyeY, 8.5, 0, Math.PI * 2); ctx.fill();

  /* 头顶瓷冠：三尖，压低贴颅。两尖 + 中央凹会读成「中分刘海」，
     太高则读成兔耳 —— 三尖是唯一不会被误读成别的器官的形状。 */
  ctx.beginPath();
  ctx.moveTo(-9, headY - 6.2);
  ctx.lineTo(-6.2, headY - 10.6);
  ctx.lineTo(-3.1, headY - 7.4);
  ctx.lineTo(0, headY - 11.2);
  ctx.lineTo(3.1, headY - 7.4);
  ctx.lineTo(6.2, headY - 10.6);
  ctx.lineTo(9, headY - 6.2);
  ctx.closePath();
  ctx.fillStyle = XK.ivoryS;
  ctx.fill();
  ctx.strokeStyle = XK.ink;
  ctx.lineWidth = 0.9;   /* 1.2 的描边会把三尖冠吃成黑色锯齿 */
  ctx.stroke();

  /* 受击闪白 */
  if (e.flash > 0) {
    ctx.globalAlpha = Math.min(0.5, e.flash * 3);
    ctx.fillStyle = '#ffffff';
    roundRect(-14, -102, 28, 102, 10);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  ctx.restore();
}

/* ---------------- 大肥鱼倒地（等待救援）：复用尸体造型，套同一套软倒曲线 ---------------- */
/* 人形单位的倒地参数：扑倒是 0.24 秒、歪倒是 0.60 秒 —— 和扑倒/起身
   同一族时间尺度（0.24 / 0.36），这样「倒下」和「趴下」在观感上是
   同一个人的同一个重量，不会有「趴下很重、被打死很轻」的割裂。 */
const ACT_DOWNED_SOFT = { t1: 0.24, t2: 0.60, soft: 0.30, fold: 1.21, sink1: 8, sink2: 2, sinkEnd: 10 };

function actDownedCurve(a, opt) {
  const td = Math.max(0, game.time - (a.downedAt === undefined ? game.time : a.downedAt));
  return actDeathCurve(td, opt || ACT_DOWNED_SOFT);
}

function drawWhaleDowned(a) {
  const x = a.x - camera.x, y = a.y;

  /* 血泊 */
  ctx.fillStyle = 'rgba(110,24,24,0.42)';
  ctx.beginPath(); ctx.ellipse(x + 6, y + 1, 42, 9, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath(); ctx.ellipse(x, y + 2, 30, 6, 0, 0, Math.PI * 2); ctx.fill();

  /* 倒地曲线现在只有一条（util.js 的 actDeathCurve）：膝盖先软 →
     上身歪出去 → 落地余震。三个人原本各抄一份、数字其实一模一样，
     抄错一个符号就是「倒向另一边」。参数集中在这里，是因为这三个
     人的重量和身高是同一档；大肥鱼另有自己的一份（在下面）。 */
  const dc = actDownedCurve(a);
  const ang = -dc.ang, sink = dc.sink;

  drawWhaleCorpse({ x: a.x, y: a.y, h: a.h, dir: 1 }, -ang, sink, 1);

  /* 呼救波纹 */
  const pulse = 0.5 + 0.5 * Math.sin(game.time * 4);
  ctx.strokeStyle = 'rgba(255,110,110,' + (0.16 + pulse * 0.22) + ')';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(x, y - 18, 30 + pulse * 12, 0, Math.PI * 2);
  ctx.stroke();
}

/* ============================================================
   主角：黑甲战士（位图通道，2026-10-28 接入）
   ------------------------------------------------------------
   和大肥鱼同一条路子：发明细立绘 → 抠白底 → 归一化到 192px 高
   （游戏内 96px 的 2 倍超采样）→ base64 内联，代码只做搬运和变形。

   为什么不能用路径画：1280×720、1.22 倍视角下人只有 56~96px，
   头盔上的一道分模线不到 0.5px，参数调到头也画不出设定稿的金属感。

   两张底图：
     · hold —— 双手抱在胸前的持握姿势，手臂已经画进图里。
       枪由代码挂在手上，于是枪跟着准星转、手不动，读起来是「手在稳枪」。
     · idle —— 垂手站姿，兜底（握枪图解码失败、或以后过场用）。

   物理碰撞盒 h=58 一个数字都不动，视觉用 HERO_VH=96 —— 和 大肥鱼 同尺，
   两人并排是一个世界里的角色；敌兵仍按 h 画，天然比主角矮一截。
   ============================================================ */

const HERO_SPRITE_IDLE_B64 = 'data:image/png;base64,';
const HERO_SPRITE_HOLD_B64 = 'data:image/png;base64,';

const HERO_SPRITE = (typeof Image !== 'undefined') ? new Image() : null;
if (HERO_SPRITE) HERO_SPRITE.src = HERO_SPRITE_IDLE_B64;
const HERO_SPRITE_HOLD = (typeof Image !== 'undefined') ? new Image() : null;
if (HERO_SPRITE_HOLD) HERO_SPRITE_HOLD.src = HERO_SPRITE_HOLD_B64;

function heroSpriteReady() {
  return !!HERO_SPRITE && HERO_SPRITE.complete && HERO_SPRITE.naturalWidth > 0;
}
function heroHoldReady() {
  return !!HERO_SPRITE_HOLD && HERO_SPRITE_HOLD.complete && HERO_SPRITE_HOLD.naturalWidth > 0;
}

const HERO_VH = 96;              /* 屏幕上的视觉身高 */
const HERO_ART_W_HOLD = 87;      /* 素材归一化后的宽度（hold，192 高） */
const HERO_ART_W_IDLE = 78;      /* 同上（idle） */
const HERO_AR_HOLD = HERO_ART_W_HOLD / 192;
const HERO_AR_IDLE = HERO_ART_W_IDLE / 192;

/* 脚底锚点：按「两只鞋的中点」量，不是按图的几何中心 ——
   图左边还挂着背包，用图心当锚点人会整体前移。 */
const HERO_FOOT_HOLD = 0.414;
const HERO_FOOT_IDLE = 0.551;

/* 蹲下两段压缩：头段几乎不压（盔是圆的，压了就扁），身段压得狠。
   切点在下巴/衣领之间（y≈34%），压缩时接缝落在真实的结构线上。 */
const HERO_NECK = 0.34;
const HERO_HEAD_K = 1.00;    /* 头段不压 —— 和 whale 同一条规矩，见那边 98 行 */
const HERO_BODY_K = 0.62;    /* 身段压到 62%（头不压之后压缩全在这一段） */
const HERO_PRONE_THIN = 0.34;
const HERO_CROUCH_LEAN = 0.20;
const HERO_CROUCH_WIDE = 0.16;
const HERO_CROUCH_ROT = -0.10;  /* 蹲下时腿绕髋往前折 */

/* 趴下抬升系数。1 就等于「半个身厚的标准量」，主角这套立绘放倒之后
   身子比标准厚度更「沉」：按标准抬，胸背会压进地面 8px（实测见
   test/_action.js ⑥）。多抬 62% 让背线正好落在地面线上 ——
   这个数是量出来的，不是调出来的，别手改。 */
const HERO_LIFT_K = 1.62;

function heroBands(cq) {
  const headH = HERO_VH * HERO_NECK * (1 - cq * (1 - HERO_HEAD_K));
  const bodyH = HERO_VH * (1 - HERO_NECK) * (1 - cq * (1 - HERO_BODY_K));
  return { headH, bodyH, total: headH + bodyH };
}
function heroRowY(rowFrac, cq) {
  if (cq <= 0.01) return -HERO_VH + rowFrac * HERO_VH;
  const { headH, bodyH, total } = heroBands(cq);
  if (rowFrac < HERO_NECK) return -total + (rowFrac / HERO_NECK) * headH;
  return -bodyH + ((rowFrac - HERO_NECK) / (1 - HERO_NECK)) * bodyH;
}

/* 前手（扣扳机那只）的掌心，量自 art/hero_hold.png：art 像素 (70, 92)。
   枪的挂点就是这里 —— 数字是量出来的，不是猜的。 */
const HERO_HAND_ROW_HOLD = 92 / 192;
const HERO_HAND_XFRAC_HOLD = 70 / HERO_ART_W_HOLD;
/* 枪的尺寸系数。按身高 96/58≈1.65 等比放大会让他端着一门炮：
   这张立绘头占了三分之一，等比缩放后枪比小臂还粗。0.92 是「顺手的一把步枪」。 */
const HERO_GUN_K = 0.92;

/* 拆腿：把立绘拆成「躯干 + 前腿 + 后腿」三片，腿要动就必须单独摆。
   腿片的上缘故意伸进胯部（y=112，比切口 128 高 16），画的时候先腿后躯干，
   伸进胯里的那 16px 被躯干盖住 —— 腿不管摆多大，切口永远藏在里面。
   矩形全部写在 87×192 的立绘坐标里，按 naturalWidth/87 自动缩放。 */
const HERO_LEG = {
  front: { sx: 37, sy: 112, sw: 50, sh: 80, cutX0: 37, cutX1: 87, cutY: 128, pivotX: 50, pivotY: 126 },
  back:  { sx: 0,  sy: 112, sw: 37, sh: 80, cutX0: 0,  cutX1: 37, cutY: 128, pivotX: 27, pivotY: 126, dim: 0.10 }
};
const _heroSplit = new Map();
function heroLegParts(img) { return legPartsOf(img, HERO_LEG, HERO_ART_W_HOLD, _heroSplit); }

/* 摆幅要按「看得见的量」定，不是按角度手感定：髋到脚 66 立绘像素 = 33 屏幕像素，
   0.16rad 让脚前后挪 10 立绘像素 = 5 屏幕像素，两只靴子来回差一个靴宽 ——
   刚够读出「在迈步」，再大就开始像踢正步（这张是开腿站姿，腿本来就分得开）。 */
const HERO_GAIT_K = {
  stepRot: 0.16, stepLift: 10,
  idleRot: 0.038, idleLift: 2.6,
  airFront: 0.15, airBack: -0.12, airLiftF: 8.0, airLiftB: 9.0
};

/* 受击红闪的剪影，和 whaleSilhouette 的区别是「留辉光」：
   大肥鱼是白蓝底，半透纯红叠上去只算偏红，底色还认得出来；
   这套是黑甲（#1a2029），同样的红直接把它吃成一个人形红块，而 cyber 头盔上
   唯一的高识别度特征就是那条目镜缝 —— 丢了激战里一秒认不出自己。
   所以按像素重建剪影时，把青色像素（目镜 + 胸口状态灯）原样留下；
   红影一叠，那条缝反而更亮，一眼还是自己的指挥官。
   接收 img 或任何 canvas（拆件后的躯干片是 canvas），按对象缓存。 */
const _glowSil = new Map();
function glowSilhouette(src) {
  if (!src || typeof document === 'undefined') return null;
  const w = src.naturalWidth || src.width, h = src.naturalHeight || src.height;
  if (!w || !h) return null;
  let hit = _glowSil.get(src);
  if (hit !== undefined) return hit;

  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d');
  g.drawImage(src, 0, 0);

  let d;
  try { d = g.getImageData(0, 0, w, h); }
  catch (e) { hit = whaleSilhouette(src); _glowSil.set(src, hit); return hit; }
  /* 注：立绘是 base64 内联的，不会污染画布；只有换成外部图片才走上面这条退路 */

  const s = d.data;
  const out = g.createImageData(w, h);
  const o = out.data;
  for (let i = 0; i < o.length; i += 4) {
    const al = s[i + 3];
    if (al < 8) continue;                            /* 透明像素留空 */
    const r = s[i], gg = s[i + 1], b = s[i + 2];
    if (gg > 150 && b - r > 110) {                   /* 目镜 / 胸口指示灯：原样保留 */
      o[i] = r; o[i + 1] = gg; o[i + 2] = b; o[i + 3] = al;
      continue;
    }
    o[i] = 255; o[i + 1] = 90; o[i + 2] = 60; o[i + 3] = al;
  }
  g.putImageData(out, 0, 0);
  hit = c;
  _glowSil.set(src, hit);
  return hit;
}

function heroTint(img) { return glowSilhouette(img); }

/* 拆件状态下躯干单独一片，红闪时也得留辉光 —— 否则站立（splitOn）时
   走的是躯干片，那条目镜缝照样会被纯红盖掉 */
function heroBodySil(parts) {
  return parts ? glowSilhouette(parts.body) : null;
}

/* 枪：和大肥鱼共用同一把（whaleGunBody 是按「局部 +x 朝前」画的通用步枪），
   只换挂点和缩放。part='back' 先画枪托弹匣（被手挡住），'front' 再画机匣枪管。 */
function heroGunProp(a, cq, lean, part) {
  ctx.save();
  const pitch = whalePitch(a);
  /* 挂点从 gunAnchor 拿 —— 和 muzzlePoint 读同一份。
     蹲/趴换成姿态图之后掌心位置由那张图决定，这里自己再算一遍必然对不上。 */
  const an = gunAnchor(a);
  ctx.translate(an.hx, an.hy);
  /* 外层已经 scale(facing,1) 镜像过，这里的 +x 就是面朝方向；
     外层还整体倾了 lean，这里要扣掉，否则枪会比准星多转那 3° */
  ctx.rotate(pitch - (lean || 0));
  ctx.scale(HERO_GUN_K, HERO_GUN_K);
  ctx.translate(-9, -5);                                          /* 握把咬住掌心 */
  ctx.translate(-kickOf(a), 0);                                   /* 后坐 */
  const dip = gunDip(a);
  if (dip.rot) ctx.rotate(dip.rot);                               /* 换弹：枪口垂下 */
  if (dip.dy) ctx.translate(0, dip.dy);
  whaleGunBody(a, part);
  ctx.restore();
}

/* 兜底剪影：位图还没解码完（首帧）或跑无头测试（没有 Image）时用。
   几块炭黑 + 一条目镜光 + 一把枪，够顶一两帧，不至于让玩家闪一下空白。 */
function heroBlocky(a, cq, lean) {
  const bands = heroBands(cq);
  const headH = bands.headH, bodyH = bands.bodyH, total = bands.total;
  heroGunProp(a, cq, lean, 'back');
  ctx.fillStyle = '#161b21';
  roundRect(-8, -bodyH, 16, bodyH, 4);
  ctx.fill();
  ctx.fillStyle = '#20272f';
  roundRect(-8.5, -total, 17, headH, 7);
  ctx.fill();
  ctx.fillStyle = '#78e2ff';
  roundRect(1.5, -total + headH * 0.44, 6.5, 2.2, 1.1);
  ctx.fill();
  heroGunProp(a, cq, lean, 'front');
}

function drawHero(a, isBuddy) {
  if (a.dead) return;
  if (a.downed) { drawDowned(a); return; }

  const sx = a.x - camera.x;
  const facing = Math.cos(a.aim) >= 0 ? 1 : -1;
  const sq = clamp(a.landSquash || 0, 0, 1);
  const t = game.time;

  /* 承托面阴影（flatShadow：菜单立绘贴脚，不查世界层） */
  const under = a.flatShadow ? a.y : surfaceBelow(a.x, a.y);
  const gap = a.flatShadow ? 0 : clamp((under - a.y) / 190, 0, 1);
  const sk = 1 - gap * 0.68;
  ctx.fillStyle = 'rgba(0,0,0,' + (0.42 * sk).toFixed(3) + ')';
  ctx.beginPath();
  ctx.ellipse(sx + facing * 2, under + 1, (17 + 26 * proneK(a)) * sk, 4.8 * sk, 0, 0, Math.PI * 2);
  ctx.fill();

  /* 冲刺残影：暗块 + 一点冷调，比纯色块更像残影 */
  if ((a.dashTime || 0) > 0) {
    const dir = Math.sign(a.vx) || facing;
    for (let i = 3; i >= 1; i--) {
      ctx.globalAlpha = 0.10 * i;
      ctx.fillStyle = '#1a2733';
      roundRect(sx - dir * i * 10 - 8, a.y - 96 * 0.86, 17, 96 * 0.78, 8);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* 二段跳空翻：与士兵/大肥鱼共用 AIRJUMP_FLIP 时钟 */
  let flipK = 0, flipAng = 0;
  if ((a.airJumpT || 0) > 0) {
    flipK = clamp(1 - a.airJumpT / AIRJUMP_FLIP, 0, 1);
    const e = flipK * flipK * (3 - 2 * flipK);
    flipAng = (a.flipDir || facing) * Math.PI * 2 * e;
  }
  const pivot = HERO_VH * 0.56;
  if (flipK > 0 && flipK < 0.82) {
    const al = 0.34 * (1 - flipK / 0.82);
    ctx.strokeStyle = 'rgba(120,226,255,' + al.toFixed(3) + ')';
    ctx.lineWidth = 2.2;
    ctx.lineCap = 'round';
    for (let i = 0; i < 2; i++) {
      const a0 = flipAng - 1.7 - i * 0.5;
      ctx.beginPath();
      ctx.arc(sx, a.y - pivot, HERO_VH * 0.42 - i * 5, a0, a0 + 1.15);
      ctx.stroke();
    }
  }

  const blink = a.invuln > 0 && Math.floor(a.invuln * 18) % 2 === 0;

  ctx.save();
  ctx.translate(sx, a.y);
  ctx.scale(1 + sq * 0.11, 1 - sq * 0.15);
  if (flipAng) {
    ctx.translate(0, -pivot);
    ctx.rotate(flipAng);
    ctx.translate(0, pivot);
  }
  if (blink) ctx.globalAlpha = 0.5;

  /* 蹲 / 趴互斥：趴下时蹲姿由 cqEff 压成 0，这里只保留一个有效值 */
  const cq = cqEff(a);
  /* 蹲到底 / 趴到底有专门画的图 —— 有图就不再放倒、不再压薄、不再拆头，
     因为那张图本身就是对的姿态。pp 换成 POSE_FLAT 之后，下面每一处
     bodyXform / blitHead / 压薄都自动变成空操作，不用逐处加 if。 */
  const pa = poseArtOf('hero', cq, proneK(a));
  const pp = pa ? POSE_FLAT : pronePose(a, HERO_VH, HERO_LIFT_K);
  const lying = pp.pr > 0.002;

  /* ---------- 位图通道 ---------- */
  const holdUse = heroHoldReady();
  const img0 = holdUse ? HERO_SPRITE_HOLD : HERO_SPRITE;
  const spH = HERO_VH, spW = spH * (holdUse ? HERO_AR_HOLD : HERO_AR_IDLE);
  const dx = -spW * (holdUse ? HERO_FOOT_HOLD : HERO_FOOT_IDLE);

  ctx.scale(facing, 1);

  /* 倾身 + 起步倾角：绕脚底转一点点，头、肩、枪、腿一起走（motionOf） */
  const mo = motionOf(a);
  const lean = whaleLean(a) + mo.lean;
  if (lean) ctx.rotate(lean);
  if (mo.bob) ctx.translate(0, -mo.bob);

  /* 趴下：身段绕脚底放倒，头绕颈部切口抬回去（同一套见 util.js 的 proneHead）。
     放倒之后枪要扣掉同样的角度 —— 躺着架枪是平着架的，不是跟着身体戳向天。 */
  const gunLean = lean + (lying ? pp.ang : 0);
  /* 脖子切口：直立本地坐标里的横线。cutY 是它的 y（向上为负），
     cutH 是切口以上那一段（= 头）的高度。 */
  const cutY = -spH * (1 - HERO_NECK);
  const cutH = spH * HERO_NECK;
  /* 放倒变换：身段、腿、枪全都套这一层；头不套（它要反着抬回来） */
  const bodyXform = () => {
    if (!lying) return;
    ctx.translate(pp.shift, -pp.lift);
    ctx.rotate(pp.ang);
  };

  /* 位图没就绪就别往下算了 —— 下面全是 drawImage / naturalWidth。
     注意这条兜底要排在姿态图之前判断：姿态图也是位图，同样要能解码。 */
  if (!img0 || !img0.naturalWidth) {
    /* 矢量兜底人偶没有脖子分身段的概念，只能整副骨架放倒（头仍然朝下，
       但这张图本来就只在立绘解码失败那几帧出现，不为它单独做拆件）。 */
    ctx.save(); bodyXform();
    heroBlocky(a, cq, gunLean);
    ctx.restore();
    ctx.restore();
    if (isBuddy) drawBuddyPlate(a, sx, lying ? a.y - PRONE_PLATE : a.y + heroRowY(0, cq) - 8);
    return;
  }

  /* 姿态图：不转、不压、不拆件。唯一的加工是 poseWarped 的切片形变
     —— 让腿在蹲行 / 匍匐时真的动起来，否则整张图平移，像贴纸在滑。
     枪仍然分成 back / front 两趟画（枪托在身体后、机匣在身体前），
     否则整把枪要么被身体吞掉，要么浮在人身上。 */
  if (pa) {
    const gm = poseGeom(pa.art, HERO_VH);
    const warp = poseWarpOf(a);
    heroGunProp(a, cq, gunLean, 'back');
    poseWarped(pa.im, gm, warp);
    heroGunProp(a, cq, gunLean, 'front');
    if (a.flash > 0) {
      /* 受击红闪：姿态图也要红。和上面那条走同一个 tint 缓存，
         用 drawImage 叠剪影而不是 fillRect（会把关卡一起染红）。
         warp 也共用一份 —— 不然红闪和主体错开一两像素，看着像重影。 */
      ctx.globalAlpha = Math.min(0.44, a.flash * 2.2);
      poseWarped(heroTint(pa.im), gm, warp);
      ctx.globalAlpha = 1;
    }
    ctx.restore();
    if (isBuddy) drawBuddyPlate(a, sx, a.y + heroRowY(0, cq) - 8);
    return;
  }

  const natW = img0.naturalWidth, natH = img0.naturalHeight;
  const u = spH / natH;                    /* 立绘像素 → 屏幕像素（等比） */

  /* 身段 / 整图。趴下时只画脖子以下，头交给 blitHead 单独摆。 */
  const blit = (img) => {
    if (!img) return;
    const nk = HERO_NECK * natH;
    if (lying) {
      /* 躺倒后压厚度：见 drawWhaleGirl 同一行（正面像两腿张开，压住就不蹬腿） */
      ctx.save();
      ctx.scale(1, 1 - HERO_PRONE_THIN * pp.pr);
      ctx.drawImage(img, 0, nk, natW, natH - nk, dx, cutY, spW, -cutY + 0.5);
      ctx.restore();
      return;
    }
    if (cq <= 0.01) { ctx.drawImage(img, dx, -spH, spW, spH); return; }
    const { headH, bodyH, total } = heroBands(cq);
    /* 折 + 撑，和 whale 同一套（那边 98 行有完整理由）：
       shear 绕脚底把上身往前折，髋部横向撑开，头段一点不缩放 */
    ctx.save();
    ctx.transform(1, 0, -cq * HERO_CROUCH_LEAN, 1, 0, 0);
    ctx.scale(1 + cq * HERO_CROUCH_WIDE * 0.55, 1);
    /* 身段先画（贴地）：+0.5 是补缝，避免两条 drawImage 之间露 1px 背景 */
    ctx.save();
    ctx.scale(1 + cq * HERO_CROUCH_WIDE * 0.45, 1);
    ctx.drawImage(img, 0, nk, natW, natH - nk, dx, -bodyH, spW, bodyH + 0.5);
    ctx.restore();
    /* 头段压在身段上（不缩放）：盔还是圆的 */
    ctx.drawImage(img, 0, 0, natW, nk, dx, -total, spW, headH + 0.5);
    ctx.restore();
  };

  /* 头段：只跟 PRONE_HEAD.k 倍放倒角，剩下的绕切口反着抬回去。
     绕中心转会留一道楔形缝（后脑那侧抬升 (spW/2)·sinθ），
     所以沉降量按转角算，让后半边始终埋在身段里。 */
  const blitHead = (img) => {
    if (!img || !lying) return;
    const ncX = dx + spW * 0.5;
    const nh = proneHead(pp, ncX, cutY);
    if (!nh) return;
    const nk = HERO_NECK * natH;
    const sink = PRONE_HEAD.pull + (spW * 0.5) * Math.abs(Math.sin(nh.ang));
    ctx.save();
    ctx.translate(nh.x, nh.y);
    ctx.rotate(nh.ang);
    ctx.translate(-spW * 0.05, sink);
    ctx.drawImage(img, 0, 0, natW, nk, dx - ncX, -cutH, spW, cutH + 0.5);
    ctx.restore();
  };

  const parts = holdUse ? heroLegParts(img0) : null;
  /* 趴下时不拆件 —— 躺倒的人腿是伸直的，跟着身体一起转就行，
     不需要两条腿各自摆步态。判据见 drawWhaleGirl 里同一行的长注释。 */
  const splitOn = !!parts && cq <= 0.02 && pp.pr < 0.002;

  const blitLeg = (key, useSil, gait) => {
    const R = HERO_LEG[key];
    const g = gait[key];
    const cv = useSil ? whalePartSil(parts, key) : parts.legs[key];
    if (!cv) return;
    const ox = dx + R.sx * u;
    const oy = -spH + R.sy * u - g.lift * u;
    /* 旋转中心 = 髋点，换算成「相对腿片左上角」的偏移；
       translate 已经把腿片左上角挪到原点，所以 drawImage 必须画在 (0,0) */
    const px = (R.pivotX - R.sx) * u, py = (R.pivotY - R.sy) * u;
    ctx.save();
    ctx.translate(ox + px, oy + py);
    ctx.rotate(g.rot + cq * HERO_CROUCH_ROT);
    ctx.translate(-px, -py);
    ctx.drawImage(cv, 0, 0, cv.width, cv.height, 0, 0, R.sw * u, R.sh * u);
    ctx.restore();
  };

  const blitLegs = (useSil) => {
    const gait = gaitFor(a, t, cq, HERO_GAIT_K);
    blitLeg('back', useSil, gait);
    blitLeg('front', useSil, gait);
  };

  if (splitOn) {
    ctx.save(); bodyXform();
    /* 枪托 + 弹匣：先铺在立绘底下（等下的人会盖住它） */
    heroGunProp(a, cq, gunLean, 'back');
    blitLegs(false);
    blit(parts.body);
    ctx.restore();
    blitHead(parts.body);
    /* 'front'（机匣 + 枪管）排在头之后：趴下时枪口在脸颊高度，
       画在头下面会被头盔整个吞掉。留在 bodyXform 里让 ±pp.ang 抵平。 */
    ctx.save(); bodyXform();
    heroGunProp(a, cq, gunLean, 'front');
    ctx.restore();
  } else {
    ctx.save(); bodyXform();
    heroGunProp(a, cq, gunLean, 'back');
    blit(img0);
    ctx.restore();
    blitHead(img0);
    ctx.save(); bodyXform();
    heroGunProp(a, cq, gunLean, 'front');
    ctx.restore();
  }

  /* 受击红闪：用 sprite 的 alpha 当遮罩的红剪影，叠上去（目镜那条青线在上面
     glowSilhouette 里被留下了，所以红影里还能看见一眼冷光）。
     拆件时两块腿也要各自红一遍，否则红影子会顶着一双不动的腿。
     黑甲比白底吃色，上限比大肥鱼的 0.5 压到 0.44，免得整个人糊成一团红。 */
  if (a.flash > 0) {
    ctx.globalAlpha = Math.min(0.44, a.flash * 2.2);
    ctx.save(); bodyXform();
    if (splitOn) {
      blitLegs(true);
      /* 躯干只红到腿片顶边为止：腿片 sy=112 起画、躯干 cutY=128 才挖，
         中间那 16 行两边都有，各叠一次 0.44 就变成 0.69 —— 平时看不出来，
         红闪时腰上会亮出一条橙带。clip 掉上边，下面全交给腿片（单层）。
         腿绕髋转 ±0.16rad，顶边最多让开 2 行立绘像素 ≈ 1 屏幕像素，看不着。 */
      const cutTop = Math.min(HERO_LEG.front.sy, HERO_LEG.back.sy) / 192;
      ctx.save();
      ctx.beginPath();
      ctx.rect(-220, -spH, 440, spH * cutTop);
      ctx.clip();
      blit(heroBodySil(parts));
      ctx.restore();
    } else {
      blit(heroTint(img0));
    }
    ctx.restore();
    blitHead(splitOn ? heroBodySil(parts) : heroTint(img0));
    ctx.globalAlpha = 1;
  }

  ctx.restore();

  if (isBuddy) drawBuddyPlate(a, sx, lying ? a.y - PRONE_PLATE : a.y + heroRowY(0, cq) - 8);
}

/* 倒地待救：动作曲线和士兵/大肥鱼完全一样（膝盖先折 → 上身歪出去 → 落地余震），
   只是把「脸」换成头盔、把皮肤色换成炭黑 —— 主角全程不露脸，倒地也不能露。
   枪先扔在地上：人躺平了还端着枪，会读成「他在瞄准」。 */
function drawHeroDowned(a) {
  const x = a.x - camera.x, y = a.y;
  const dir = Math.cos(a.aim || 0) >= 0 ? 1 : -1;

  /* 血泊 */
  ctx.fillStyle = 'rgba(110,24,24,0.40)';
  ctx.beginPath(); ctx.ellipse(x + 6 * dir, y + 1, 40, 9, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.32)';
  ctx.beginPath(); ctx.ellipse(x, y + 2, 30, 6, 0, 0, Math.PI * 2); ctx.fill();

  /* 倒地曲线现在只有一条（util.js 的 actDeathCurve）：膝盖先软 →
     上身歪出去 → 落地余震。三个人原本各抄一份、数字其实一模一样，
     抄错一个符号就是「倒向另一边」。参数集中在这里，是因为这三个
     人的重量和身高是同一档；大肥鱼另有自己的一份（在下面）。 */
  const dc = actDownedCurve(a);
  const ang = -dc.ang, sink = dc.sink;

  /* 掉在地上的枪：先画，压在人下面 */
  ctx.save();
  ctx.translate(x + 30 * dir, y - 2);
  ctx.scale(dir, 1);
  ctx.rotate(0.10);
  ctx.fillStyle = '#2c343c';
  roundRect(-16, -3, 34, 5, 2); ctx.fill();
  ctx.fillStyle = '#454f59';
  roundRect(-2, -6, 12, 5, 1.5); ctx.fill();
  ctx.fillStyle = '#1b2127';
  roundRect(6, -2, 6, 7, 1.5); ctx.fill();
  ctx.restore();

  /* 身姿按「躺平」画，再用角度补间：ang 从 0（直立）走到 -1.51（躺平）。
     士兵那版是「竖直着画再整体转」，转到 86° 腿就朝天竖起来 —— 那是硕兵
     短腿厚身看着还凑合，主角腿长，竖起来像被钉在墙上。
     这里把坐标系直接建在躺姿上，躺稳时 ang2 = 0，天然是平的。 */
  const ang2 = ang + 1.51;

  ctx.save();
  ctx.translate(x, y - sink * 0.08);
  ctx.scale(dir, 1);
  ctx.rotate(ang2);

  /* 腿：髋 → 膝 → 脚，膝盖微微折 */
  ctx.strokeStyle = '#1b2229';
  ctx.lineWidth = 8;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(2, -4);
  ctx.lineTo(14, -8);
  ctx.lineTo(23, -5);
  ctx.stroke();
  ctx.fillStyle = '#0f1418';
  roundRect(22, -10, 9, 8, 2.5); ctx.fill();      /* 靴子 */

  /* 手臂：一只朝头那边摊出去 */
  ctx.strokeStyle = '#1b2229';
  ctx.lineWidth = 6.5;
  ctx.beginPath();
  ctx.moveTo(-9, -10);
  ctx.lineTo(-18, -3);
  ctx.stroke();

  /* 躯干：背板 + 胸甲两块，和立绘的分块对上 */
  ctx.fillStyle = '#141a20';
  roundRect(-16, -14, 21, 14, 5); ctx.fill();
  ctx.fillStyle = '#212a32';
  roundRect(-14, -13, 12, 8, 3); ctx.fill();
  ctx.fillStyle = '#78e2ff';
  roundRect(-11, -11, 2.4, 2.4, 1.2); ctx.fill();  /* 胸口那一点冷光 */

  /* 头盔：一个球 + 一条目镜缝，没有脸 */
  ctx.fillStyle = '#171e25';
  ctx.beginPath(); ctx.arc(-22, -8, 9.4, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#232c35';
  ctx.beginPath(); ctx.arc(-23, -10, 7.8, Math.PI * 1.02, Math.PI * 1.92); ctx.fill();
  ctx.fillStyle = '#78e2ff';
  roundRect(-27, -9.6, 7, 2.2, 1.1); ctx.fill();
  ctx.restore();

  /* 呼救波纹 */
  const pulse = 0.5 + 0.5 * Math.sin(game.time * 4);
  ctx.strokeStyle = 'rgba(255,110,110,' + (0.14 + pulse * 0.20) + ')';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(x, y - 18, 30 + pulse * 12, 0, Math.PI * 2);
  ctx.stroke();
}

/* ============================================================
   位图干员：六张立绘接进同一套动作层
   ------------------------------------------------------------
   大肥鱼那条位图管线（脖子分段蹲下 / 绕脚底放倒 / 拆腿迈步 / 枪挂掌心）
   对干员同样适用，所以这里**不重写一套动作**，只是把那条管线里写死的
   大肥鱼常数换成一张配置表（CAST_CFG）。动作表现因此天然一致：
   蹲下 0.16s、扑倒 0.24s、步频按 cadence —— 全在 util.js 的动作层里，
   和画哪张图无关。

   和她的三处差别，都是为了「一次配置、六个角色表现一致」：

     · 每人只有一张立绘（垂手站立），没有握枪姿势的第二张 ——
       枪因此挂在腰侧，读作「低姿携行」，不假装端枪。挂点仍然只有一份
       （castAnchor），画枪和算枪口都读它，所以「枪口不在枪管末端」
       在这条路径上不可能发生：两边读的是同一个数。

     · 头身比统一按 34% 切脖子。六张图量出来的值在 24%~39% 之间乱跳，
       用各自的会让蹲下后的身高差最多 8px —— 批量应用就变成「六个人蹲六样」。

     · 拆腿矩形由 tools/cast-art.js 从**鞋子的位置**量出来。裙摆侧边的
       披风和丝带也在腿区那一行里，按整体外框拆会把披风当腿，一迈步
       披风跟着甩。腿片固定 26px 宽、绕鞋心切，上缘往裙摆里伸 16px
       藏切口（先画腿、后画躯干，伸进去那截被裙子盖住）。
   ============================================================ */

/* ==CASTART:BEGIN== */
/* 六张干员立绘，art/cast/*.png 原样内联（tools/gen-castart.js 生成，别手改）。
   192px 高：游戏里画 96px，正好是 2 倍超采样 —— 缩放时不会糊。 */
const CAST_SPRITE_B64 = {
  kimi: 'data:image/png;base64,',
  glm: 'data:image/png;base64,',
  gpt: 'data:image/png;base64,',
  grok: 'data:image/png;base64,',
  gemini: 'data:image/png;base64,',
  claude: 'data:image/png;base64,'
};
/* ==CASTART:END== */
const CAST_SPRITE = {};
for (const _ck in CAST_SPRITE_B64) {
  if (typeof Image === 'undefined') break;
  const _im = new Image();
  _im.src = CAST_SPRITE_B64[_ck];
  CAST_SPRITE[_ck] = _im;
}

/* 六个人共用的一档默认值。全写进每人的配置里，「批量应用」就会退化成
   「六份微调」：改一次枪的大小要改六处，第六处迟早漏掉。 */
const CAST_DEF = {
  vh: 96,            /* 视觉身高：和大肥鱼同档，碰撞盒仍是 58 不动 */
  neck: 0.34,        /* 头/身分界（相对身高） */
  headK: 1.00,       /* 头段**不压**：六张立绘头占比本来就大，压一点就糊脸 */
  bodyK: 0.66,       /* 身段残留 —— 头不压之后，降高全靠这一段 */
  lean: 0.20,        /* 蹲下时上身绕脚底前折的剪切系数 */
  wide: 0.16,        /* 蹲下时髋与裙摆横向撑开 */
  thin: 0.34,        /* 趴下时压薄：正面像两腿左右分开，转平后会张成 V */
  crouchRot: -0.08,  /* 蹲下时两条腿绕髋往前折（负角 = 脚端往 +x 走） */
  handRow: 0.60,     /* 腰侧携行的挂枪点（相对身高，从上往下量） */
  handX: 1.5,        /* 挂点比脚心前移这一点，枪托才不会从背后戳出来 */
  gunK: 0.86,        /* 枪的缩放：这六张头身比接近常人，0.95 会像抱着一门炮 */
  liftK: 1.70        /* 趴下抬升：和 96 高立绘的几何同档（大肥鱼实测 1.74） */
};

const CAST_CFG = {
  kimi: {
    foot: 0.5921, hair: '#dfe6ff',
    leg: {
      front: { sx: 71, sy: 133, sw: 26, sh: 59, cutX0: 71, cutX1: 97, cutY: 149, pivotX: 84, pivotY: 143 },
      back:  { sx: 26, sy: 133, sw: 26, sh: 59, cutX0: 26, cutX1: 52, cutY: 149, pivotX: 39, pivotY: 143 }
    }
  },
  glm: {
    foot: 0.6225, hair: '#3b2f2a',
    leg: {
      front: { sx: 93, sy: 135, sw: 26, sh: 57, cutX0: 93, cutX1: 119, cutY: 151, pivotX: 106, pivotY: 145 },
      back:  { sx: 43, sy: 135, sw: 26, sh: 57, cutX0: 43, cutX1: 69, cutY: 151, pivotX: 56, pivotY: 145 }
    }
  },
  gpt: {
    foot: 0.7162, hair: '#2b2b2b', liftK: 0.93,
    leg: {
      front: { sx: 72, sy: 141, sw: 26, sh: 51, cutX0: 72, cutX1: 98, cutY: 157, pivotX: 85, pivotY: 151 },
      back:  { sx: 56, sy: 141, sw: 26, sh: 51, cutX0: 56, cutX1: 82, cutY: 157, pivotX: 69, pivotY: 151 }
    }
  },
  grok: {
    foot: 0.5262, hair: '#2a2f3a',
    leg: {
      front: { sx: 47, sy: 133, sw: 26, sh: 59, cutX0: 47, cutX1: 73, cutY: 149, pivotX: 60, pivotY: 143 },
      back:  { sx: 26, sy: 133, sw: 26, sh: 59, cutX0: 26, cutX1: 52, cutY: 149, pivotX: 39, pivotY: 143 }
    }
  },
  gemini: {
    /* 蓬发 + 大尾巴：横过来比同批「厚」，1.70 抬不起来，裙摆陷地 5px。
       判据只有一条：test/_action.js ⑥ 的「趴下 / 匍匐」读数，调到 ±3 以内。
       注意方向 —— 读数**正数是陷地、负数是浮空**，加大 liftK 会把数往负方向推。 */
    foot: 0.5333, hair: "#5a4a7a", liftK: 2.06,
    leg: {
      front: { sx: 76, sy: 133, sw: 26, sh: 59, cutX0: 76, cutX1: 102, cutY: 149, pivotX: 89, pivotY: 143 },
      back:  { sx: 42, sy: 133, sw: 26, sh: 59, cutX0: 42, cutX1: 68, cutY: 149, pivotX: 55, pivotY: 143 }
    }
  },
  claude: {
    /* 短裙、腿露在外面，接地的是鞋尖而不是裙摆 —— 1.70 把她抬得浮空 3px，
       反而要往下压。同一个 liftK 在这批图里差了 0.6 个量级，不能取平均值了事。 */
    foot: 0.5873, hair: "#c8b8a0", liftK: 1.46,
    leg: {
      front: { sx: 62, sy: 133, sw: 26, sh: 59, cutX0: 62, cutX1: 88, cutY: 149, pivotX: 75, pivotY: 143 },
      back:  { sx: 41, sy: 133, sw: 26, sh: 59, cutX0: 41, cutX1: 67, cutY: 149, pivotX: 54, pivotY: 143 }
    }
  }
};
for (const _ck2 in CAST_CFG) CAST_CFG[_ck2] = Object.assign({}, CAST_DEF, CAST_CFG[_ck2]);

/* 步幅：这六张的腿比大肥鱼长一倍（腿部露 41 立绘像素 vs 18），
   同一个角度走出的步幅更大，所以步幅角要小一档、抬脚要高一点。 */
const CAST_GAIT_K = {
  stepRot: 0.20, stepLift: 8,
  idleRot: 0.045, idleLift: 3.2,
  airFront: 0.15, airBack: -0.12, airLiftF: 8.0, airLiftB: 9.0
};

function castCfg(look) { return CAST_CFG[look] || null; }
function castReady(look) {
  const im = CAST_SPRITE[look];
  return !!im && im.complete && im.naturalWidth > 0;
}

/* 蹲下时头段 / 身段各自的本地高度（和大肥鱼同一套公式，参数来自配置） */
function castBands(C, cq) {
  const headH = C.vh * C.neck * (1 - cq * (1 - C.headK));
  const bodyH = C.vh * (1 - C.neck) * (1 - cq * (1 - C.bodyK));
  return { headH, bodyH, total: headH + bodyH };
}
/* 任意图内行号 → 本地 y（本地坐标：脚底 = 0、向上为负） */
function castRowY(C, rowFrac, cq) {
  if (cq <= 0.01) return -C.vh + rowFrac * C.vh;
  const b = castBands(C, cq);
  if (rowFrac < C.neck) return -b.total + (rowFrac / C.neck) * b.headH;
  return -b.bodyH + ((rowFrac - C.neck) / (1 - C.neck)) * b.bodyH;
}

/* 枪的挂点：**唯一**一份。画枪（castGunProp）和算枪口（gunAnchor）都读它，
   所以「枪口不在枪管末端」在这条路径上不可能发生。
   look 只有存在姿态图时才用得上（它要按角色查表）—— 六干员和大肥鱼
   还没有姿态图，传 undefined 就一直是老路径。 */
function castAnchor(C, cq, pr, look) {
  const pa = look ? poseArtOf(look, cq || 0, pr || 0) : null;
  if (pa) {
    const hand = poseHand(pa.art, C.vh);
    return {
      hx: hand.x, hy: hand.y,
      K: C.gunK, rec: 1.4, vh: C.vh, liftK: C.liftK, squash: true, poseArt: true
    };
  }
  return {
    hx: C.handX, hy: castRowY(C, C.handRow, cq || 0),
    K: C.gunK, rec: 1.4, vh: C.vh, liftK: C.liftK, squash: true
  };
}

const _castSplit = new Map();
function castLegParts(C, img) {
  return legPartsOf(img, C.leg, img.naturalWidth, _castSplit);
}

const _castTint = new Map();
function castTint(img) {
  if (_castTint.has(img)) return _castTint.get(img);
  const t = whaleTintFor(img);
  _castTint.set(img, t);
  return t;
}

/* 位图通道的枪：枪身和枪口焰。手臂已经画在立绘里，这里只补枪 ——
   再画一只袖子就是第三只手了。back/front 用来分两趟画（枪托在下、机匣在上）。 */
function castGunProp(a, C, cq, lean, part) {
  ctx.save();
  const pitch = whalePitch(a);
  /* 挂点从 castAnchor 拿，不在这里自己算一遍 —— 蹲/趴换成姿态图之后，
     掌心位置由那张图决定，两处各写一份必然对不上。 */
  const an = castAnchor(C, cq, proneK(a), a.look);
  ctx.translate(an.hx, an.hy);
  ctx.rotate(pitch - (lean || 0));
  ctx.scale(C.gunK, C.gunK);
  ctx.translate(-9, -5);              /* 握把在 (9,5)，挪过来咬住掌心 */
  ctx.translate(-kickOf(a), 0);
  const dip = gunDip(a);
  if (dip.rot) ctx.rotate(dip.rot);
  if (dip.dy) ctx.translate(0, dip.dy);
  whaleGunBody(a, part);
  ctx.restore();
}

/* ============================================================
   位图干员本体
   ------------------------------------------------------------
   骨架照抄大肥鱼那条位图分支（同一个顺序：影子 → 残影 → 空翻 → 挤压 →
   镜像 → 倾身 → 起伏 → 放倒 → 拆腿 → 躯干 → 头 → 枪），因为那条路径
   已经在七项动作验收里跑过，换个角色不该换顺序。
   ============================================================ */
function drawCast(a, isBuddy) {
  if (a.dead) return;
  if (a.downed) { drawCastDowned(a); return; }
  const C = CAST_CFG[a.look];
  const img = CAST_SPRITE[a.look];
  /* 图没解码好就退回程序化骨架 —— 干员本来就有一份矢量画法，这是白捡的兜底 */
  if (!C || !img || !img.complete || !img.naturalWidth) { drawAgent(a, isBuddy); return; }

  const h = a.h, sx = a.x - camera.x;
  const facing = Math.cos(a.aim) >= 0 ? 1 : -1;
  const sq = clamp(a.landSquash || 0, 0, 1);
  const t = game.time;

  /* 承托面阴影（离地越高越淡越小，和另外三套画法同一个公式） */
  const under = a.flatShadow ? a.y : surfaceBelow(a.x, a.y);
  const gap = a.flatShadow ? 0 : clamp((under - a.y) / 190, 0, 1);
  const sk = 1 - gap * 0.68;
  ctx.fillStyle = 'rgba(0,0,0,' + (0.42 * sk).toFixed(3) + ')';
  ctx.beginPath();
  ctx.ellipse(sx + facing * 2, under + 1, (16 + 24 * proneK(a)) * sk, 4.6 * sk, 0, 0, Math.PI * 2);
  ctx.fill();

  /* 冲刺残影 */
  if ((a.dashTime || 0) > 0) {
    const dir = Math.sign(a.vx) || facing;
    for (let i = 3; i >= 1; i--) {
      ctx.globalAlpha = 0.10 * i;
      ctx.fillStyle = C.hair;
      roundRect(sx - dir * i * 9 - 8, a.y - h * 0.86, 16, h * 0.78, 7);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* 二段跳空翻：和人类士兵共用 AIRJUMP_FLIP 时钟 */
  let flipK = 0, flipAng = 0;
  if ((a.airJumpT || 0) > 0) {
    flipK = clamp(1 - a.airJumpT / AIRJUMP_FLIP, 0, 1);
    const e = flipK * flipK * (3 - 2 * flipK);
    flipAng = (a.flipDir || facing) * Math.PI * 2 * e;
  }
  const pivot = h * 0.56;
  if (flipK > 0 && flipK < 0.82) {
    const al = 0.34 * (1 - flipK / 0.82);
    ctx.strokeStyle = 'rgba(180,220,255,' + al.toFixed(3) + ')';
    ctx.lineWidth = 2.2;
    ctx.lineCap = 'round';
    for (let i = 0; i < 2; i++) {
      const a0 = flipAng - 1.7 - i * 0.5;
      ctx.beginPath();
      ctx.arc(sx, a.y - pivot, h * 0.42 - i * 5, a0, a0 + 1.15);
      ctx.stroke();
    }
  }

  const blink = a.invuln > 0 && Math.floor(a.invuln * 18) % 2 === 0;

  ctx.save();
  ctx.translate(sx, a.y);
  ctx.scale(1 + sq * 0.11, 1 - sq * 0.15);
  if (flipAng) {
    ctx.translate(0, -pivot);
    ctx.rotate(flipAng);
    ctx.translate(0, pivot);
  }
  if (blink) ctx.globalAlpha = 0.5;

  const cq = cqEff(a);
  /* 蹲到底 / 趴到底有专门画的图就不放倒、不压薄、不拆头 —— 见 drawHero 同一段。
     干员还没出姿态图，这里是 null，走的完全是老路径。 */
  const pa = poseArtOf(a.look, cq, proneK(a));
  const pp = pa ? POSE_FLAT : pronePose(a, C.vh, C.liftK);

  const natW = img.naturalWidth, natH = img.naturalHeight;
  const spH = C.vh, spW = spH * (natW / natH);
  const dx = -spW * C.foot;

  /* 镜像：素材只画了朝右一种，朝左全靠 scale(-1,1) 翻 */
  ctx.scale(facing, 1);

  const mo = motionOf(a);
  const lean = whaleLean(a) + mo.lean;
  if (lean) ctx.rotate(lean);
  if (mo.bob) ctx.translate(0, -mo.bob);

  const lying = pp.pr > 0.002;
  const gunLean = lean + (lying ? pp.ang : 0);
  
  const bodyXform = () => {
    if (!lying) return;
    ctx.translate(pp.shift, -pp.lift);
    ctx.rotate(pp.ang);
  };

  /* 身段 / 整图。
     趴下时**不拆头** —— 这一条和大肥鱼不一样，理由只有一句：
     这六张立绘是正面像（同时看得到两只眼、两条腿），大肥鱼那张是侧向
     站姿、脸朝 +x。侧面像转 85° 会让脸的朝向跟着扎进土里，所以她要
     把头单独抬回来；正面像转完脸仍然朝着镜头，拆头反而只会在脖子上
     留一道横穿的缝（头发是整片画的，切口宽度等于整个画幅）。 */
  const blit = (im) => {
    if (!im) return;
    if (lying || cq <= 0.01) {
      ctx.save();
      if (lying) ctx.scale(1, 1 - (C.thin || 0.26) * pp.pr);
      ctx.drawImage(im, dx, -spH, spW, spH);
      ctx.restore();
      return;
    }
    const b = castBands(C, cq);
    /* 折 + 撑（理由见 whale 那边 98 行）：shear 绕脚底把上身往前折，
       髋部横向撑开，头段一点不缩放 —— 蹲是「折」，不是「缩」 */
    ctx.save();
    ctx.transform(1, 0, -cq * (C.lean || 0.10), 1, 0, 0);
    ctx.scale(1 + cq * (C.wide || 0.10) * 0.55, 1);
    ctx.save();
    ctx.scale(1 + cq * (C.wide || 0.10) * 0.45, 1);
    ctx.drawImage(im, 0, natH * C.neck, natW, natH * (1 - C.neck),
                  dx, -b.bodyH, spW, b.bodyH + 0.5);
    ctx.restore();
    ctx.drawImage(im, 0, 0, natW, natH * C.neck,
                  dx, -b.total, spW, b.headH + 0.5);
    ctx.restore();
  };


  /* 腿：拆件后单独摆。蹲下时不拆 —— 蹲姿是两段压缩画的，
     腿片塞不进那套坐标，而蹲着本来也不该抖腿。 */
  const parts = castLegParts(C, img);
  /* 趴下时不拆件：躺倒的腿跟着身体转，不摆步态（判据见 drawWhaleGirl） */
  const splitOn = !!parts && cq <= 0.02 && !lying;
  const u = spW / natW;                 /* 立绘像素 → 屏幕像素 */
  const gait = gaitFor(a, t, cq, CAST_GAIT_K);

  const blitLeg = (key, useSil) => {
    const R = C.leg[key], g = gait[key];
    const cv = useSil ? whalePartSil(parts, key) : parts.legs[key];
    if (!cv) return;
    const ox = dx + R.sx * u;
    const oy = -spH + R.sy * u - g.lift * u;
    const px = (R.pivotX - R.sx) * u, py = (R.pivotY - R.sy) * u;
    ctx.save();
    ctx.translate(ox + px, oy + py);
    /* 蹲下时腿绕髋往前折一点 —— 短裙角色（奇米她们露腿）如果不折，
       蹲下只读作「腿变短」；折一下才有膝盖往前顶的意思。
       whale 那边不给负不加这个，她裙摆盖到脚踝，腿一动就露馅。 */
    ctx.rotate(g.rot + cq * (C.crouchRot || 0));
    ctx.translate(-px, -py);
    ctx.drawImage(cv, 0, 0, cv.width, cv.height, 0, 0, R.sw * u, R.sh * u);
    ctx.restore();
  };

  if (pa) {
    /* 姿态图。枪仍然分 back / front 两趟，理由同 drawHero；
       腿的形变也共用 poseWarped，六干员铺好姿态图之后不用再改这里。 */
    const gm = poseGeom(pa.art, C.vh);
    const warp = poseWarpOf(a);
    castGunProp(a, C, cq, gunLean, 'back');
    poseWarped(pa.im, gm, warp);
    castGunProp(a, C, cq, gunLean, 'front');
    if (a.flash > 0) {
      ctx.globalAlpha = Math.min(0.5, a.flash * 2.2);
      poseWarped(castTint(pa.im), gm, warp);
      ctx.globalAlpha = 1;
    }
  } else if (splitOn) {
    ctx.save(); bodyXform();
    castGunProp(a, C, cq, gunLean, 'back');   /* 枪托塞在身体后面 */
    blitLeg('back', false);
    blitLeg('front', false);
    blit(parts.body);
    ctx.restore();
    /* 'front' 这趟（机匣 + 枪管）必须排在躯干之后、且留在 bodyXform 里：
       排后面 —— 趴下时枪口正好在脸颊高度，画在下面会被脸整个吞掉；
       留在 bodyXform 里 —— gunLean 含 +pp.ang、castGunProp 内部再减掉，
       一进一出抵平，净角度 = pitch；放外面画那 -pp.ang 没人抵，枪管会竖起来。 */
    ctx.save(); bodyXform();
    castGunProp(a, C, cq, gunLean, 'front');
    ctx.restore();
  } else {
    ctx.save(); bodyXform();
    castGunProp(a, C, cq, gunLean, 'back');
    blit(img);
    ctx.restore();
    ctx.save(); bodyXform();
    castGunProp(a, C, cq, gunLean, 'front');
    ctx.restore();
  }

  /* 受击红闪：用 sprite 的 alpha 当遮罩，不能直接 fillRect（会把关卡一起染红）。
     姿态图那一支在上面已经红过了，这里要跳过 —— 叠两遍会变成 0.75 的一团橙。 */
  if (a.flash > 0 && !pa) {
    ctx.globalAlpha = Math.min(0.5, a.flash * 2.2);
    ctx.save(); bodyXform();
    if (splitOn) {
      blitLeg('back', true);
      blitLeg('front', true);
      blit(whalePartSil(parts, 'body'));
    } else {
      blit(castTint(img));
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }
  ctx.restore();

  /* 名牌：位图比碰撞盒高，锚点按视觉高度重算，否则会被头发盖住 */
  if (isBuddy) {
    const topY = pp.pr > 0.02 ? a.y - PRONE_PLATE : a.y + castRowY(C, 0, cq) - 8;
    drawBuddyPlate(a, sx, topY);
  }
}

/* 倒地：站姿立绘绕脚底转 87° 读成躺平（和 whale/hero 同一个做法） */
function drawCastCorpse(c, ang, sink, fade) {
  const C = CAST_CFG[c.look], img = CAST_SPRITE[c.look];
  if (!C || !img || !img.complete || !img.naturalWidth) return false;
  const spH = C.vh, spW = spH * (img.naturalWidth / img.naturalHeight);
  const dir = c.dir || 1;
  ctx.save();
  ctx.globalAlpha = fade === undefined ? 1 : fade;
  ctx.translate(c.x - camera.x, c.y);
  ctx.translate(0, -sink * 0.1);
  ctx.rotate(dir * ang);
  ctx.scale(dir, 0.88);      /* 压扁 0.88：躺着的人从侧面看本来就薄 */
  ctx.drawImage(img, -spW * C.foot, -spH, spW, spH);
  ctx.restore();
  return true;
}

function drawCastDowned(a) {
  const x = a.x - camera.x, y = a.y;
  const dir = Math.cos(a.aim || 0) >= 0 ? 1 : -1;

  ctx.fillStyle = 'rgba(110,24,24,0.42)';
  ctx.beginPath(); ctx.ellipse(x + dir * 6, y + 1, 42, 9, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath(); ctx.ellipse(x, y + 2, 30, 6, 0, 0, Math.PI * 2); ctx.fill();

  const dc = actDownedCurve(a);
  if (!drawCastCorpse({ x: a.x, y: a.y, look: a.look, dir: dir }, -dc.ang, dc.sink, 1)) {
    drawAgentDowned(a);
    return;
  }

  const pulse = 0.5 + 0.5 * Math.sin(game.time * 4);
  ctx.strokeStyle = 'rgba(255,110,110,' + (0.16 + pulse * 0.22) + ')';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(x, y - 18, 30 + pulse * 12, 0, Math.PI * 2);
  ctx.stroke();
}

/* ============================================================
   干员（AI 角色）程序化 painter
   ------------------------------------------------------------
   奇米（Kimi）/ 知源（GLM）/ 枢机（GPT）不是位图，全部由 CHAR_LIST
   里的几个颜色驱动同一套骨架画出：
     coat 外套 / cloth 内衬 / hair 头发 / hairStyle 发型 / visor 目镜 / color 主色
   和大肥鱼、主角共用同一条规矩 —— 脚底为原点、朝 +x、
   视觉身高 96（AGENT_VH），碰撞盒仍是 58，换人不换手感。
   骨架比位图版简单一层（没有拆腿），因为这三张脸的关键识别点是
   「目镜颜色 + 发型剪影」，而不是衣褶。
   ============================================================ */

const AGENT_VH = 96;
const AGENT_GAIT_K = {
  stepRot: 0.20, stepLift: 11,
  idleRot: 0.042, idleLift: 3.0,
  airFront: 0.16, airBack: -0.13, airLiftF: 8.0, airLiftB: 9.0
};

/* 趴下抬升系数。干员的骨架是程序化画的，胸腹比标准「半个身厚」薄，
   按标准抬会整块浮在地面上 5px（脚都碰不到地）。0.61 是实测值，
   改骨架就得重新量（见 test/_action.js ⑥）。 */
const AGENT_LIFT_K = 0.61;

/* 由 look 反查设定：角色可能被改名，但 look 是稳定的 */
function agentLookDef(a) {
  if (typeof CHAR_LIST === 'undefined') return null;
  for (let i = 0; i < CHAR_LIST.length; i++) {
    if (CHAR_LIST[i].look === a.look) return CHAR_LIST[i];
  }
  return null;
}

/* 干员的枪。挂点和主角同一套算法（掌心咬住握把），只是枪更小一号：
   这三个人视觉身高和主角一样是 96，但骨架更细，0.82 是「顺手的一把枪」。 */
function agentGunProp(a, part, lean) {
  ctx.save();
  const pitch = whalePitch(a);
  ctx.translate(2.5, -55);
  ctx.rotate(pitch - (lean || 0));
  ctx.scale(0.82, 0.82);
  ctx.translate(-9, -5);                                          /* 握把咬住掌心 */
  ctx.translate(-kickOf(a, { rec: 1.4 }), 0);                     /* 后坐（干员 1.4） */
  const dip = gunDip(a);
  if (dip.rot) ctx.rotate(dip.rot);                               /* 换弹：枪口垂下 */
  if (dip.dy) ctx.translate(0, dip.dy);
  whaleGunBody(a, part);
  ctx.restore();
}

/* 一条腿：髋 → 膝 → 踝，末端一只短靴。rot 是髋关节摆角，lift 是抬脚量 */
function agentLeg(rot, lift, clothCol, bootCol, back) {
  const kx = back ? -3.2 : 2.2;
  const ax = back ? -5.0 : 3.2;
  ctx.save();
  ctx.translate(0, -40);                 /* 髋 */
  ctx.rotate(rot);
  ctx.strokeStyle = clothCol;
  ctx.lineWidth = 9;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(kx, 19);                    /* 膝 */
  ctx.lineTo(ax, 36 - lift);             /* 踝 */
  ctx.stroke();
  /* 靴：贴地那只脚要压到 y≈+1，才和落影咬得住 */
  ctx.fillStyle = bootCol;
  roundRect(ax - 5, 34 - lift, 14, 8, 3);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.07)';
  roundRect(ax - 3.4, 35 - lift, 11, 2, 1);
  ctx.fill();
  ctx.restore();
}

/* 发型：只画剪影，落在头后面。
   bob   = 齐肩短发，两侧各一团包住下颌
   pony  = 单马尾，从后脑甩出去一条，会随速度飘
   crop  = 贴头短发，只有后颈一点 */
function agentHair(def, t, speed) {
  const hair = def.hair || '#dfe6ff';
  const style = def.hairStyle || 'bob';
  ctx.fillStyle = hair;
  if (style === 'pony') {
    const sway = Math.sin(t * 5) * 2.2 - Math.min(6, speed * 0.06);
    ctx.beginPath();
    ctx.moveTo(-6, -86);
    ctx.quadraticCurveTo(-20 + sway, -80, -22 + sway * 1.6, -60);
    ctx.quadraticCurveTo(-16, -64, -9, -74);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(0,0,0,0.22)';
    ctx.beginPath();
    ctx.moveTo(-8, -84);
    ctx.quadraticCurveTo(-18 + sway, -78, -20 + sway * 1.6, -64);
    ctx.quadraticCurveTo(-15, -68, -9, -76);
    ctx.closePath();
    ctx.fill();
  } else if (style === 'bob') {
    ctx.beginPath();
    ctx.moveTo(-9, -92);
    ctx.quadraticCurveTo(-15, -84, -13.5, -70);
    ctx.lineTo(-4, -74);
    ctx.quadraticCurveTo(-6, -84, -2, -90);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.10)';
    ctx.beginPath();
    ctx.moveTo(-10.5, -88);
    ctx.quadraticCurveTo(-13, -80, -12, -72);
    ctx.lineTo(-9.5, -73);
    ctx.quadraticCurveTo(-10.5, -81, -8, -87);
    ctx.closePath();
    ctx.fill();
  } else {
    /* crop：后颈一小撮 */
    ctx.beginPath();
    ctx.moveTo(-8, -89);
    ctx.quadraticCurveTo(-12, -82, -9.5, -76);
    ctx.lineTo(-3, -79);
    ctx.closePath();
    ctx.fill();
  }
}

function drawAgent(a, isBuddy) {
  if (a.dead) return;
  if (a.downed) { drawAgentDowned(a); return; }

  const def = agentLookDef(a) || {};
  const sx = (a.sx !== undefined) ? a.sx : a.x - camera.x;
  const facing = Math.cos(a.aim) >= 0 ? 1 : -1;
  /* 蹲 / 趴互斥：趴下时蹲姿被 cqEff 压成 0，横向补肉、纵向压扁同时收工 */
  const cq = cqEff(a);
  const pp = pronePose(a, AGENT_VH, AGENT_LIFT_K);
  const lying = pp.pr > 0.002;
  const sq = clamp(a.landSquash || 0, 0, 1);
  const t = game.time;
  const speed = Math.abs(a.vx || 0);

  const coat = def.coat || a.trim || '#1b2340';
  const cloth = def.cloth || '#2b3357';
  const bootCol = '#12161b';
  const visor = def.visor || a.bodyColor || '#9ab6ff';
  const accent = def.color || visor;

  /* 承托面阴影（离地越高越淡越小，和大肥鱼 / 主角同一套公式；
     flatShadow 用于菜单立绘） */
  const under = a.flatShadow ? a.y : surfaceBelow(a.x, a.y);
  const gap = a.flatShadow ? 0 : clamp((under - a.y) / 190, 0, 1);
  const sk = 1 - gap * 0.68;
  ctx.fillStyle = 'rgba(0,0,0,' + (0.42 * sk).toFixed(3) + ')';
  ctx.beginPath();
  ctx.ellipse(sx + facing * 2, under + 1, (16 + 26 * proneK(a)) * sk, 4.7 * sk, 0, 0, Math.PI * 2);
  ctx.fill();

  /* 冲刺残影：用外套色压暗，比纯黑块更像「人跑过去的影子」 */
  if ((a.dashTime || 0) > 0) {
    const dir = Math.sign(a.vx) || facing;
    for (let i = 3; i >= 1; i--) {
      ctx.globalAlpha = 0.09 * i;
      ctx.fillStyle = coat;
      roundRect(sx - dir * i * 9 - 8, a.y - 78, 16, 66, 7);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  const mo = motionOf(a);
  const lean = whaleLean(a) + mo.lean;
  const gait = gaitFor(a, t, cq, AGENT_GAIT_K);

  ctx.save();
  ctx.translate(sx, a.y);
  /* 落地挤压：蹲得越深纵向压得越狠，同时横向补一点肉，重心才不飘 */
  const squash = 1 - cq * 0.30 + sq * 0.06;
  ctx.scale(facing * (1 + cq * 0.08), squash);
  if (lean) ctx.rotate(lean);
  if (mo.bob) ctx.translate(0, -mo.bob);

  /* 趴下：整副骨架绕脚底放倒。骨架是照着「站立 96 高」写的，
     放倒之后头会横着甩出去一米，所以重心同时往回挪（pp.shift）。
     枪要扣掉同样的角度，否则枪管跟着身体一起竖起来，像在朝天开枪。 */
  if (lying) {
    ctx.translate(pp.shift, -pp.lift);
    ctx.rotate(pp.ang);
  }
  const gunLean = lean + (lying ? pp.ang : 0);

  /* ---- 后侧肢体（先画，被躯干压住） ---- */
  agentLeg(gait.back.rot, gait.back.lift, '#242b33', '#0e1216', true);
  agentGunProp(a, 'back', gunLean);
  /* 后臂 */
  ctx.strokeStyle = '#242b33';
  ctx.lineWidth = 8;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-1, -62);
  ctx.lineTo(-5 - Math.min(3, speed * 0.03), -50);
  ctx.stroke();

  /* ---- 外套下摆：盖住大腿根，是「军装」和「紧身衣」的分界线 ---- */
  ctx.fillStyle = coat;
  ctx.beginPath();
  ctx.moveTo(-9, -50);
  ctx.lineTo(9, -50);
  ctx.lineTo(7.5, -34);
  ctx.lineTo(-8, -34);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.20)';
  ctx.beginPath();
  ctx.moveTo(-9, -50);
  ctx.lineTo(-1, -50);
  ctx.lineTo(-1, -34);
  ctx.lineTo(-8, -34);
  ctx.closePath();
  ctx.fill();

  /* ---- 躯干 ---- */
  ctx.fillStyle = cloth;
  roundRect(-8, -72, 16, 24, 5);
  ctx.fill();
  /* 胸甲：比内衬亮一档，前襟斜切一刀，读起来是「有护具」而不是「一块布」 */
  ctx.fillStyle = coat;
  ctx.beginPath();
  ctx.moveTo(-8, -70);
  ctx.lineTo(8, -70);
  ctx.lineTo(8, -56);
  ctx.lineTo(-8, -60);
  ctx.closePath();
  ctx.fill();
  /* 弹匣袋两个 */
  ctx.fillStyle = 'rgba(0,0,0,0.28)';
  roundRect(-5.5, -55, 5, 6, 1.5); ctx.fill();
  roundRect(1.0, -55, 5, 6, 1.5); ctx.fill();
  /* 胸口状态灯：三张脸靠它区分「谁的胸甲」 */
  ctx.fillStyle = visor;
  ctx.globalAlpha = 0.65 + 0.35 * Math.sin(t * 3.1);
  roundRect(2.2, -67, 2.6, 2.6, 1.3);
  ctx.fill();
  ctx.globalAlpha = 1;

  /* 肩甲：主色的一小条，落在远端肩上 */
  ctx.fillStyle = accent;
  ctx.globalAlpha = 0.55;
  roundRect(-9.5, -73.5, 7.5, 5, 2);
  ctx.fill();
  ctx.globalAlpha = 1;

  /* ---- 前侧肢体 ---- */
  agentLeg(gait.front.rot, gait.front.lift, cloth, bootCol, false);
  /* 前臂：肘在腰侧，手握在枪的握把上（和 agentGunProp 的挂点对齐） */
  ctx.strokeStyle = cloth;
  ctx.lineWidth = 7.5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(4, -64);
  ctx.lineTo(6, -56);
  ctx.lineTo(3.5, -53);
  ctx.stroke();

  /* ---- 头 ---- */
  /* 脖子 */
  ctx.fillStyle = '#1a2028';
  roundRect(-2.5, -77, 5, 6, 2);
  ctx.fill();
  /* 头发在头后面先铺一层 */
  agentHair(def, t, speed);
  /* 头盔：一个略扁的球 + 一道目镜缝，全程没有脸 */
  ctx.fillStyle = coat;
  ctx.beginPath();
  ctx.ellipse(0, -85, 9.2, 10.4, 0, 0, Math.PI * 2);
  ctx.fill();
  /* 头盔顶盖：亮一档，给出球面感 */
  ctx.fillStyle = 'rgba(255,255,255,0.10)';
  ctx.beginPath();
  ctx.ellipse(-1.6, -89, 6.6, 5.4, 0, Math.PI * 1.02, Math.PI * 1.94);
  ctx.fill();
  /* 目镜：宽 11、高 3，横贯整张脸 —— 这是 96px 上唯一还认得出的五官 */
  ctx.fillStyle = '#0b1016';
  roundRect(-6.5, -86.5, 13, 6, 3);
  ctx.fill();
  ctx.fillStyle = visor;
  roundRect(-6.0, -85.4, 12, 3.2, 1.6);
  ctx.fill();
  /* 目镜高光：一道白线，让人一眼知道那是「亮的」而不是「画上去的色块」 */
  ctx.fillStyle = 'rgba(255,255,255,0.55)';
  roundRect(-5.2, -85.0, 8.6, 0.9, 0.45);
  ctx.fill();
  /* 呼吸面罩：下半张脸一块小梯形，把「没有嘴」讲清楚 */
  ctx.fillStyle = '#161d25';
  ctx.beginPath();
  ctx.moveTo(-5.2, -79.6);
  ctx.lineTo(6.4, -79.6);
  ctx.lineTo(4.6, -74.6);
  ctx.lineTo(-3.6, -74.6);
  ctx.closePath();
  ctx.fill();
  /* 面罩上的滤芯小点（知源是这一族里唯一的重装，给它多加一道侧灯） */
  ctx.fillStyle = accent;
  ctx.globalAlpha = 0.8;
  roundRect(4.4, -78.2, 1.8, 1.8, 0.9);
  ctx.fill();
  ctx.globalAlpha = 1;

  /* ---- 枪（压在手上） ---- */
  agentGunProp(a, 'front', gunLean);

  ctx.restore();

  /* 名牌：干员当 AI 战友时才需要，玩家自己不加 */
  if (isBuddy && typeof drawBuddyPlate === 'function') {
    /* 趴下时视觉顶边只剩一个身厚，名牌改挂受击盒顶，别悬在一米高的空中 */
    drawBuddyPlate(a, sx, lying ? a.y - PRONE_PLATE : a.y - AGENT_VH - 6);
  }
}

function drawAgentDowned(a) {
  const def = agentLookDef(a) || {};
  const x = (a.sx !== undefined) ? a.sx : a.x - camera.x, y = a.y;
  const dir = Math.cos(a.aim || 0) >= 0 ? 1 : -1;
  const coat = def.coat || a.trim || '#1b2340';
  const cloth = def.cloth || '#2b3357';
  const visor = def.visor || a.bodyColor || '#9ab6ff';

  /* 血泊 */
  ctx.fillStyle = 'rgba(110,24,24,0.40)';
  ctx.beginPath(); ctx.ellipse(x + 6 * dir, y + 1, 38, 8.5, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.30)';
  ctx.beginPath(); ctx.ellipse(x, y + 2, 28, 5.5, 0, 0, Math.PI * 2); ctx.fill();

  /* 倒地曲线现在只有一条（util.js 的 actDeathCurve）：膝盖先软 →
     上身歪出去 → 落地余震。三个人原本各抄一份、数字其实一模一样，
     抄错一个符号就是「倒向另一边」。参数集中在这里，是因为这三个
     人的重量和身高是同一档；大肥鱼另有自己的一份（在下面）。 */
  const dc = actDownedCurve(a);
  const ang = -dc.ang, sink = dc.sink;

  /* 掉在地上的枪 */
  ctx.save();
  ctx.translate(x + 28 * dir, y - 2);
  ctx.scale(dir, 1);
  ctx.rotate(0.10);
  ctx.fillStyle = '#2c343c';
  roundRect(-15, -3, 32, 5, 2); ctx.fill();
  ctx.fillStyle = '#454f59';
  roundRect(-2, -6, 11, 5, 1.5); ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(x, y - sink * 0.08);
  ctx.scale(dir, 1);
  ctx.rotate(ang + 1.51);

  /* 腿 */
  ctx.strokeStyle = cloth;
  ctx.lineWidth = 8;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(2, -5);
  ctx.lineTo(13, -8);
  ctx.lineTo(21, -5);
  ctx.stroke();
  ctx.fillStyle = '#0e1216';
  roundRect(20, -10, 9, 8, 2.5); ctx.fill();

  /* 摊出去的手臂 */
  ctx.strokeStyle = cloth;
  ctx.lineWidth = 6.5;
  ctx.beginPath();
  ctx.moveTo(-9, -10);
  ctx.lineTo(-18, -3);
  ctx.stroke();

  /* 躯干 */
  ctx.fillStyle = coat;
  roundRect(-16, -14, 21, 14, 5); ctx.fill();
  ctx.fillStyle = cloth;
  roundRect(-14, -12, 12, 7, 3); ctx.fill();
  ctx.fillStyle = visor;
  roundRect(-11, -11, 2.4, 2.4, 1.2); ctx.fill();

  /* 头盔 + 目镜（躺下后目镜仍然朝上，才认得出是谁） */
  ctx.fillStyle = coat;
  ctx.beginPath(); ctx.arc(-22, -8, 9.2, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#0b1016';
  roundRect(-29, -10.4, 11, 5, 2.5); ctx.fill();
  ctx.fillStyle = visor;
  roundRect(-28.4, -9.6, 9.6, 3, 1.5); ctx.fill();
  ctx.restore();

  /* 呼救波纹 */
  const pulse = 0.5 + 0.5 * Math.sin(game.time * 4);
  ctx.strokeStyle = 'rgba(255,110,110,' + (0.14 + pulse * 0.20) + ')';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(x, y - 18, 30 + pulse * 12, 0, Math.PI * 2);
  ctx.stroke();
}
